object Workspace {
  import Main._

  /**
    * O(√x)
    */
  def divisors(x: Int): Array[Int] = {
    import scala.collection.mutable.ArrayBuffer
    val pre = ArrayBuffer[Int]()
    val post = ArrayBuffer[Int]()
    REP(math.sqrt(x).toInt, 1) { d =>
      if (x % d == 0) {
        pre += d
        if (d * d != x) post += x / d
      }
    }

    val res = Array.ofDim[Int](pre.length + post.length)
    REP(pre.length)(i => res(i) = pre(i))
    val preLen = pre.length
    val postLen = post.length
    REP(postLen)(i => res(i + preLen) = post(postLen - 1 - i))
    res
  }
}

class Main(out: java.io.PrintWriter, sc: Main.InputReader) {
  import sc._
  import Main._
  import java.util.Arrays.sort

  import scala.collection.mutable
  import math.{abs, max, min}
  import mutable.ArrayBuffer
  import Workspace._

  // toIntとか+7とかするならvalにしろ
  final private[this] val MOD = 998244353

  val pow2 = Array.ofDim[Long](32)
  pow2(0) = 1
  REP(pow2.length - 1)(i => pow2(i + 1) = pow2(i) * 2 % MOD)

  def solve(): Unit = {
    val n = ni()
    val x = ns(n).map(_-'0')
    val d = divisors(2 * n)
    val d_rev = Array.fill[Int](4e5.toInt)(-1)
    REP(d.length) { i =>
      d_rev(d(i)) = i
    }
    val cnt = Array.ofDim[Long](d.length) // 約数毎の出現数

    // 先頭dを固定した時残りに~d, d, ~d, dのように並べることができるか
    def isJust(d: Int): Boolean = {
      REP(n / d - 1, 1) { i =>
        val xor = i&1
        REP(d) { j =>
          // d*i+jまで一致していて、後はlessの場合
          if (x(d * i + j) == 1 && x(j) == xor) return true

          if (x(j) != (x(d * i + j)^xor)) return false
        }
      }
      true
    }

    def cnt2n = {
      var res = 1L
      REP(n) { i =>
        if (x(i) == 1) {
          res += pow2(n - 1 - i)
        }
      }
      res % MOD
    }

    REP(d.length) { i =>
      val dd = d(i)
      if (dd % 2 == 0 && 2 * n / dd % 2 == 1 && dd <= n) {
        REP(dd / 2) { j =>
          if (x(j) == 1) {
            // lessを数える
            debug(s"less $dd $j")
            cnt(i) += pow2(dd / 2 - 1 - j)
          }
        }
        if (isJust(dd / 2)) {
          debug(s"just $dd")
          cnt(i) += 1
        }
        cnt(i) %= MOD
      }

      // 約数包除
      var k = dd * 2
      while(k <= 2 * n) {
        if (d_rev(k) != -1) cnt(d_rev(k)) = (MOD + cnt(d_rev(k)) - cnt(i)) % MOD
        k += dd
      }
    }
    cnt(d_rev(2 * n)) = (cnt(d_rev(2 * n)) + cnt2n) % MOD
    debug(d)
    debug(cnt)
    var ans = 0L
    REP(d.length) { i =>
      ans = (ans + d(i).toLong * cnt(i)) % MOD
    }
    out.println(ans)
  }
}

