void solve() {
    cin >> n >> x;
    for (int times = 1; times <= n; ++times)
        if (n % times == 0 && times % 2 == 1) {
            int len = n / times;
            string s = x.substr(0, len);
            for (char c : s)
                cnt[times] = (2 * cnt[times] + c - '0') % MOD;
            string invs = s;
            for (char &c : invs)
                c ^= 1;
            string t;
            for (int i = 0; i < times; ++i)
                if (~i & 1)
                    t += s;
                else
                    t += invs;
            if (t <= x)
                cnt[times] = (cnt[times] + 1) % MOD;
        }
    int ans = 0;
    for (int i = n; i >= 1; --i)
        if (n % i == 0 && i % 2 == 1) {
            for (int j = 3 * i; j <= n; j += 2 * i)
                if (n % j == 0)
                    cnt[i] = (cnt[i] - cnt[j] + MOD) % MOD;
            ans = (ans + 1ll * cnt[i] * n / i) % MOD;
        }
    cout << 2 * ans % MOD << "\n";
}
