vector<pair<LL, LL>> prime_factorization(LL x) {
	assert(x > 0);
	vector<pair<LL, LL>> f;
	for(LL i = 2; i <= x; i++) {
		if(i * i > x) { i = x; }
		if(x % i == 0) {
			f.EB(i, 0);
			while(x % i == 0) { f.back().SE++; x /= i; }
		}
	}
	return f;
}

vector<LL> divisors(LL x) {
	auto pf = prime_factorization(x);
	vector<LL> d = { 1 };
	for(auto e: pf) {
		int ds = d.size();
		inc(i, ds) {
			LL v = d[i];
			inc(j, e.SE) { v *= e.FI; d.PB(v); }
		}
	}
	sort(ALL(d));
	return d;
}

typedef ModInt<998244353> MI;

int n;
string x;
vector<LL> di;

MI mu[200001];
void mumu(LL x) {
	auto pf = prime_factorization(x);
	RF(e, pf) { if(e.SE > 1) { return; } }
	mu[x] = (SI(pf) % 2 == 0 ? +1 : -1);
}

MI f[200001];
void ff(int d) {
	if(n % d != 0) { return; }
	int B = n / d;
	if(B % 2 == 0) { return; }

	MI ans = 0;
	inc(i, d) {
		ans *= 2;
		ans += (x[i] - '0');
	}

	string s = x.substr(0, d);
	string t = s;
	inc(i, d) { t[i] = (t[i] == '0' ? '1' : '0'); }

	string u = s;
	inc(i, (B - 1) / 2) { u += t + s; }
	assert(SI(x) == SI(u));
	if(u <= x) { ans += 1; }

	f[d] = ans;
}

MI g(int d) {
	if(n % d != 0) { return 0; }
	int B = n / d;
	if(B % 2 == 0) { return 0; }

	MI ans = 0;
	RF(e, di) {
		if(d % e == 0) { ans += mu[d / e] * f[e]; }
	}
	return ans;
}

int main() {
	cin >> n >> x;

	di = divisors(n);
	inc1(d, n) { ff(d); }
	inc1(d, n) { mumu(d); }

	MI ans = 0;
	inc1(d, n) { ans += 2 * d * g(d); }

	cout << ans << endl;

	return 0;
}

