map<ll,ll> moe;
void cal_moe(ll n){
	vector<ll> p;
	for(ll i=2;i*i<=n;i++){
		if(n%i==0){
			p.push_back(i);
			while(n%i==0)n/=i;
		}
	}
	if(n!=1)p.push_back(n);
	ll m=p.size();
	REP(i,1<<m){
		ll mo=1,d=1;
		REP(j,m){
			if((i>>j)&1){
				mo*=-1;
				d*=p[j];
			}
		}
		moe[d]=mo;
	}
}

