  for (int i = 1; i <= n; i++) {
    if (n % i == 0 && (n / i) % 2 == 1) div.push_back(i);
  }
  int m = div.size();
  vector<ModInt> w(m);
  for (int i = m - 1; i >= 0; i--) {
    w[i] = 2 * div[i];
    for (int j = i + 1; j < m; j++) {
      if (div[j] % div[i] == 0 && (div[j] / div[i]) % 2 == 1) w[i] -= w[j];
    }
  }
  ModInt ans = 0;
  for (int i = 0; i < m; i++) {
    ModInt c = 0;
    for (int j = 0; j < div[i]; j++) {
