ll calc(int num){
    int cyc=N/num;
    string g=X.substr(0, cyc), h;
    ll res=0, now=1;
    for(int i=cyc-1; i>=0; --i){
        if(g[i]=='1') res=(res+now)%mod;
        now=(now*2)%mod;
    }
    if(num==1){
        res=(res+1)%mod;
        return res;
    }
    for(int i=0; i<cyc; ++i){
        if(g[i]=='0') h += '1';
        else h += '0';
    }
    for(int i=1; i<num; ++i){
        string subs=X.substr(i*cyc, cyc);
        if(i%2==1){
            if(h!=subs){
                if(h<subs) res=(res+1)%mod;
                break;
            }
        }else{
            if(g!=subs){
                if(g<subs) res=(res+1)%mod;
                break;
            }
            if(i+1==num) res=(res+1)%mod;
        }
    }
    return res;
}

