ll solve(int d, int n, string x) {
	for (int i = 0; i < n; ++i) {
		g[i].clear();
	}
	for (int i = 0; i < n; ++i) {
		if (i + d < n) {
			g[i].pb({i + d, 0});
			g[i + d].pb({i, 0});
		} else if (d != 2 * n) {
			g[i].pb({(i + d) % n, 1});
			g[(i + d) % n].pb({i, 1});
		} else {
			// g[i].pb({(i + d) % n, 0});
			// g[(i + d) % n].pb({i, 0});
		}

	}
	memset(color, -1, sizeof(color));
	ll components = 0;
	for (int i = 0; i < n; ++i) {
		if (color[i] == -1) {
			if (!assign(i, 0)) {
				return 0;
			}
			++components;
		}
	}
	memset(color, -1, sizeof(color));
	// cout << "comp " << d << ' ' << components << endl;
	ll ans = 0, left = components;
	for (int i = 0; i < n; ++i) {
		// if (d == 2 * n) {
