		if (x[i] == '0') {
			if (color[i] == 1) {
				break;
			} else if (color[i] == -1) {
				assign(i, 0);
				--left;
			}
		} else {
			if (color[i] == -1) {
				assign(i, 1);
				--left;
				ans += p2[left];
				ans %= mod;
			} else if (color[i] == 0) {
