    vecll tmp2(d+1, n);
    for (ll i:irange(0l,n)) {
      if (!bs.test(i)) {
        tmp[i%d] = min(tmp[i%d], i);
      } else {
        tmp2[i%d] = min(tmp2[i%d], i);
      }
    }
    for (ll i:irange(0l,dh)) {
