      sub += dp[e];
      sub %= MOD;
    }
  }
  dp[n2] = (MOD + sum - sub) % MOD;
  ll ans = 0;
  for(auto& p : dp) {
    ans += p.second * p.first;
    ans %= MOD;
  }
