vector<int> odd_cut(int n) {
    vector<int> res;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0 && (n/i) % 2 == 1) {
            res.emplace_back(i);
        }
    }
    return res;
}

void solve() {
    int n; cin >> n;
    string s; cin >> s;
    vector<mint> les(n+1);
    les[0] = 0;
    for (int i = 0; i < n; i++) {
        int x = s[i]-'0';
        les[i+1] = les[i]*2 + x;
    }

    mint res = 0;
    map<int,mint> mp;
    auto ds = odd_cut(n);
    for (int k: ds) {
        mint v = les[k];
        int ad = 1;
        for (int i = k; i < n; i++) {
            char x = s[i%k];
            if ((i/k) & 1) x ^= 1;
            if (x < s[i]) break;
            if (x > s[i]) {
                ad = 0; break;
            }
        }
        v += ad;

        for (int d: ds) {
            if (d < k && k%d == 0) {
                v -= mp[d];
            }
        }
        mp[k] = v;

        res += v * k * 2;
    }

    cout << res;
}

