int foo(const string &x, int block)
{
	string bound = x.substr(0, block);

	bool ok = true, fn = false;

	for (int i = 0; !fn && ok && i * block < x.size(); i++)
		for (int j = 0; !fn && ok && j < block; j++)
		{
			char q = i % 2 == 0 ? bound[j] : '1' ^ '0' ^ bound[j];

			ok &= (q <= x[i * block + j]);

			if (q < x[i * block + j])
				fn = true;
		}

	bound = '0' + bound;

	if (ok)
		for (int i = bound.size() - 1; i >= 0; i--)
			if (bound[i]++ == '1')
				bound[i] = '0';
			else
				break;

	int cnt = 0;

	for (auto it : bound)
	{
		cnt *= 2;
		cnt += it - '0';

		if (cnt > mod)
			cnt -= mod;
	}

	return cnt;
}


