{
	int n;
	string x;

	cin >> n >> x;

	vector<int> cnt(n + 1), arr;

	for (int i = 1; i * i <= n; i++)
		if (n % i == 0)
		{
			arr.push_back(i);
			arr.push_back(n / i);
		}

	sort(arr.begin(), arr.end());
	arr.erase(unique(arr.begin(), arr.end()), arr.end());

	for (auto it : arr)
		if (n / it % 2 == 1)
		{
			cnt[it] = foo(x, it);

			for (auto q : arr)
			{
				if (q == it)
					break;
				if (it % q == 0)
				{
					cnt[it] -= cnt[q];

					if (cnt[it] < 0)
						cnt[it] += mod;
				}
			}
		}

	ll ans = 0;

	for (auto it : arr)
	{
		ans += 2ll * it * cnt[it];
		ans %= mod;
	}

	cout << ans << endl;
}


