int p2[maxn];
int main(){
	p2[0] = 1;
	for(int i = 1; i < maxn; i++) p2[i] = mul(2, p2[i - 1]);
	int n; cin >> n;
	string s; cin >> s;
	vector<int> divs;
	for(int d = 1; d <= n; d++){
		if(n % d == 0 && (n / d) % 2 == 1){
			divs.push_back(d);
		}
	}
	int len = divs.size();
	vector<int> how(len);
	int ans = 0;
	for(int i = 0; i < len; i++){
		int d = divs[i];
		int ways = 0;
		for(int j = 0; j < d; j++){
			if(s[j] == '1'){
				ways += p2[d - j - 1];
				if(ways >= mod) ways -= mod;
			}
		}
		bool ok = true;
		for(int j = d; j < n && ok; j++){
			int dist = j / d;
			if(dist % 2){
				if(s[j % d] == '0'){
					if(s[j] == '0'){
						ok = false;
					}
				} else {
					if(s[j] == '1'){
						break;
					}
				}
			} else {
				if(s[j % d] == '0'){
					if(s[j] == '1'){
						break;
					}
				} else {
					if(s[j] == '0'){
						ok = false;
					}
				}
			}
		}
		if(ok){
			ways += 1;
			if(ways >= mod) ways -= mod;
		}
		for(int j = 0; j < i; j++){
			if(d % divs[j] == 0){
				ways += mod - how[j];
				if(ways >= mod) ways -= mod;
			}
		}
		how[i] = ways;
		ans += mul(ways, d);
		if(ans >= mod) ans -= mod;
	}
	cout << mul(ans, 2) << endl;
	return 0;
}

