const int M = 998244353;
long long modexp(int x, long long e, int m) {
    long long ans = 1, p = x % m;
    while (e > 0) {
        if (e % 2 != 0) ans = (ans * p) % m;
        p = (p * p) % m;
        e >>= 1;
    }
    return ans;
}

int bruteforce(int n, string &s) {
    int x = 0;
    for (int i = 0; i < n; i++) x = 2 * x + (s[i] - '0');
    int ans = 0;
    function<int(int)> step = [&](int y) {
        const int b = y & 1;
        return b == 0 ? (1 << (n - 1)) + y / 2 : y / 2;
    };
    for (int y = 0; y <= x; y++) {
        int z = y;
        do { ans++; z = step(z); } while (y != z);
    }
    return ans;
}

