void dfs(int u) {
  for (auto p : g[u]) {
    int v = p.first, c = p.second;
    int nc = col[u] ^ c;
    if (used[v] != -1) {
      if (nc != col[v]) {
        fail = true;
      }
      continue;
    }
    col[v] = nc;
    used[v] = used[u];
    dfs(v);
  }
}

int calc(int d) {
  //cerr << "calc " << d << '\n';
  for (int i = 0; i < n; ++i) {
    g[i].clear();
    used[i] = -1;
  }
  fail = false;
  for (int i = 0; i < n; ++i) {
    g[i].emplace_back((i + d) % n, ((i + d) / n) % 2);
  }
  int deg = 0;
  for (int i = n - 1; i >= 0; --i) {
    if (used[i] == -1) {
      ++deg;
      col[i] = r[i] == '1';
      used[i] = i;
      dfs(i);
    }
    if (fail) {
      return 0;
    }
  }
  int res = 0;
  for (int i = n - 1; i >= 0; --i) {
    if (col[i] == 1 && r[i] == '0') {
      return res;
    }
    if (col[i] == 0 && r[i] == '1') {
      break;
    }
    if (used[i] == i) {
      --deg;
      if (col[i] == 1) {
        //cerr << "KEK " << deg << '\n';
        udd(res, bin(2, deg));
      }
    }
  }
  udd(res, bin(2, deg));
  return res;
}

