	for(int i=1;i<=n;i++)
		if(n%i==0&&((n/i)&1)) {
			int sum=0;
			for(int j=n;j>=n-i+1;j--)
				if(s[j]=='1') sum=(sum+bin[j-(n-i)-1])%mod;
			int fl=0,fl2=0;
			for(int j=n-i;j&&!fl2;j-=i) {
				fl^=1;
				for(int k=j,l=n;k>=j-i+1;k--,l--) {
					int b=(s[l]-'0')^fl;
					if(b<s[k]-'0') { sum=(sum+1)%mod;fl2=1;break; }
					else if(b>s[k]-'0') { fl2=1;break; }
				}
			}
			if(!fl2) sum=(sum+1)%mod;
			f[i]=sum;
		}
	for(int i=1;i<=n;i++)
		if(n%i==0&&((n/i)&1)) 
			for(int j=i+i;j<=n;j+=i)
				if(n%j==0&&((n/i)&1)) f[j]=(f[j]-f[i]+mod)%mod;
	for(int i=1;i<=n;i++)
		if(n%i==0&&((n/i)&1)) ans=(ans+2ll*f[i]*i)%mod;
