const int M = 15;
int f(int x){
  int all_mask = (1<<M)-1;
  for(int i=1;i<=M;i++){
    int mask = (1<<i)-1;
    int low = (((x&mask)^mask)<<(M-i));
    int ret = (all_mask^(low^(x>>i)));
    if(ret==x){
      return i;
    }
  }
  return -1;
}
string bitrev(string s){
  string t;
  for(int i=0;i<s.size();i++){
    if(s[i]='1')t+='0';
    else t+='1';
  }
  return t;
}
ModInt one = ModInt(1ll);
ModInt to_ModInt(string s){
  ModInt a;
  for(int i=0;i<s.size();i++){
    a = a*ModInt(2ll);
    if(X[i]=='1')a += one;
  }
  return a;
}  
