const int mod=998244353;
const int maxn=(4e5)+10;
int n,s[maxn];
int T[maxn],d[maxn];
int f[maxn],ans;
char S[maxn];
void update(int &x,int y) {
	x+=y; if (x>=mod) x-=mod;
}
int solve(int k) {
	for (int i=1,x=1;i<=2*n;i++,x++) {
		if (x>2*k) x=1;
		if (x<=k) T[i]=d[x]; else T[i]=d[x-k]^1;
	}
	for (int i=1;i<=n;i++) {
		if (T[i]<d[i]) return s[k]+1;
		if (T[i]>d[i]) return s[k];
	}
	return s[k]+1;
}
