void Minus(vector<int> &x) {
	int i;

	x[0]--;
	if (x[0] < 0) {
		i = 1;
		while (true) {
			x[i - 1] += 2;
			x[i]--;
			if (x[i] >= 0) break;
			i++;
		}
	}
}

bool check(vector<int> &x, int d) {
	vector<int> y(n, 0);
	int i, j;

	//cout << "d = " << d << ", x = ";
	//for (i = x.size() - 1; i >= 0; i--) cout << x[i];
	//cout << endl;

	int shift = 0;
	for (i = 0; i < n / d; i++) {
		if (i % 2 == 0) {
			for (j = 0; j < d; j++) {
				y[shift] += x[j];
				shift++;
			}
		}
		else {
			for (j = 0; j < d; j++) {
				y[shift] += (!x[j]);
				shift++;
			}
		}
	}

	//cout << "y = ";
	//for (i = n - 1; i >= 0; i--) cout << y[i];
	//cout << endl;

	for (i = n - 1; i >= 0; i--) {
		int p = s[n - 1 - i] - '0';
		int q = y[i];
		if (q != p) {
			if (q > p) return false;
			return true;
		}
	}
	return true;
}

int calc(int d) {

	//まずは、2^((n/d)-1) * x <= int(s)なる最大のxを探す
	int i;
	vector<int> x;	//…x2x1x0 (10進数)
	x.resize(d);
	//cout<< "x.size() = " << x.size() << endl;
	for (i = 0; i < d; i++) {
		int val = s[d - 1 - i] - '0';
		x[i] = val;
	}

	//x, x-1, x-2, x-3…あたりを試すと条件を満たす最大のxが分かる
	while (!check(x, d)) {
		Minus(x);
	}

	int ret = 0;
	int mul = 1;
	for (i = 0; i < x.size(); i++) {
		ret += x[i] * mul;
		ret %= mod;
		mul *= 2;
		mul %= mod;
	}
	ret++;
	ret %= mod;
	return ret;
}

signed main() {
	int i, j, k;

	cin >> n >> s;

	static int memo[200001];
	for (i = 1; i <= n; i++) {
		if (n % i != 0) continue;
		if ((n / i) % 2 == 0) continue;
		memo[i] = calc(i);
		//cout << "memo[" << i << "] = " << memo[i] << endl;
	}

	static int cnt[200001] = {0};

	for (i = 1; i <= n; i++) {
		if (n % i != 0) continue;
		if ((n / i) % 2 == 0) continue;

		vector<int> ps;
		int tmp = i;
		for (j = 2; j * j <= tmp; j++) {
			while (tmp % j == 0) {
				tmp /= j;
				ps.push_back(j);
			}
		}
		if (tmp > 1) ps.push_back(tmp);

		for (j = 0; j < (1 << ps.size()); j++) {
			int yaku = 1;
			int ucnt = 0;
			for (k = 0; k < ps.size(); k++) {
				if ((j >> k) & 1) {
					yaku *= ps[k];
					ucnt++;
				}
			}
			if ((ps.size() - ucnt) % 2 == 0) {
				cnt[i] += memo[yaku];
				if (cnt[i] >= mod) cnt[i] -= mod;
			}
			else {
				cnt[i] -= memo[yaku];
				if (cnt[i] < 0) cnt[i] += mod;
			}
		}
		//cout << "cnt[" << i << "] = " << cnt[i] << endl;
	}

	int ans = 0;
	for (i = 1; i <= n; i++) {
		ans += 2 * i * cnt[i] % mod;
		ans %= mod;
		//cout << "cnt[" << i << "] = " << cnt[i] << endl;
	}
	cout << ans << endl;
	return 0;
}

