using namespace std;
const int MAXN = 202020;
const int P = 998244353;
char s[MAXN], t[MAXN];
bool vis[MAXN];
int n, ans, val[MAXN];
void update(int &x, int y)
{
	x += y;
	if (x >= P)
		x -= P;
}
int cnt(int x)
{
	int ans = 0;
	for (int i = 1; i <= x; i++)
		ans = ((ans * 2) + (s[i] - '0')) % P;
	int tmp = 1;
	for (int i = 1; i <= n; i++)
	{
		if(tmp <= x)
			t[i] = s[tmp];
		else
			t[i] = s[tmp - x] ^ 1;
		tmp = (tmp == 2 * x) ? 1 : (tmp + 1);
	}	
	for (int i = 1; i <= n; i++)
	{
		if (s[i] > t[i])
			return ans + 1;
		if (t[i] > s[i])
			return ans;
	}
	return ans + 1;
}
int main()
{
	scanf("%d", &n);
	scanf("%s", s + 1);
	for (int i = 1; i <= n; i++)
		if (n % i == 0 && (n / i) % 2 == 1)
			vis[i] = true;
	int ans = 1ll * cnt(n) * (2 * n) % P;
	for(int i = n - 1; i >= 1; i--)
	{
		if(!vis[i])
			continue;
		int tmp = 2 * n;
		for(int j = i; j <= n; j += i)
			if(vis[j])
				update(tmp, val[j]);
		val[i] = 2 * i;
		update(val[i], P - tmp);
		update(ans, 1ll * cnt(i) * val[i] % P);
	}
	printf("%d\n", ans);
	return 0;
}

