ll mpow(ll x, ll n){ //x^n(mod M)
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

char str[200005];

int main(int argc, char* argv[])
{
    int n;
    scanf("%d", &n);
    scanf("%s", str);

    ll x0=0;
    int i;
    for(i=0; i<n; i++) {
        x0=(x0*2+(str[i]-'0'))%MOD;
    }

    vector<int> a;
    for(i=3; i<=n; i+=2) {
        if(n%i==0) {
            a.push_back(n/i);
        }
    }
    reverse(a.begin(), a.end());

    ll ans=n*2*(x0+1)%MOD;

    int siz=(int)a.size();
    vector<ll> ans0(siz);

    int t;
    for(t=0; t<siz; t++) {
        int kk=a[t];

        for(i=0; i<n; i++) {
            if(str[i]=='1') {
                int bad=0;
                if(i>=kk) {
                    int i0=i%kk;
                    int step=(i-i0)/kk;
                    if(step%2==0 && str[i0]=='1') {
                        bad=1;
                    }
                    if(step%2==1 && str[i0]=='0') {
                        bad=1;
                    }
                }
                if(bad==0) {
                    int defined=MIN(kk, i+1);
                    int not_defined=kk-defined;
                    ans0[t] = (ans0[t] + mpow(2, not_defined))%MOD;
                }
            }

            {
                int bad=0;
                if(i>=kk) {
                    int i0=i%kk;
                    int step=(i-i0)/kk;
                    if(step%2==0 && str[i0]!=str[i]) {
                        bad=1;
                    }
                    if(step%2==1 && str[i0]==str[i]) {
                        bad=1;
                    }
                }
                if(bad) {
                    break;
                }
            }
        }
        if(i==n) {
            ans0[t]=ans0[t]+1;
        }
    }

    for(t=0; t<siz; t++) {
        int t2;
        for(t2=t+1; t2<siz; t2++) {
            if(a[t2]%a[t]==0) {
                //printf("%d %d\n", a[t2], a[t]);
                ans0[t2]=(ans0[t2]-ans0[t]+MOD)%MOD;
            }
        }
    }

    for(t=0; t<siz; t++) {
        ans0[t] = ans0[t] * (n*2-a[t]*2) %MOD;
        ans = (ans - ans0[t] +MOD)%MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

