int main(){
    using namespace std;
    constexpr unsigned long MOD = 998244353;
    unsigned long N;
    cin >> N;
    vector<unsigned long> X(N);
    {
        string S;
        cin >> S;
        transform(S.begin(), S.end(), X.begin(), [](auto i){return i & 1;});
        transform(S.begin(), S.end(), back_inserter(X), [](auto i){return ~i & 1;});
    }
    vector<unsigned long> pow2(N + 1);
    pow2[0] = 1;
    for(unsigned long i = 1; i <= N; ++i)pow2[i] = pow2[i - 1] * 2 % MOD;
    const auto& answer = [&](auto x) -> unsigned long{
        unsigned long ret{0}, out{3 * N + 1}, safe{3 * N};
        for(unsigned long i = 0, t; i < x; ++i){
            if(t = X[i])(ret += pow2[x - i - 1]) %= MOD;
            for(unsigned long j = i; j < 2 * N; j += x){
                if(X[j] > t){
                    safe = min(safe, j);
                    break;
                }
                if(X[j] < t){
                    out = min(out, j);
                    break;
                }
                t ^= 1;
            }
        }
        return (ret + (safe < out)) % MOD;
    };
    vector<unsigned long> factor;
    {
        unsigned long i{1};
        for(; i * i < N; ++i)if(!(N % i)){
            if(i & 1)factor.push_back(i);
            if((N / i) & 1)factor.push_back(N / i);
        }
        if(i * i == N && i & 1)factor.push_back(i);
    }
    sort(factor.rbegin(), factor.rend());
    vector<unsigned long> ans(N + 1);
    unsigned long a{0};
    for(const auto& i : factor)if(i & 1) ans[i] = answer(N / i);
    for(const auto& i : factor){
        for(unsigned long j = 2 * i; j <= N; j += i)ans[i] += MOD - ans[j];
        a += (N / i) * (ans[i] %= MOD) % MOD;
    }
    cout << (a * 2) % MOD << endl;
    return 0;
}

