int main() {
  long long N;
  cin >> N;
  string X;
  cin >> X;

  long long pow_2 = 0, N_help = N;
  while (N_help % 2 == 0){
    N_help /= 2;
    pow_2++;
  }

  priority_queue<long long, vector<long long>, greater<long long>> yakusu;
  for (int i = 1; i <= N_help; i++){
    if (N_help % i == 0) yakusu.push(i);
  }

  long long count = 1, help[N];
  help[0] = 1;
  for (int i = 1; i <= N; i++){
    if (i != 1) help[i - 1] = help[i - 2] << 1;
    count += (X[N - i] - '0') * help[i - 1];
    count %= MOD;
    help[i - 1] %= MOD;
  }
  count *= 2 * N;
  count %= MOD;

  while (!yakusu.empty()) {
    long long a = yakusu.top() * 2 * help[pow_2];
    yakusu.pop();
    if (a >= N) continue;
    long long count_ = 0;
    for (long long i = 0; i < a; i++){
      for (long long j = 0; j < N; j++){
        if ((0 <= j % a + i && j % a + i < a / 2) || (a <= j % a + i && j % a + i < a / 2 * 3)){
          if (j == N - 1 && X[j] == '1') count_++;
          if (X[j] == '1') continue;
          if (X[j] == '0') break;
        }
        else {
          if (j == N - 1) count_++;
          if (X[j] == '1') {
            count_++;
            break;
          }
          if (X[j] == '0') continue;
        }
      }
    }
    count -= (2 * N - a) * count_;
    if (count < 0){
      count %= MOD;
      count += MOD;
      count %= MOD;
    }
  }

  cout << count << endl;
}

