mint convert(const string& s) {
    mint ret = 0;
    for (char c : s) {
        ret = (ret * 2) + (c == '1');
    }
    return ret;
}

int main() {
    int n;
    string s;
    std::cin >> n >> s;

    int e;
    for (e = 25; e > 0; --e) {
        if (n % (1 << e) == 0) break;
    }

    vector<mint> cnt(n + 1, 0);
    for (int l = 1; l <= n; ++l) {
        if (l % (1 << e) != 0 || n % l != 0) continue;

        string head = s.substr(0, l);

        auto& c = cnt[l];
        c = convert(head);

        while (head.length() < s.length()) {
            int prev = head[head.length() - l] - '0';
            head.push_back(1 - prev + '0');
        }
        if (head <= s) ++c;

        for (int sl = 1; sl < l; ++sl) {
            if (l % sl == 0) c -= cnt[sl];
        }
    }

    mint ans = 0;
    for (int l = 1; l <= n; ++l) {
        if (cnt[l] == 0) continue;
        ans += cnt[l] * l * 2;
    }

    std::cout << ans << std::endl;
    return 0;
}

