int vis[200005], mu[200005], prm[200005], cnt;
void euler() {
    mu[1] = 1;
    for (int i = 2; i <= n; ++i) {
        if (!vis[i]) mu[i] = mod - 1, prm[++cnt] = i;
        for (int j = 1; j <= cnt; ++j) {
            if (i * prm[j] > n) break;
            vis[i * prm[j]] = 1;
            if (i % prm[j] == 0) break;
            mu[i * prm[j]] = M(mod - mu[i]);
        }
    }
}

int get(int len) {
    int ret = 0;
    for (int i = 1; i <= len; ++i) ret = M(ret + ret + s[i] - '0');
    return ret;
}

int check(int len) {
    for (int i = 1; i <= len; ++i) {
        if (s[i + len] == (s[i] ^ 1)) continue;
        if (s[i + len] > (s[i] ^ 1)) return 1;
        if (s[i + len] < (s[i] ^ 1)) return 0;
    }
    int t = n / (2 * len);
    for (int i = 1; i < t; ++i) {
        int tl = i * len;
        for (int i = 1; i <= len * 2; ++i) {
            if (s[i + tl] == s[i]) continue;
            if (s[i + tl] > s[i]) return 1;
            if (s[i + tl] < s[i]) return 0;
        }
    }

    int tl = t * len;
    for (int i = 1; i <= len; ++i) {
        if (s[i + tl] == s[i]) continue;
        if (s[i + tl] > s[i]) return 1;
        if (s[i + tl] < s[i]) return 0;
    }
    return 1;
}

int main() {
    n = read(), euler();
    scanf("%s", s + 1);
    for (int i = 1; i <= n; ++i) {
        if (!(n % i == 0 && n % (2 * i) != 0)) continue;
        // cerr << i << ' ' << get(i) << ' ' << check(i) << endl;
        f[i] = M(M(get(i) + mod) + check(i));
    }
    f[n] = M(f[n] + 1);
    for (int i = 1; i <= n; ++i)
        for (int j = i; j <= n; j += i)
            g[j] = M(g[j] + 1ll * f[i] * mu[j / i] % mod);
    int res = 0;
    for (int i = 1; i <= n; ++i) {
        if (!(n % i == 0 && n % (2 * i) != 0)) continue;
        res = M(res + 2ll * g[i] * i % mod);
    }
    printf("%d\n", res);
    return 0;
}

