int solve(int t)
{
	int s=0;
	for (int i=0;i<t;i++) s=(s*2+a[i])%MOD;
	bool flag=0;
	for (int i=t;i<n;i++)
		if (a[i]<(a[i%t]^((i/t)&1))) {flag=1;break;}
		else if (a[i]>(a[i%t]^((i/t)&1))) break;
	if (!flag) s++;
	return s;
}

int main()
{
	scanf("%d",&n);
	scanf("%s",str);
	int r=0;
	for (int i=0;i<n;i++) a[i]=str[i]-'0',r=(r*2+a[i])%MOD;;
	r++;
	for (int i=1;i<=n;i++)
		if (n%i==0&&n/i%2==1)
		{
			(f[i]+=solve(i))%=MOD;
			for (int j=i*2;j<=n;j+=i)
				if (n%j==0) (f[j]+=MOD-f[i])%=MOD;
			(r+=MOD-f[i])%=MOD;
		}
	int ans=(LL)r*n*2%MOD;
	for (int i=1;i<=n;i++)
		if (n%i==0&&n/i%2==1) (ans+=(LL)f[i]*i*2%MOD)%=MOD;
	printf("%d\n",ans);
	return 0;
}

