inline int inc(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int dec(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int mul(int a, int b) { return 1LL * a * b % MOD; }

inline int power(int x, int k) {
	int tmp = 1;
	while(k) {
		if(k & 1) tmp = mul(tmp,x);
		x = mul(x,x);
		k >>= 1;
	}
	return tmp;
}

int n, arr[2][maxn], mi[maxn], f[maxn], lis[maxn], im[maxn], inv2;
char s[maxn];

inline int get_num(int l, int r, int kd) {
	int tmp = dec(arr[kd][r],mul(mi[r - l + 1],arr[kd][l - 1]));
	return tmp;
}

inline int LCP(int l1, int r1, int l2, int r2, int kd) {
	int len = min(r1 - l1 + 1,r2 - l2 + 1);
	int l = 0, r = len, tmp = 0;
  while(l <= r) {
    int mid = (l + r) >> 1;
		int t1 = get_num(l1,l1 + mid - 1,kd);
		int t2 = get_num(l2,l2 + mid - 1,0);
		if(t1 == t2) l = mid + 1, tmp = mid;
		else r = mid - 1;
	}
	return tmp;
}

inline int calc(int x) {
	int now = get_num(1,x,0);
	int flag = 1;
	for(int i = x + 1, kd = 1;i <= n;i += x, kd = 1 - kd) {
		int len = LCP(1,x,i,i + x - 1,kd);
		if(len == x) continue;
		if(!kd) {
			if(s[len + 1] == '0') flag = 1;
			else flag = 0;
			break;
		}
		else {
      if(s[len + 1] == '1') flag = 1;
			else flag = 0;
			break;
		}
	}
	now = inc(now,flag);
	return now;
}

