int Add(int a,int b){
	return a+b>=mod?a+b-mod:a+b;
}
int Minus(int a,int b){
	return a<b?a-b+mod:a-b;
}
int dfs(int now,int flag){
	if(now==m){
		if(!flag)
			return 1;
		else{
			while(now<n){
				if((c[now%m]^((now/m)&1))<a[now]-'0')
					return 1;
				else if((c[now%m]^((now/m)&1))>a[now]-'0')
					return 0;
				now++;
			}
			return 1;
		}
	}
	if(!flag&&~dp[now])
		return dp[now];
	int ret=0;
	for(int i=0;i<=(flag?a[now]-'0':1);i++){
		c[now]=i;
		ret=Add(ret,dfs(now+1,flag&&i==a[now]-'0'));
	}
	if(!flag)
		dp[now]=ret;
	return ret;
}
