const int MOD=998244353;

ll ppow(ll a,ll b){
	a%=MOD;
	ll res=1;
	while(b){
		if(b&1)res=(res*a)%MOD;
		a=(a*a)%MOD;
		b>>=1;
	}
	return res;
}

vector<ll>divisor(ll n){
	vector<ll>res;
	for(ll i=1;i*i<=n;i++){
		if(n%i==0){
			res.push_back(i);
			if(i!=n/i)res.push_back(n/i);
		}
	}
	return res;
}

ll dp[500000];

int main(){
	int n;string s;cin>>n>>s;
	auto v=divisor(n);
	for(int k:v){
		if((n/k)%2==0)continue;
		ll sum=0;
		rep(i,k){
			if(s[i]=='1')(sum+=ppow(2,k-i-1))%=MOD;
		}
		int g=0;
		bool ok=false;
		while(g<n){
			char c=s[g%k];
			if((g/k)%2==1)c=(c=='0'?'1':'0');
			if(s[g]==c)g++;
			else{
				if(s[g]<c)ok=false;
				else ok=true;
				break;
			}
		}
		if(g==n||ok)sum++;
		dp[k]=sum%MOD;
	}
	for(int i=1;i<=n;i++){
		if(!dp[i])continue;
		for(int j=2*i;j<=n;j+=i)(dp[j]+=MOD-dp[i])%=MOD;
	}
	ll all=1;
	rep(i,n){
		if(s[i]=='1')(all+=ppow(2,n-i-1))%=MOD;
	}
	ll ans=0;
	for(int k:v){
		(ans+=2*k*dp[k])%=MOD;
		(all+=MOD-dp[k])%=MOD;
	}
	(ans+=all*2*n)%=MOD;
	cout<<ans<<endl;
}

