      for (int j = i; j < MAX_N; j += i) {
        factor[j] = i;
      }
    }
  }

  for (int i = 1; i < MAX_N; i++) {
    mobius[i] = Modint(mobi(i));
  }

  int n;
  cin >> n;

  string X;
  cin >> X;

