    if (X[i] == '1') {
      pref += Modint(1);
    }

    if (n % (i + 1) == 0 && (n / (i + 1)) % 2 == 1) {
      Modint period (2 * (i + 1));
      Modint cnt_cur (0);
      cnt[i + 1] = pref;

      // check if the completion of prefix is <= X
      int k = i + 1;
      int ok = 0;
      for (int t = 0; t < n; t++) {
        if (t % (2 * k) < k) {
          if (X[t % k] < X[t]) {
            ok = 1;
            break;
          } else if (X[t % k] > X[t]) {
            ok = -1;
            break;
          }
        } else {
          if (neg(X[t % k]) < X[t]) {
            ok = 1;
            break;
          } else if (neg(X[t % k]) > X[t]) {
            ok = -1;
            break;
          }
        }
      }

      if (ok >= 0) {
        cnt[k] += Modint(1);
      }

      Modint uniq (0);
      for (int d = 1; d <= k; d++) {
        if (k % d == 0) {
          uniq += mobius[d] * cnt[k / d];
        }
      }

      ans += uniq * period;
    }
  }

  cout << ans << endl;
}

