string rev(string s) {
	int sz = (int)s.size();
	string res = "";
	rep(i, sz) {
		if(s[i] == '0') res += '1';
		else res += '0';
	}
	return res;
}

mint val(string s) {
	int sz = (int)s.size();
	mint res = 0;
	mint pw = (mint)1;
	per(i, sz) {
		if(s[i] == '1') res += pw;
		pw *= (mint)2;
	}
	return res;
}

vector<int> pf(int x) {
	vector<int> res;
	for(int i = 2; i * i <= x; ++ i) {
		if(x % i == 0) {
			res.pb(i);
			while(x % i == 0) x /= i;
		}
	}
	if(x != 1) res.pb(x);
	return res;
}

