	int cc=1;
	for(int i=g;i>=1;i--){
		if(s[n-i]=='1'){
			// cerr<<i<<" "<<cc<<endl;
			dadd(ans,cc);
		}
		dmul(cc,2);
	}
	int l=-1;
	bool ok=true;
	for(int i=n-1;i>=n-g;i--){
		int t=n/g;
		int j=i;
		while(t--){
			int k=j%n;
			char c=s[i]^(j!=k);
			if(k>l&&c!=s[k]){
				l=k;
				ok=c<s[k];
			}
			j=(i+x)%m;
		}
	}
	if(ok){
		dadd(ans,1);
	}
	return ans;
}
