inline void add_edge(int s,int e,int t){
	tot++;v[tot]=e;w[tot]=t;nxt[tot]=head[s];head[s]=tot;
}

bool flag=true;
void dfs(int u,int c){
	col[u]=c;
	bel[u]=cnt;
	seq[cnt].push_back(u);
    for(int i=head[u];i;i=nxt[i])
        if(col[v[i]]==-1)
        	dfs(v[i],(c+w[i])&1);
        else if((col[u]^col[v[i]])!=w[i])flag=false;
}
bool vis[Maxn];
char num[Maxn];
inline int solve(int x){
	cnt=0;
	tot=0;memset(head,0,sizeof(int)*(n+1));
	flag=true;
	for(register int i=1;i<=n;++i){
		int to=(i-x+n)%n;
		if(to==0)add_edge(i,n,0);
		else add_edge(i,to,0);
	}
	for(register int i=1;i<=n/2;++i){
		add_edge(i,i+n/2,1);
		add_edge(i+n/2,i,1);
	}
	memset(col,-1,sizeof(int)*(n+1));
	for(register int i=1;i<=n;++i)
	    if(col[i]==-1){
	    	cnt++;
	    	seq[cnt].clear();
	    	dfs(i,0);
	    	if(!flag)return 0;
		}
	memset(vis,false,sizeof(bool)*(n+1));
	int tmp=0,res=0;
	bool z=false;
    for(register int i=1;i<=n;++i)
