  void main_() {
    using mint = modint<static_cast<u64>(998244353)>;
    const usize n = scan<usize>();
    std::vector<int> x(n);
    for (auto& e : x) {
      e = scan<char>() - '0';
    }
    std::vector<mint> pow2(n + 1_z);
    pow2[0_z] = static_cast<mint>(1);
    for (const auto i : rep(0_z, n)) {
      pow2[i + 1_z] = pow2[i] + pow2[i];
    }

    const auto solve = [&](const usize block) -> mint {
      mint ret = static_cast<mint>(0);
      for (const auto i : rep(0_z, block)) {
        if (x[i]) {
          ret += pow2[block - i - 1_z];
        }
      }
      for (const auto i : rep(0_z, n)) {
        const int ex = x[i % block] ^ (i / block % 2_z);
        if (ex < x[i]) {
          return ret + static_cast<mint>(1);
        }
        if (ex > x[i]) {
          return ret;
        }
      }
      return ret + static_cast<mint>(1);
    };

    std::vector<mint> vec(n + 1_z);
    mint ans = static_cast<mint>(0);
    for (const auto i : rep(1_z, n + 1_z)) {
      if (n % i == 0_z && i % 2_z == 1_z) {
        vec[i] += solve(n / i);
      }
    }
    const prime_sieve s{ 300000_z };
    s.multiple_mobius(vec);
    for (const auto i : rep(1_z, n + 1_z)) {
      ans += vec[i] * static_cast<mint>(n / i);
    }
    std::cout << (ans * static_cast<mint>(2)).value() << std::endl;
  }

