void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
    int n;

    auto solve_test = [&] () {
        string x;
        cin >> x;
        assert(int(x.size()) == n);

        vector<int> mu(n + 1, +1);
        for (int i = 2; i * i <= n; i++) {
            for (int j = i * i; j <= n; j += i * i)
                mu[j] = 0;
        }

        vector<char> isprime(n + 1, 1);
        for (int i = 2; i <= n; i++) {
            if (isprime[i]) {
                for (int j = i; j <= n; j += i)
                {
                    mu[j] *= -1;
                    if (j > i)
                        isprime[j] = 0;
                }
            }
        }

        int two = 1;
        while (n % (2 * two) == 0)
            two *= 2;

        vector<vector<int>> divs(n + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 2 * i; j <= n; j += i)
                divs[j].push_back(i);
        }

        auto with_blocks = [&](int l) {
            assert(n % l == 0 && (n / l) % 2 == 1);

            int ans = 0;
            for (int i = 0; i < l; i++)
                ans = mult(ans, 2), add(ans, x[i] - '0');

