            for (int i = 0; i < n; i++) {
                const char cur = ((i / l) % 2 == 0 ? x[i % l] : x[i % l] ^ '0' ^ '1');
                if (cur < x[i])
                    break;
                if (cur > x[i]) {
                    ok = false;
                    break;
                }
            }

            if (ok)
                add(ans, 1);
            return ans;
        };

        vector<int> f(n / two + 1);
        for (int i = 1; i <= n / two; i += 2) {
            if (n % i != 0)
                continue;

            f[i] = with_blocks(two * i);
            for (int j : divs[i]) {
