        int ans = 0;
        for (int i = 1; i <= n / two; i++)
        {
            add(ans, mult(i == n / two ? 2 * n : 2 * two * i, f[i]));
        }
        return ans;
    };

    while (cin >> n)
    {
        auto res = solve_test();
        cout << res << endl;
