int pw(int n,int k){
  if(k<0)return pw(n,k+MOD-1);
  int res=1;
  while(k){
    if(k&1)res*=n;res%=MOD;
    n*=n;n%=MOD;
    k>>=1;
  }
  return res;
}

int f(int a){//長さaのループがX以下に何種類存在するか
  int res=0;
  for(int i=0;i<a;i++)if(x[i]=='1')res+=pw(2,a-i-1),res%=MOD;//桁DPっぽいところ
  {//最初a文字がXと完全に一致しているやつがx以下かどうかの判定
    string A=x.substr(0,a),s;
    while(s.size()<N)s+=A;
    for(int i=0;i<s.size();i++)if((i/a)&1)s[i]=(s[i]-'0')^1+'0';
    //sがx以下かどうか判定する
    for(int i=a;i<N;i++){
      if(x[i]=='1'&&s[i]=='0'){res++;break;}
      if(x[i]=='0'&&s[i]=='1')break;
      if(i==N-1)res++;
    }
  }
  return res;
}

int INT(string x){//xを数字に変換する
  int res=0;
  for(char p:x){
    res*=2;
    res+=(p=='1');
    res%=MOD;
  }
  return res;
}

