const int MOD=998244353;
int N, P2[200001], V[200001];
bool chk[200001];
string X;

bool check(int SZ)
{
	for(int p=0;p*SZ<N;p++) {
		for(int i=0;i<SZ;i++) {
			if(X[p*SZ+i]<(X[i]-'0'^(p&1))+'0') return false;
			if(X[p*SZ+i]>(X[i]-'0'^(p&1))+'0') return true;
		}
	}
	return true;
}

int solve(int SZ)
{
	int ret=0;
	if(check(SZ)) ret=1;
	for(int i=SZ-1;i>=0;i--) if(X[i]=='1') ret=(ret+P2[SZ-1-i])%MOD;
	return ret;
}

