const int mod = 998244353;
const int N = 200010;
int n, a[N], ans, mu[N], tx[N];
char s[N];
bool p[N];

int calc(int x) {
	int res = 0, j = 1;
	rep(i, 1, x) res = (res * 2 + a[i]) % mod;
	rep(i, 1, n) {
		tx[i] = (j <= x ? a[j] : (a[j - x] ^ 1));
		++j; if(j > x + x) j -= x + x;
	}
	rep(i, 1, n) if(a[i] != tx[i]) return tx[i] < a[i] ? (res + 1) % mod : res;
	return (res + 1) % mod;
}
int main() {
	scanf("%d%s", &n, s + 1); rep(i, 1, n) a[i] = s[i] - '0';
	rep(i, 1, n) if(n % i == 0 && (n / i) % 2) p[i] = 1;
	ans = 1ll * calc(n) * 2 * n % mod;
	per(i, n - 1, 1) if(p[i]) {
		int w = n + n;
		for(int j = i; j <= n; j += i) if(p[j]) w = (w + mu[j]) % mod;
		mu[i] = (i + i - w + mod) % mod;
		ans = (ans + 1ll * calc(i) * mu[i] % mod) % mod;
	}
	printf("%d\n", ans);
	return 0;
}

