string makeloop(string x, int n, int i) {
  string a = x.substr(0, i);
  string b;
  rep(j, i) {
    if (a[j] == '0')
      b += '1';
    else
      b += '0';
  }
  string loop = ((a + b) * (n / i + 1)).substr(0, n);
  return loop;
}

int main() {
  int n;
