  ll ans = 0;
  ll temp = 0;
  ll done = 0;
  vector<ll> num(n + 1, 0);
  for (int i = 1; i <= n; i++) {
    int t = x[i - 1] - '0';
    temp = (temp * 2 + t) % MOD;
    if ((n % i != 0) || (n / i % 2 == 0)) continue;

    int dictcheck = 0;
    string loop = makeloop(x, n, i);
    if (x >= loop) {
      dictcheck = 1;
    }

    vector<int> divisor;
    rep(j, i - 1) {
      if (i % (j + 1) == 0) divisor.push_back(j + 1);
    }
    ll done = 0;
    for (auto& d : divisor) {
      done = (done + num[d]) % MOD;
    }
    ans = (ans + (MOD + temp + dictcheck - done) % MOD * 2 * i % MOD) % MOD;
    num[i] = (MOD + temp + dictcheck - done) % MOD;
  }

