#include <bits/stdc++.h>
using namespace std;

#define MOD 998244353

string S, R;
long long two[200005];
long long dp[200005], fp[200005];

vector< pair<long long, long long> > X;

long long solve(int pos, int period)
{
    if(pos == period)
    {
        R.clear();

        for(int i=0; i<period; i++)
            R.push_back(S[i]);

        for(int i=period; i<S.size(); i++)
        {
            int x = R[i-period] - '0';
            x ^= 1;
            R.push_back((char)(x + '0'));
        }

        return (R <= S);
    }

    if(dp[pos] != -1)
        return dp[pos];

    long long ans = solve(pos + 1, period);

    if(S[pos] == '1')
        ans += two[period - pos - 1];

    return dp[pos] = ans % MOD;
}

long long func(int pos)
{
    if(pos == X.size())
        return 0;

    if(fp[pos] != -1)
        return fp[pos];

    long long ans = X[pos].second;

    for(int i=pos+1; i<X.size(); i++)
        if(X[i].first % X[pos].first == 0)
            ans += MOD - func(i);

    return fp[pos] = ans % MOD;
}

int main() {

    ios::sync_with_stdio(0);
    cin.tie(NULL), cout.tie(NULL);

    int N;
    cin >> N >> S;

    two[0] = 1;

    for(int i=1; i<=N; i++)
        two[i] = two[i-1] * 2 % MOD;

    long long curr = 0, num = 0;

    for(int j=3; j<=N; j+= 2)
    {
        if(N % j)
            continue;

        int y = N / j;

        for(int i=0; i<=y; i++)
            dp[i] = -1;

        X.push_back({j, solve(0, y)});
    }

    memset(fp, -1, sizeof(fp));

    for(int i=0; i<X.size(); i++)
    {
        num += func(i);
        curr += func(i) * (N / X[i].first) * 2 % MOD;
    }

    long long ans = 0;

    for (auto s : S)
        ans = (ans * 2 + s - '0') % MOD;

    num %= MOD, curr %= MOD;
    ans = (ans + 1 - num + MOD) * N * 2 % MOD + curr;

    cout << ans % MOD << "\n";
    return 0;
}

