template <class T> void inverse_multiple_transform(::std::vector<T> &a) {
  int n = a.size();
  ::std::vector<bool> sieve(n, true);
  for (int i = 0; ++i != n;) {
    a[i] -= a[0];
  }
  for (int p = 2; p < n; ++p) {
    if (sieve[p]) {
      for (int k = 1; k * p < n; ++k) {
        sieve[k * p] = false;
        a[k] -= a[k * p];
      }
    }
  }
}
