map<int, int> prime_factorization(int n) {
    map<int, int> mp;
    for (int x = 2; x * x <= n; x++) {
        while (n % x == 0) {
            mp[x]++;
            n /= x;
        }
    }
    if (n != 1) mp[n]++;
    return mp;
}
