                    cnt -= val[x];
                    if(x * x < j) cnt -= val[j / x];
                    while(cnt < 0) cnt += MOD;
                }
            }
            val[j] = cnt;
            ans += cnt * j * 2;
            ans %= MOD;
        }
    }
