        return 2*n%i==0 && (2*n/i)%2==1;
    };
    static int f[XN],sum[XN];
    for(int i=1;i<=n;++i)
        sum[i]=(sum[i-1]*2LL+x[i]-'0')%P;
    for(int i=1;i<=2*n;++i) {
        if(IsValid(i)) {
            assert(i%2==0);
            f[i]=sum[i/2];
            bool tak=1;
            if(i!=2*n) {
                assert(i<=n);
                std::string s(x+1,x+1+i/2);
                while(s.length()!=n) {
                    s+=s.substr(s.length()-i/2,i/2);
                    for(int j=s.length()-i/2;j<s.length();++j)
                        s[j]^=1;
                }
                if(s>std::string(x+1,x+1+n))
                    tak=0;
            }
            M(f[i]+=tak);
        }
    }
    for(int i=1;i<=2*n;++i)
        if(IsValid(i))
            for(int j=2;i*j<=2*n;++j)
                if(IsValid(i*j))
                    M(f[i*j]-=f[i]);
    int Ans=0;
    for(int i=1;i<=2*n;++i)
        if(IsValid(i))
            M(Ans+=1LL*i*f[i]%P);

