    if ((2 * n / k) % 2 == 0) continue;
    string t = s.substr(0, k / 2), t2 = t;
    cerr << k << " " << t << endl;
    bool f = true;
    for (int i = 0; i < k / 2; i++) {
      if (t[i] == '0')
        t2[i] = '1';
      else {
        t2[i] = '0';
        f = false;
      }
    }
    string x = "";
    while (x.size() < n) {
      x += t;
      x += t2;
    }
    x = x.substr(0, n);
    // cerr << k << " " << x << endl;
    if (x <= s) {
      dp[k]++;
    }
    if (!f) {
      ll sum = 0, tmp = 1;
      reverse(t.begin(), t.end());
      for (int i = 0; i < k / 2; i++) {
        if (t[i] == '1') sum = (sum + tmp) % mod;
        tmp = tmp * 2 % mod;
      }
      cerr << k << " " << sum << endl;
      dp[k] = (dp[k] + sum) % mod;
    }
    for (int j = 2; j * j <= k; j++) {
      if (k % j) continue;
      dp[k] = (dp[k] + mod - dp[j]) % mod;
      if (j * j != k) dp[k] = (dp[k] + mod - dp[k / j]) % mod;
    }
    ret += (ll)k * dp[k] % mod;
    ret %= mod;
    cerr << k << " " << dp[k] << endl;
  }
  cout << ret << endl;
}

