		for (int j = 0; j < m; j++) {
			int dig = s[j]-'0';
			dig = (dig + (i%2))%2;
			if (dig < (s[i*m+j]-'0')) return true;
			if (dig > (s[i*m+j]-'0')) return false;
		}
	}
	return true;
}

int prefMod(int d) {
	int m = n/d;
	int lans = 0;
	FOR(i,0,m) {
		lans = (2*lans+s[i]-'0') % mod;
	}
	return lans;
}

