int calc(int x)
{
	int tot=n/x;
	if (tot%2==0) return 0;
	int ans=b[x];
	for (int i=1;i<=x;++i)
	{
		A[i]=a[i];
	}
	for (int i=x+1;i<=n;++i)
	{
		A[i]='0'+'1'-A[i-x];
	}
	int flag=0;
	for (int i=1;i<=n;++i)
	{
		if (a[i]<A[i]) 
		{
			flag=-1;
			break;
		}
		else if (a[i]>A[i])
		{
			flag=1;
			break;
		}
	}
	if (flag>=0) ++ans;
	return ans%mod;
}

void init()
{
	read(n);
	scanf("%s",a+1);
	for (int i=1;i<=n;++i)
	{
		b[i]=Mul(b[i-1],2);
		add(b[i],a[i]-'0');
	}
	mu[1]=1;
	for (int i=2;i<=n;++i)
	{
		if (!flag[i])
		{
			prime[++cnt]=i;
			mu[i]=mod-1;
		}
		for (int j=1;j<=cnt&&i*prime[j]<=n;++j)
		{
			flag[i*prime[j]]=1;
			if (i%prime[j]==0)
			{
				mu[i*prime[j]]=0;
				break;
			}
			mu[i*prime[j]]=mod-mu[i];
		}
	}
	for (int i=1;i<=n;++i)
	{
		if (n%i) continue;
		f[i]=calc(i);
	}
}

void solve()
{
	for (int i=1;i<=n;++i)
	{
		for (int j=i;j<=n;j+=i)
		{
			add(g[j],Mul(f[i],mu[j/i]));
		}
	}
	int ans=Mul(b[n]+1,n+n);
	for (int i=1;i<=n;++i)
	{
		if (!f[i]) continue;
		int tmp=Mul(n+n-i-i,g[i]);
		sub(ans,tmp);
	}
	printf("%d\n",ans);
}

