int solve(int n, int k) {
	int need = k;
	for (int iter = 0;;iter++) {
		if (need == k && iter > 0) {
			return iter;
		}

		if (k & 1) {
			k /= 2;
		} else {
			k /= 2;
			k += 1 << (n - 1);
		}
	}
}

