int dva[maxn];

int eval(int d) {
	int l = n / d;
	int ans = 0;
	for (int i = 0; i < l; i++) {
		if (x[i] == '1') {
			ans += dva[l - i - 1];
			ans %= base;
		}
	}
	bool ok = true;
	for (int i = 0; i < n; i++) {
		int m = i / l;
		int nd = x[i % l] - '0';
		if (m % 2) {
			nd ^= 1;
		}
		int hv = x[i] - '0';
		if (hv < nd) {
			ok = false;
			break;
		}
		if (hv > nd) {
			break;
		}
	}
	return ans + ok;
}

