        REP(i, N) if(sgn[i] == -2) {
            pairs tmp;
            tmp.pb(Pii(i, 1));
            sgn[i] = 1;

            int now = i;
            while(true){
                int prev = now, ss = sgn[prev];
                now = (now - D + 2 * N) % (2 * N);
                if(now >= N){
                    now -= N;
                    ss *= -1;
                } 
                if(now == i && ss == 1) break;
                else if(sgn[now] != -2){
                    if(sgn[now] != ss){
                        f = false;
                        break;
                    }
                }else{
                    sgn[now] = ss;
                    tmp.pb(Pii(now, ss));
                }
            }
            if(!f) break;
            ps.pb(tmp);
        }
        if(!f) continue;

        cnt[x] = 0;
        int m = SZ(ps);
        vec X0(N);
        REP(i, m){

            int i0 = ps[i][0].f;
            int x0 = X[i0] - '0';

            if(X[i0] - '0' == 1){
                cnt[x] += pow((mint)2, m - 1 - i);
            }
            for(auto tt: ps[i]){
                if(tt.s == 1) X0[tt.f] = x0;
                else X0[tt.f] = 1 - x0;
            }
        }
        bool not_large = true;
        REP(i, N){
            if(X0[i] > X[i] - '0'){
                not_large = false;
                break;
            }else if(X0[i] < X[i] - '0') break;
        }
        if(not_large) cnt[x] += 1;
    }
    mint ans = 0;
    REP(i, n){
        REP(j, i) if(d[i] % d[j] == 0) cnt[i] -= cnt[j];
        ans += (mint)d[i] * cnt[i]; 
    }
    //vdebug(d);
    //vdebug(cnt);
    Out(ans);

    return 0;
}

