#define MOD   998244353LL

ll solve(ll n, const string &x, ll div)
{
    ll count = 0LL;
    rep (i, div) {
        count *= 2LL;
        count %= MOD;
        if (x[i] == '1') {
            count++;
            count %= MOD;
        }
    }
    count++;
    count %= MOD;

    rep (i, n) {
        char divc = x[i%div];
        if ((i/div)&1LL) divc = (divc == '0' ? '1' : '0');
        if (x[i] < divc) {
            count--;
            while (count < 0LL) count += MOD;
        }
        if (x[i] != divc) break;
    }

    return count;
}

