int main(int argc, const char * argv[]) {
    ios_base::sync_with_stdio(false);
    int N;
    string X;
    cin >> N >> X;

    set<int> Div;
    for (int n = 1; n * n <= N; ++n) {
        if (N % n == 0) {
            Div.emplace(n);
            Div.emplace(N/n);
        }
    }

    ll Res = 0;
    map<int, ll> mapDivToNum;
    for (int d : Div) {
        int Rep = N/d;
        if (Rep%2 == 0) continue;
        int Score = 2 * d;

        ll Temp = 0;
        for (int i = 0; i < d; ++i) {
            (Temp *= 2) %= MOD;
            if (X[i] == '1') (Temp += 1) %= MOD;
        }
        string A = X.substr(0, d);
        string B;
        for (char a : A) {
            if (a == '0') B.push_back('1');
            else B.push_back('0');
        }
        string Y;
        for (int r = 0; r < Rep; ++r) {
            if (r % 2 == 0) {
                Y += A;
            } else {
                Y += B;
            }
        }
        if (Y <= X) {
            (Temp += 1) %= MOD;
        }

        (Temp += mapDivToNum[d]) %= MOD;

        for (int d2 : Div) {
            if (d2 % d == 0) {
                (mapDivToNum[d2] += (MOD - Temp)) %= MOD;
            }
        }

        (Res += Score * Temp) %= MOD;
    }

    cout << Res << endl;

    return 0;
}

