const int N=200005,P=998244353;

int n,q[N],f[N];char s[N];

int biger(int x,int y,int len,int t){
	rep(i,1,len)if((s[x+i-1]^t)!=s[y+i-1])return (s[x+i-1]^t)>s[y+i-1]?1:-1;
	return 0; 
}

int solve(int x){
	bool flag=1;
	for(int i=1,t=0;i<=n;i+=x,t^=1){
		int tmp=biger(1,i,x,t);
		if(tmp==-1)break;
		if(tmp==1){flag=0;break;}
	}
	int k=0;
	rep(i,1,x){
		k=k*2+(s[i]&1);
		k%=P;
	}
	return (k+(flag==1))%P;
}

signed main(){
	rd(n);scanf("%s",s+1);
	rep(i,1,n){
		if(n%i==0&&n/i%2==1)q[++*q]=i;
	}
	rep(i,1,*q){
		f[i]=solve(q[i]);
	}
	int ans=0;
	rep(i,1,*q){
		rep(j,1,i-1){
			if(q[i]%q[j]==0&&q[i]/q[j]%2==1){
				(f[i]+=P-f[j])%=P;
			}
		}
		(ans+=q[i]*2%P*f[i]%P)%=P;
	}
	pt(ans,'\n');
	return 0;
}

