const int maxn = 200010, P = 998244353;
int n, ans, f[maxn], g[maxn][2];
char s[maxn];

int main() {
    scanf("%d %s", &n, s + 1);
    g[0][0] = 1;
    for (int i = 1; i <= n; i++) if (!(n % i)) {
        if (!((n / i) & 1)) continue;
        for (int j = 1; j <= i; j++) {
            g[j][0] = g[j][1] = 0;
            for (int t = 0; t < 2; t++) {
                (g[j][1] += g[j - 1][1]) %= P;
                char c = t + '0';
                if (c <= s[j]) (g[j][c < s[j]] += g[j - 1][0]) %= P;
            }
        }
        bool flag = 1;
        for (int j = i + 1; j <= n; j++) {
            char c = s[j % i == 0 ? i : j % i];
            if (!(((j + i - 1) / i) & 1)) c ^= 1;
            if (c > s[j]) { flag = 0; break; }
            if (c < s[j]) break;
        }
        f[i] = g[i][1];
        if (flag) (f[i] += g[i][0]) %= P;
        for (int j = 1; j < i; j++) if (!(i % j)) {
            f[i] = (f[i] - f[j] + P) % P;
        }
        ans = (ans + 2LL * i * f[i]) % P;
    }
    printf("%d\n", ans);
    return 0;
}

