void ad(int &x, int y) { if ((x += y) >= md)x -= md; }
void sb(int &x, int y) { if ((x -= y) <  0 )x += md; }

bool fl(int x){
	f(i, x, n)z[i] = z[i - x] ^ 1;
	f(i, 0, n)if (z[i] < s[i])return true;
	else if (z[i] > s[i])return false;
	return true;
}

void go(int x){
	x >>= 1;
	f(i, 0, x){
		if (s[i] == '1')ad(dp[x << 1], p2[x - i - 1]);
		z[i] = s[i];
	}
	if (fl(x))ad(dp[x << 1], 1);
}

