	f(i, 1, n2 + 1)if (n % i && n2 % i == 0)ok[i] = true;
	f(i, 1, n2 + 1)if (ok[i])go(i);
	f(i, 1, n2 + 1)if (ok[i])for (int j = i << 1; j <= n2; j += i)sb(dp[j], dp[i]);
