void dfs(int v) {
    used[v] = 1;
    for (int to : g[v]) {
        if (!used[to]) {
            dfs(to);
        }
    }
}

void restore(int v) {
    used[v] = 1;
    for (int i = 0; i < g[v].size(); ++i) {
        const int to = g[v][i];
        if (!used[to]) {
            t[to] = ((t[v] - '0') ^ x[v][i]) + '0';
            restore(to);
        }
    }
}

void clr() {
    memset(used, 0, sizeof(used));
    for (int i = 0; i < n; ++i) {
        g[i].clear();
        x[i].clear();
    }
    ids.clear();
    digits.clear();
}

int solve(int d) {
    int res = 0;
