        res = 1;
        for (int i = 0; i < n; ++i) {
            if (s[i] == '1') {
                res += pw[n - 1 - i];
                res %= mod;
            }
        }
        return res;
    }
    clr();
    for (int i = 0; i < n; ++i) {
        int from = i, to = (i + n - d) % n;
        if (from > to) {
            swap(from, to);
        }
        const int val = i < d;
        g[from].push_back(to);
        g[to].push_back(from);
        x[from].push_back(val);
        x[to].push_back(val);
    }
    //cout << "###" << d << ": ";
    for (int i = 0; i < n; ++i) {
        if (!used[i]) {
            dfs(i);
            ids.push_back(i);
            digits.push_back(s[i] - '0');
            //cout << i << " ";
        }
    }
    for (int i = 0; i < digits.size(); ++i) {
        if (digits[i]) {
            res += pw[digits.size() - 1 - i];
            res %= mod;
        }
    }
    memset(used, 0, sizeof(used));
    for (int i = 0; i < digits.size(); ++i) {
        t[ids[i]] = s[ids[i]];
        restore(ids[i]);
    }
    //cout << t << " " << s << endl;
    res += (t <= s);
    res %= mod;
    //cout << endl;
    return res;
}

