            if (d * d != i && d != 1) {
                f[i] -= f[i / d];
            }
        }
        // cout << i << " " << f[i] << endl;
    }

    int res = 0;
    for (int i = 1; i <= n; ++i) {
        int cur = f[i];
        mul(cur, 2 * i);
        add(res, cur);
    }

    cout << res << endl;

#ifdef LOCAL
    cerr << "Time: " << double(clock()) / CLOCKS_PER_SEC << endl;
#endif
}

