const int N=200010;
const int M=12000010;
const LL MOD=998244353;
using namespace std;

int n;
char s[N];
int b[N],d[N],cnt=0;
LL c[N];

void READ(){
	scanf("%d",&n);
	scanf("%s",s+1);
	rep(i,1,n)b[i]=s[i]-'0';
}

void GETK(){
	for(int i=1;i*i<=n;i++){
		if(n%i)continue;
		if(i&1)d[++cnt]=n/i;
		if(i*i==n)continue;
		if((n/i)&1)d[++cnt]=i;	
	}
	sort(d+1,d+cnt+1);
}

LL GET(int x){
	LL now=0;
	rep(i,1,x){
		now=now*2%MOD+b[i];
		now%=MOD;
	}
	int pos=0,flg=1,val;
	rep(i,1,n){
		pos=pos%x+1;
		if(pos==1)flg^=1;
		val=b[pos]^flg;
		if(val<b[i])return (now+1)%MOD;
		if(val>b[i])return now;
	}
	return (now+1)%MOD;
}

void SOLVE(){
	LL ans=0;
	rep(i,1,cnt){
		c[i]=GET(d[i]);
		rep(j,1,i-1)if(d[i]%d[j]==0)c[i]=(c[i]-c[j]+MOD)%MOD;
		ans+=c[i]*d[i]%MOD*2%MOD;ans%=MOD;
	}
	printf("%lld\n",ans);
}

int main(){
	READ();
	GETK();
	SOLVE();
	return 0;
}

