int f(int x, int n){
	int f = x, res = 0;
	do{
		if(x%2==0) x+=1<<n;
		x>>=1;
		++res;
	}while(x!=f);
	return res;
}

int g(int x, int n){
	string s;
	for(int i=0;i<n;++i,x/=2) s+=char(x%2+'0');

	for(int k=2;k<=n;k+=2) if(n%(k/2)==0){
		string t = s.substr(k);
		for(int i=0;i<k;++i) t+=s[i]^1;
		if(t==s){
			//assert(k%2==0);
			//assert(n%(k/2) == 0);
			assert(n/(k/2)%2==1);
			return k;
		}
	}
	return n*2;
}

int g2(int x, int n){
	string s;
	for(int i=0;i<n;++i,x/=2) s+=char(x%2+'0');

	for(int k=1;k<=n;k++) if(n%k==0 && n/k%2){
		bool ok = true;
		for(int i=0;i<n;++i) ok&=s[i] == (s[i%k]^(i/k%2));
		if(ok) return k*2;
	}
	return -1;
}

vector<int> divs[N];

const int mod = 998244353;

ll solve(string X){
	int n = X.size();

	for(int i=1;i<=n;++i) divs[i].clear();
	for(int i=1;i<=n;++i) for(int j=i;j<=n;j+=i) if((j/i)%2==1) divs[j].push_back(i);

	vector<int> p2(n+1);
	for(int i=p2[0]=1; i<=n; ++i) p2[i]=p2[i-1]*2 %mod;

	vector<int> F(n+1);

	ll ans = 0;

	vector<int> h(n+1);
	for(int k : divs[n]){
		bool ok = true;
		for(int i=0;i<n;++i){
			ok&= X[i] == (X[i%k]^(i/k%2));
			if(!ok){
				h[k] = i;
				break;
			}
		}
		if(ok) h[k] = n;
	}

	for(int pref=0;pref<=n;++pref){
		if(X[pref]=='0') continue;

		int len = (pref==n ? n : pref + 1);
		for(int k : divs[n]){
			if(len <= k){
				F[k] = p2[k-len];
				for(int k2 : divs[k]) if(k2<k){
					F[k]-=F[k2];
					if(F[k]<0) F[k]+=mod;
				}
			}else{
				bool ok = h[k]>len-2;
				char c = pref<n ? '0' : '1';
				ok&= c==(X[(len-1)%k]^((len-1)/k%2));
				F[k] = ok;
			}
			ans+= 2LL*k*F[k];
			ans%=mod;
			//cerr<<"?"<<pref<<": "<<k<<": "<<F[k]<<endl;
		}
	}



	return ans;
}

bool doit(){
