	pw2[0] = 1;
	for (int i=1; i < 300000; ++i) pw2[i] = mult(2, pw2[i-1]);

	int n;
	cin >> n;

	string x;
	cin >> x;
	int total = 0;
	int pw = 1;
	for (int i=x.size()-1; i >= 0; i--){
		if (x[i] == '1') total = sum(total, pw);
		pw = mult(pw, 2);
	}


	int l = -1;
	for (int i=1; i <= n; ++i){
		if ((i / __gcd(i, n)) % 2 == 0){
			l = i;
			break;
		}
	}

	if (l==-1){
		cout << mult(total, mult(2, n));
		exit(0);
	}

	int q = l;

	int res=0, spec=0;

	vector<int> num = {0};

	for (l=q; l <= n; l += q){
		if ((2*n)%l!=0){
			num.push_back(0);
			continue;
		}
		int tut=0;
		data.assign(l, {});
		used.assign(l, false);
		int G = __gcd(n, l);
		//cout << G << endl;
		for (int i=0; i < l; ++i){
			int T = (i-G+l)%l;
			data[i].push_back(T);
			data[T].push_back(i);
		}


		int cmp = 0;
		for (int i=0;i<l; ++i){
			if (used[i]) continue;
			dfs2(i);
			cmp++;
		}

		conc.assign(l, -1);

