		for (int i=0; i < n; ++i){
			//cout << i << " " << cmp << endl;
			if (conc[i%l] == -1){
				if (x[i] == '0'){
					cmp--;
					dfs(i%l, 0);
				}
				else{
					tut = sum(tut, pw2[cmp-1]);
					cmp--;
					dfs(i%l, 1);
				}
			}
			else if (conc[i%l] == 0){
				if (x[i] == '1'){
					tut = sum(tut, pw2[cmp]);
					if_out = true;
					break;
				}
				else continue;
			}
			else{
				if (x[i] == '0'){
					if_out=true;
					break;
				}
				else continue;
			}
		}
		if (!if_out) tut = sum(tut, 1);
		for (int j=1; j < num.size(); ++j){
			if ((l/q)%j == 0){
				tut = sum(tut, -num[j]);
			}
		}
		num.push_back(tut);
		//tut = sum(tut, -spec);
		spec = sum(spec, tut);
		res = sum(res, mult(tut, l));

		//cout << l << " " << tut << endl;
	}

	total = sum(total, 1);


	res = sum(mult(2*n, sum(total, -spec)), res);

	cout << res;
}

