        ll y = x/2;
        bool able = 1;
        cnt = 0;

        for(ll i=0; i<y; i++){
            if(arr[i+1] == 0) continue;
            ll tmp = pow2[y-i-1];
            ans += (tmp * x) % MOD;
            ans %= MOD;
            cnt += tmp;
            cnt %= MOD;
        }

        for(ll i=y+1; i<=n; i++){
            ll tmpn = (i-1)%y;
            bool tmp;
            if(((i-1)/y)%2 == 1){
                tmp = !arr[tmpn+1];
            }
            else{
                tmp = arr[tmpn+1];
            }

            if(arr[i] == 0 && tmp == 1){
                able = 0;
                break;
            }
            else if(arr[i] == 1 && tmp == 0){
                break;
            }
        }

        if(able){
            ans += x;
            ans %= MOD;
            cnt++;
            cnt %= MOD;
        }

        for(auto &tmp: cand){
            if(tmp > x && tmp%x == 0 && (tmp/x)%2 == 1){
                ans -= (cnt * tmp) % MOD;
                ans += 2LL*MOD;
                ans %= MOD;
            }
        }
    }

    printf("%lld", ans);
}

