using bs = bitset<MAX_N>;

int n;
modlong from_bs(bs x) {
    modlong ans=0, pow=1;
    for (int i=0; i<n; i++) {
        if (x[i]) ans += pow;
        pow *= 2;
    }
    return ans;
}

int main() {
    bs x;
    cin >> n >> x;
    modlong ans = 0, used[n+1];
    fill(used, used+n+1, 0);
    for (int i=n; i>0; i--) {
        if (i % 2 == 1 && n % i == 0) {
            int res = 1, step = n / i;
            for (int j = step+1; j<=n; j++) {
                bool ref = x[n - j % step] ^ (((j - 1) / step) % 2);
                if (x[n - j] > ref) 
                    break;
                else if (x[n - j] < ref) {
                    res = 0;
                    break;
                }
            }
            modlong add = from_bs(x >> (n - step)) + (res ? 1 : 0) - used[step];
            ans += add * step * 2;
            for (int k=step; k<=n; k+=step) used[k] += add;
        }
    }
    cout << ans << '\n';
    return 0;
}

