long long solve(int k)
{
        if(good(0, k) == false){
                return 0;
        }

        int l = 0, r = k;
        while(l < r){
                int m = (l + r) / 2;
                if(good(m + 1, k)){
                        l = m + 1;
                } else{
                        r = m;
                }
        }

        int res = 0;
