long long constexpr mod = 998244353LL;

class llm{
    long long l;
    static std::unordered_map<long long, llm> inv;

public:
    llm(long long m = 0LL) : l((m % mod >= 0)?(m % mod):(m % mod + mod)) {};

    llm inverse() const {
        if(inv.find(l) == inv.end()){
            llm x = pow(mod - 2);
            inv.emplace(l, x);
            return x;
        }
        return inv[l];
    }

    llm pow (long long i) const {
        if (i < 0)  return inverse().pow(-i);
        if (i == 0) return 1;
        long long int x = pow(i / 2) % mod;
        if (i % 2 == 0) {
            return x * x % mod;
        }else {
            return x * x * l % mod;
        }
    }

    llm operator= (llm m) {l = m.l; return *this;}

    llm operator<< (long long i) const {return pow( i);};
    llm operator>> (long long i) const {return pow(-i);}

    llm operator+ (llm m)       const {return llm(l + m.l);}
    llm operator+ (int m)       const {return llm(l + (m % mod));}
    llm operator+ (long m)      const {return llm(l + (m % mod));}
    llm operator+ (long long m) const {return llm(l + (m % mod));}

    llm operator- (llm m)       const {return llm(l - m.l);}
    llm operator- (int m)       const {return llm(l - (m % mod));}
    llm operator- (long m)      const {return llm(l - (m % mod));}
    llm operator- (long long m) const {return llm(l - (m % mod));}

    llm operator* (llm m)       const {return llm(l * m.l);}
    llm operator* (int m)       const {return llm(l * (m % mod));}
    llm operator* (long m)      const {return llm(l * (m % mod));}
    llm operator* (long long m) const {return llm(l * (m % mod));}

    llm operator/ (llm m)       const {return llm((*this) * m.inverse() % mod);}
    llm operator/ (int m)       const {return llm(l * llm(m).inverse()) % mod;}
    llm operator/ (long m)      const {return llm(l * llm(m).inverse()) % mod;}
    llm operator/ (long long m) const {return llm(l * llm(m).inverse()) % mod;}

    long long operator++ (void) {return l = (l + 1) % mod;}
    long long operator++ (int)  {long long tmp = l; ++(*this); return tmp;}

    long long operator-- (void) {return l = (l - 1) % mod;}
    long long operator-- (int)  {long long tmp = l; --(*this); return tmp;}

    llm operator+ (void) const {return llm( l);}
    llm operator- (void) const {return llm(-l);}

    template<typename T> llm operator+= (T m) {return *this = *this + m;}
    template<typename T> llm operator-= (T m) {return *this = *this - m;}
    template<typename T> llm operator*= (T m) {return *this = *this * m;}
    template<typename T> llm operator/= (T m) {return *this = *this / m;}

    operator long long() {return l;}

    friend istream &operator>>(istream &stream, llm &m);

};

unordered_map<long long, llm> llm::inv;

std::istream& operator>> (istream &stream, llm &m) {
    long long tmp;
    stream >> tmp;
    m.l = tmp % mod;
    return stream;
}

bool g(deque<bool> x, deque<bool> y, int N){
    bool flag = true;
    for(int i = N - 1; i >= 0; --i){
        if (x[i]) {
            if(y[i]){
                continue;
            } else {
                flag = false;
                break;
            }
        } else {
            if (y[i]) {
                break;
            } else {
                continue;
            }
        }
    }
    return flag;
}

int main(void){
    cin.tie(0); ios::sync_with_stdio(false);

    int N;

    cin >> N;

    deque<bool> x(N, false);

    for0(i, N){
        char a;
        cin >> a;
        if (a == '1') x[N - i - 1] = true;
    }

    llm result = 1;

    for0(i, N){
        if (x[i]) {
            llm a = llm(2).pow(i);
            result += a;
        }
    }

    int dec = 0;
    int add = 0;

    for1n(i, N / 3){
        int inc = 0;

        if ((N - i) % (2 * i) == 0) {
            deque<bool> y(N, false);

            for0(j, N){
                if ((j / i) % 2 == 0) y[j] = true;
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }

            for0(j, N){
                y[j] = !y[j];
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }
        }
        add += 2 * i * inc;
    }

    for1n(i, N / 6){
        int inc = 0;
        if (((N - 2 * i) % 4 * i) == 0){
            bool now = true;

            deque<bool> y(N, false);
            for0(j, N){
                if (now) {
                    if(j % (2 * i) <= 1){
                        y[j] = 1;
                    } else {
                        y[j] = 0;
                    }
                } else {
                    if(j % (2 * i) <= 1){
                        y[j] = 0;
                    } else {
                        y[j] = 1;
                    }
                }
                if (j % (2 * i) == 2 * i - 1) now = !now;
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }

            for0(j, N){
                y[j] = !y[j];
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }
        }
        add += 4 * i * inc;
    }

    result += dec;

    result *= 2 * N;

    result += add;

    cout << result;

    return 0;
}

