std::vector<int> enumerateDivisors(ll n) {
	std::set<int> set;
	for (int i = 1; i * i <= n; ++i) {
		if (n % i) continue;
		set.insert(i);
		set.insert(n / i);
	}
	std::vector<int> res(set.size());
	int p = 0;
	for (const auto& x : set) {
		res[p++] = x;
	}
	return res;
}

int convert(std::string s) {
	int res = 0;
	int now = 1;
	RREP(i, s.size()) {
		if (s[i] == '1') (res += now) %= MOD;
		(now *= 2) %= MOD;
	}
	return res;
}

