		SHOW(ans);
		return 0;
	}

	VAR(int, n);
	VAR(std::string, s);

	auto ds(enumerateDivisors(n));

	int rest = 1 + convert(s);
	int add = 0;

	V<int> v(ds.size());
	int idx = -1;
	for (const auto& d : ds) {
		++idx;
		if (n / d % 2 == 0) continue;
		std::string S(s.substr(0, d));

		bool ok = [&] {
			REP(i, s.size()) {
				char c = S[i % S.size()];
				if (i / S.size() % 2 == 1) {
					c = (c == '0') ? '1' : '0';
				}
				if (c > s[i]) return false;
				if (c < s[i]) return true;
			}
			return true;
		}();
		if (ok) {
			++v[idx];
		}

		v[idx] += convert(S);
	}

	REP(i, ds.size()) FOR(j, i + 1, ds.size()) {
		if (ds[j] % ds[i] == 0 && ds[j] / ds[i] % 2 == 1) {
			v[j] -= v[i];
		}
	}
	REP(i, ds.size()) {
		(rest -= v[i]) %= MOD;
		(add += ds[i] * 2 * v[i]) %= MOD;
	}

	(rest *= n * 2) %= MOD;
	int ans = (rest + add) % MOD;
	if (ans < 0) ans += MOD;

	OUT(ans)BR;

	return 0;
}

