void solve1(int d) {
  int k = n / d;
  if (!(k & 1)) {
    return;
  }
  {
    int val = 0;
    for (int i = 0; i < d; i++) {
      val = mul(val, 2);
      add(val, s[i] - '0');
    }
    add(cnt[d], val);
  }
  bool ok = true;
  for (int i = 0; i < n; i++) {
    int cur = s[i % d] - '0';
    if ((i / d) & 1) {
      cur ^= 1;
    }
    if (s[i] < (char) ('0' + cur)) {
      ok = false;
      break;
    } else if ((char) ('0' + cur) < s[i]) {
      break;
    }
  }
  if (ok) {
    add(cnt[d], 1);
  }
}

void solve() {
  for (int i = 0; i <= n; i++) {
    cnt[i] = 0;
  }
  for (int d = 1; d * d <= n; d++) {
    if (n % d) {
      continue;
    }
    solve1(d);
    if (d * d != n) {
      solve1(n / d);
    }
  }
  int res = 0;
  for (int i = 1; i <= n; i++) {
    if (n % i || !((n / i) & 1)) {
      continue;
    }
    if (!cnt[i]) {
      continue;
    }
    add(res, mul(cnt[i], 2 * i));
    for (int j = 2 * i; j <= n; j++) {
      if (n % j || !((n / j) & 1)) {
        continue;
      }
      add(cnt[j], mod - cnt[i]);
    }
  }
  printf("%d\n", res);
}

