ll f(int a){
  ll r = 0;
  FOR(i, 0, a) r = (r*2+b[i])%MOD;
  FOR(i, 1, n/a) FOR(j, 0, a) {
    bool c = b[i*a+j];
    bool d = (i%2)^b[j];
    if(c<d) return r;
    if(c>d) return r+1;
  }
  return r+1;
}
struct Prime{
  vector<ll> pl;
  void init(int a){ // a以下の素数列挙
    pl.resize(0);
    vector<bool> z(a+1, true);
    for(int i=2; i<=a; i++) if(z[i]){
      pl.push_back(i);
      for(int b=i*2; b <= a; b+=i) z[b]=false;
    }
  }
  void division(ll a, vector<pair<ll, int>> &v){
    v.resize(0);
    for(ll b: pl){
      if(b*b > a) break;
      if(a%b) continue;
      v.push_back({b, 0});
      while(a%b==0) a/=b, v.back().second++;
    }
    if(a>1) v.push_back(make_pair(a, 1));
  }
} pl;
