		for(int j = i + i; j <= 2 * n; j += i) {
			divs[j].pb(i);
		}
	}
	REPN(i, 2, 2 * n) {
		if ((2 * n) % i == 0 && i % 2 == 0 && ((2 * n) / i) % 2 == 1) {
			int len = i / 2;
			REP(j, 0, len) {
				ans[len] = (ans[len] * 2 + s[j] - '0') % MOD;
			}
			REP(j, 0, n) {
				d[j] = s[j % len];
				if ((j / len) % 2 == 1) {
