				}
			}
			if (strcmp(d, s) <= 0) {
				ans[len] = (ans[len] + 1) % MOD;
			}
			REP(j, 0, SZ(divs[len])) {
				ans[len] = (ans[len] + MOD - ans[divs[len][j]]) % MOD;
			}
		}
	}
	ll sum = 0ll;
	REPN(i, 0, 2 * n) {
		sum = (sum + ans[i] * 2 * i) % MOD;
