#include <bits/stdc++.h>

int main(){
    using namespace std;
    constexpr unsigned long MOD = 998244353;
    unsigned long N;
    cin >> N;
    vector<unsigned long> X(N);
    {
        string S;
        cin >> S;
        transform(S.begin(), S.end(), X.begin(), [](auto i){return i & 1;});
        transform(S.begin(), S.end(), back_inserter(X), [](auto i){return ~i & 1;});
    }
    vector<unsigned long> pow2(N);
    pow2[0] = 1;
    for(unsigned long i = 1; i < N; ++i)pow2[i] = pow2[i - 1] * 2 % MOD;
    const auto& answer = [&](auto x) -> unsigned long{
        unsigned long ret{0}, out{3 * x + 1}, safe{3 * x};
        for(unsigned long i = 0; i < x; ++i){
            if(X[i])ret += pow2[x - i - 1];
            auto t = X[i];
            for(unsigned long j = i; j < N; j += x){
                if(X[j] > t){
                    safe = min(safe, j);
                    break;
                }
                if(X[j] < t){
                    out = min(out, j);
                    break;
                }
                t ^= 1;
            }
        }
        return (ret + (safe < out)) % MOD;
    };
    vector<unsigned long> factor;
    {
        unsigned long i{1};
        for(; i * i < N; ++i)if(!(N % i)){
                factor.push_back(i);
                factor.push_back(N / i);
            }
        if(i * i == N)factor.push_back(i);
    }
    sort(factor.begin(), factor.end());
    vector<unsigned long> ans(N + 1);
    for(const auto& i : factor)if(i & 1){
        ans[N / i] = answer(N / i);
    }
    for(const auto& i : factor){
        for(const auto& j : factor){
            if(i % j == 0 && i != j)ans[i] += MOD - ans[j];
        }
        ans[i] %= MOD;
    }
    unsigned long a{0};
    for(unsigned long i = 0; i <= N; ++i)a += ans[i] * i % MOD;
    cout << (a * 2) % MOD << endl;
    return 0;
}

