    int N; string X; cin >> N >> X;

    int ans = 0;
    for (int d : divisors(N)) {
        int m = N/d;
        if (m%2 == 0) continue;
        string s = X.substr(0, d);
        (cnt[d] += val(s)) %= MOD;

        string t, r = s; inv(r);
        for (int i = 0; i < m; ++i) i%2 == 0 ? t += s : t += r;
        if (t <= X) ++cnt[d] %= MOD;

        for (int j = 2*d; j <= N; j += d) if (N%j == 0) (cnt[j] += MOD-cnt[d]) %= MOD;
        (ans += 2ll*d*cnt[d]%MOD) %= MOD;
    }
    cout << ans;
}

