typedef long long ll;
int n;
ll f[N];
char s[N];
bool vis[N];
vector<int>v;
int main()
{
    scanf("%d",&n);
    scanf("%s",s+1);
    for(int i=1;i<=n;i++) s[i+n]='1';
    for(int i=1;i*i<=2*n;i++)
        if(2*n%i==0)
    {
        if(i&1)
            v.push_back(i);
        if(2*n/i!=i&&(2*n/i&1)) v.push_back(2*n/i);
    }
    for(int l=0;l<v.size();l++)
    {
        int k=2*n/v[l],t=k/2;vis[k]=true;
        string a="",b="";
        for(int i=1;i<=t;i++) f[k]=((f[k]<<1)+s[i]-'0')%mod,a+=s[i],b+=s[i]=='1'?'0':'1';
        bool flag=true,ff=false;
        int p=0;
        for(int j=t;j+t<=2*n;j+=t)
        {
            p^=1;
            if(p)
            {
                for(int h=1;h<=t;h++)
                    if(s[j+h]!=b[h-1])
                    {
                        if(s[j+h]<b[h-1]) flag=false;
                        ff=true;
                        break;
                    }
            }
            else
            {
                for(int h=1;h<=t;h++)
                    if(s[j+h]!=a[h-1])
                    {
                        if(s[j+h]<a[h-1]) flag=false;
                        ff=true;
                        break;
                    }
            }
            if(ff) break;
        }
        f[k]+=flag;
    }
    ll ans=0;
    for(int i=2;i<=2*n;i+=2)
        if(vis[i])
    {
        for(int j=i+i;j<=2*n;j+=i)
            if(vis[j])
            f[j]=(f[j]-f[i])%mod;
        ans=(ans+f[i]*i)%mod;
    }
    ans=(ans+mod)%mod;
    printf("%lld\n",ans);
}

