typedef long long ll;
typedef long double ld;
const int MAXN = 200005;
const ll MOD = 998244353;
char str[MAXN];
int y[MAXN];
struct Mint {
	int val;
	Mint() { val = 0; }
	Mint(const ll& x) {
    val = (-MOD <= x && x <= MOD) ? x : x % MOD;
		if (val < 0) val += MOD;
  }
	friend bool operator==(const Mint& a, const Mint& b) { return a.val == b.val; }
	friend bool operator!=(const Mint& a, const Mint& b) { return !(a == b); }
	friend bool operator<(const Mint& a, const Mint& b) { return a.val < b.val; }
	Mint& operator+=(const Mint& m) { if ((val += m.val) >= MOD) val -= MOD; return *this; }
  Mint& operator-=(const Mint& m) { if ((val -= m.val) < 0) val += MOD; return *this; }
  Mint& operator*=(const Mint& m) { val = (ll)val * m.val % MOD; return *this; }
  friend Mint pow(Mint a, ll p) {
		Mint ans = 1;
		for (; p; p >>= 1, a *= a) if (p & 1) ans *= a;
		return ans;
	}
  Mint& operator/=(const Mint& m) { return *this *= pow(m, MOD - 2); }
  Mint& operator++() { return *this += 1; }
  Mint& operator--() { return *this -= 1; }
  Mint operator++(int) { Mint result(*this); *this += 1; return result; }
  Mint operator--(int) { Mint result(*this); *this -= 1; return result; }
  Mint operator-() const { return Mint(-val); }
  friend Mint operator+(Mint a, const Mint& b) { return a += b; }
	friend Mint operator-(Mint a, const Mint& b) { return a -= b; }
	friend Mint operator*(Mint a, const Mint& b) { return a *= b; }
	friend Mint operator/(Mint a, const Mint& b) { return a /= b; }
	friend ostream& operator<<(ostream& os, const Mint& x) { return os << x.val; }
};
Mint g[MAXN * 2], p2[MAXN * 2];
int main() {
	p2[0] = 1;
	for (int i = 1; i < MAXN * 2; ++i) p2[i] = p2[i - 1] * 2;
	int n;
	scanf("%d%s", &n, str);
	for (int d = 1; d < 2 * n; ++d) {
		if (2 * n % d || n % d == 0) {
			g[d] = 0;
			continue;
		}	
		assert(d % 2 == 0);
		// y[i] = y[i + d]
		for (int i = 0; i < d / 2; ++i) {
			if (str[i] == '1') {
				g[d] += p2[d / 2 - i - 1];
			}
			y[i] = str[i] - '0';
		}
		bool same = true;
		for (int i = d / 2; i < n; ++i) {
			y[i] = 1 - y[i - d / 2];
			if (y[i] < str[i] - '0') {
				break;
			}
			if (y[i] > str[i] - '0') {
				same = false;
				break;
			}
		}
		if (same) ++g[d];
		for (int e = d + d; e <= 2 * n; e += d) {
			g[e] -= g[d];
		}
	}
	++g[2 * n];
	for (int i = 0; i < n; ++i) {
		if (str[i] == '1') {
			g[2 * n] += p2[n - i - 1];
		}
	}
	Mint ans = 0;
	for (int d = 1; d <= 2 * n; ++d) {
		ans += g[d] * d;
	}
	printf("%lld\n", ans.val);
}

