#include <bits/stdc++.h>

using namespace std;
typedef long long ll;
const int N = 200010;
const int MOD = 998244353;
int _w;

void add_mod( int &a, int b ) {
	a += b;
	a -= a >= MOD ? MOD : 0;
}

void sub_mod( int &a, int b ) {
	a -= b;
	a += a < 0 ? MOD : 0;
}

int mu[N];

int calc_mu( int x ) {
	int ans = 1;
	for( int i = 2; i*i <= x; ++i )
		if( x % i == 0 ) {
			x /= i;
			ans = -ans;
			if( x % i == 0 ) return 0;
		}
	if( x != 1 ) ans = -ans;
	return ans;
}

void init_mu() {
	for( int i = 1; i < N; ++i )
		mu[i] = calc_mu(i);
}

int n, a[N];
char str[N];

vector<int> fac;

void factor( int x ) {
	for( int i = 1; i <= x; i += 2 )
		if( x % i == 0 )
			fac.push_back(x/i);
	sort(fac.begin(), fac.end());
}

int get_num( int len ) {
	int x = 0;
	for( int i = 1; i <= len; ++i ) {
		x = (x * 2 + a[i]) % MOD;
	}
	return x;
}

int chk[N];

int check( int len ) {
	for( int i = 1; i <= len; ++i ) {
		chk[i] = a[i];
		for( int j = len+i; j <= n; j += len )
			chk[j] = 1 - chk[j-len];
	}
	for( int i = 1; i <= n; ++i ) {
		if( chk[i] < a[i] )
			return 1;
		else if( chk[i] > a[i] )
			return 0;
	}
	return 1;
}

int calc( int len ) {
	int rtn = get_num(len);
	add_mod(rtn, check(len));
	return rtn;
}

int ans[N];

void solve() {
	for( int len : fac ) {
		int tmp = calc(len);
		// printf( "calc(%d) = %d\n", len, tmp );
		add_mod( ans[len], tmp );
		for( int j = len+len; j <= n; j += len ) {
			if( mu[j/len] == 1 ) {
				add_mod( ans[j], tmp );
			} else if( mu[j/len] == -1 ) {
				sub_mod( ans[j], tmp );
			}
		}
	}
	int tot = 0;
	for( int i : fac ) {
		add_mod( tot, int(1LL * ans[i] * i * 2 % MOD) );
		// printf( "ans[%d] = %d\n", i, ans[i] );
	}
	cout << tot << endl;
}

int main() {
	_w = scanf( "%d", &n );
	_w = scanf( "%s", str+1 );
	for( int i = 1; i <= n; ++i )
		a[i] = str[i] - '0';
	factor(n);
	init_mu();
	solve();
	return 0;
}

