#include <bits/stdc++.h>

using namespace std;

const int N = 2e5 + 5;
const int mod = 998244353;
inline int pls( int a , int b ) { a += b - mod; return a + ( a >> 31 & mod ); }
inline int mns( int a , int b ) { a -= b; return a + ( a >> 31 & mod ); }
inline void inc( int & a , int b ) { a += b - mod; a += a >> 31 & mod; }
inline void dec( int & a , int b ) { a -= b; a += a >> 31 & mod; }
int _w;

int n , f[N];
char str[N] , tmp[N];
bool mark[N];

int solve( int k ) {
  int res = 0;
  for( int i = 1 ; i <= k ; ++i )
    inc( res , pls( res , str[i] - '0' ) );
  for( int i = 1 , cur = 1 ; i <= n ; ++i , cur = cur >= 2 * k ? 1 : cur + 1 ) 
    if( cur > k ) tmp[i] = str[cur - k] ^ 1;
    else tmp[i] = str[cur];
  for( int i = 1 ; i <= n ; ++i )
    if( tmp[i] ^ str[i] )
      return tmp[i] < str[i] ? pls( res , 1 ) : res;
  return pls( res , 1 );
}

int main( void ) {
  _w = scanf("%d%s",&n,str+1);
  for( int i = 1 ; i <= n ; ++i )
    if( n % i == 0 && ( ( n / i ) & 1 ) )
      f[i] = solve( i ) , mark[i] = 1;
  for( int i = 1 ; i <= n ; ++i ) if( mark[i] ) 
    for( int j = i + i ; j <= n ; j += i ) if( mark[j] )
