        }
        string str = s.substr(0, k / 2);
        rep(i, k / 2) str.push_back('0' + '1' - str[i]);
        while(str.size() < t.size())
            str += str.substr(0, k);
        if(str <= t) a += 1;
        cnt.push_back(a);
    }

    rep(i, cnt.size()) FOR(j, i + 1, cnt.size()) if(v[j] % v[i] == 0) cnt[j] -=
        cnt[i];

    modint ans(0);
    rep(i, cnt.size()) ans += cnt[i] * modint(v[i]);

    cout << ans << endl;

    return 0;
}

