const int N = 1e6 + 5;
const int p = 998244353;

int sum(int a, int b) {
    a += b;
    return a < p ? a : a - p;
}

int mul(long long a, int b) {
    return a * b % p;
}

int powx(int a, int b) {
    int ans = 1;
    while (b) {
        if (b & 1) ans = mul(ans, a);
        a = mul(a, a);
        b >>= 1;
    }
    return ans;
}

int n;
int ans = 0;
string s;

int count_primes(int n) {
    int cnt = 0;
    for (int i = 2; n != 1; ++i) {
        while (n % i == 0) {
            ++cnt;
        }
    }
    return cnt;
}

int dp[N];

bool solve(int d) {
    if (n % d != 0 || (n / d) % 2 == 0) return false;
    int cnt = 0;
    for (int i = 0; i < d; ++i) {
        cnt = sum(cnt, cnt);
        cnt += s[i] - '0';
    }
    string ns(s.size(), '0');
    for (int i = 0; i < n; ++i) {
        if (i < d) {
            ns[i] = s[i];
        } else {
            ns[i] = '0' + (1 - (ns[i - d] - '0'));
        }
    }
    if (ns <= s) cnt = sum(cnt, 1);
    dp[d] = cnt;
    return true;
}

