#ifdef ONPC
    freopen("input", "r", stdin);
#endif
    cin >> n >> s;
    vector<int> cool;
    for (int i = 1; i <= n; ++i) {
        if (solve(i)) cool.push_back(i);
    }
    for (int i : cool) {
        for (int j : cool) {
            if (j <= i) continue;
            if (j % i == 0) {
                dp[j] = sum(dp[j], p - dp[i]);
            }
        }
    }
    for (int i = 1; i <= n; ++i) {
        ans = sum(ans, mul(2 * i, dp[i]));
    }
    cout << ans << '\n';
}

