const int MD = 998244353;
const int MX = 200005;
int n;
long long m[MX], ans, sm, y;
string x;
map<int, long long> mp;
int gcd(int x, int y){
	if(x < y) swap(x, y);
	while(y){
		x %= y;
		swap(x,y);
	}
	return x;
}
void setmap(int t){
	int u = t;
	long long f = 0;
	for(; u < n && x[u-t] != x[u]; u++);
	rep(i,t) f = (f*2 + x[i] - '0') % MD;
	if(u == n || x[u] == '1') f++;
	mp[t] = f;
}
int main(){
	cin >> n >> x;
	for(int i = 1; i*i <= n; i++) if(!(n%i)){
		setmap(i);
		if(i*i != n) setmap(n/i);
	}
	y = x[0] - '0';
	for(int i = 1; i < n; i++){
		int t = gcd(i,n);
		if(i/t % 2 == 0){
			m[i] += mp[t];
			sm += m[i];
			ans = (ans + m[i] * i) % MD;
			for(int j = i*2; j < n; j += i) (m[j] -= m[i]) %= MD;
		}
		y = (y*2 + x[i] - '0') % MD;
	}
	(ans += (y+1 - sm + MD) * 2*n) %= MD;
	printf("%lld\n", ans);
}

