bool weak_bigger(bs2e5 a, bs2e5 b) {
  rep (i_, n) {
    int i = n-1 - i_;
    if (a[i] < b[i]) {
      return true;
    }
    if (a[i] > b[i]) {
      return false;
    }
  }
  return true;
}

ll count(int d, bs2e5 & bs) {
  assert (d >= 3);
  int section_size = n / d;
  ll ret = 0;
  auto cbs = bs2e5();
  rep (i, section_size) {
    if (bs[n-1 - i]) {
      ret = (ret + po2[section_size - 1 - i]) % mod;
      cbs[n-1 - i] = true;
    }
    //debug(ret);
  }
  cbs |= (cbs >> section_size);
  rep (i, section_size) {
    cbs.flip(n-1 - section_size - i);
  }
  int css = section_size * 2;
  while (true) {
    cbs |= (cbs >> css);
    css *= 2;
    if (css >= n) {
      break;
    }
  }
  //debug(cbs.to_string().substr(maxn - n, n));
  //debug(bs.to_string().substr(maxn - n, n));
  if (weak_bigger(cbs, bs)) {
    ret = (ret + 1) % mod;
  }
  return ret;
}

