struct Divisor {
    long long N;
    vector<long long> result;
    vector<pair<long long, int>> c;

    Divisor(long long n) { 
        N = n;
        calc();
    }

    void calc() {
        long long d = N;
        for (long long i = 2; i * i <= d; i++) {
            int count = 0;
            while (d % i == 0) {
                d /= i; count++;
            }
            if (count) c.emplace_back(i, count);
        }
        if (d != 1) c.emplace_back(d, 1);
        rec(0, 1);
        sort(result.begin(), result.end());
    }

    void rec(int index, int cur) {
        if (index == c.size()) {
            result.emplace_back(cur);
            return;
        }
        for (int i = 0; i <= c[index].second; i++) {
            rec(index+1, cur);
            cur *= c[index].first;
        }
    }
};

int main() {
    int n; cin >> n;
    string s; cin >> s;
    long long all = 0; vector<long long> memo(n, 0);
    for (int i = 0; i < n; i++) {
        all *= 2; all += s[i] - '0';
        all %= mod; memo[i] = all;
    }
    all = (all+1) * n % mod * 2 % mod;
    Divisor d(n);
    vector<int> t;
    for (auto &x: d.result) {
        if (x == 1) continue;
        if (x & 1) t.emplace_back(x); 
    }

    map<int, long long> m;
    for (auto &x: t) {
        int h = n * 2 - n * 2 / x;
        for (auto &it: m) {
            if (x % it.first == 0) h = (h + mod - it.second) % mod;
        }
        m[x] = h;
        int loop = n / x;
        long long cnt = memo[loop-1]+1;
        for (int i = 0; i < n; i++) {
            int a = i / loop;
            int b = s[i % loop] - '0';
            if (a & 1) b = !b;
            if (s[i] - '0' < b) {
                cnt--; break;
            } else if (s[i] - '0' != b) {
                break;
            }
        }
        long long sub = cnt * m[x] % mod;
        all = (all - sub + mod) % mod;
    }
    cout << all << endl;
    return 0;
}

