	for(int i = 1; i <= N; i++) if(use[i]) {
		cnt[i] %= mod;
		for(int j = 2*i; j <= N; j += i) cnt[j] -= cnt[i];
		ans = (ans + 2LL * i * cnt[i]) % mod;
	}
	if(ans < 0) ans += mod;
	cout << ans << "\n";
	return 0;
}

