map<ll, ll> factorize(ll x) {
  map<ll, ll> res;
  for (ll i = 2; i * i <= x; ++i) {
    while (x % i == 0) {
      ++res[i];
      x /= i;
    }
  }
  if (x != 1) {
    ++res[x];
  }
  return res;
}

