int main() {
  ll N;
  cin >> N;
  vector<ll> div;
  for (int i = 1; i <= N; i += 2)
    if (N % i == 0) div.pb(i);
  string S;
  cin >> S;
  int sz = div.size();
  vector<ll> co(sz);
  rep(i, sz) {
    ll block = div[i];
    ll len = N / block;
    string head = S.substr(0, len);
    string head_rev = head;
    replace(all(head_rev), '0', '2');
    replace(all(head_rev), '1', '0');
    replace(all(head_rev), '2', '1');
    ll headnum = 0;
    rep(j, len) {
      headnum *= 2;
      headnum = headnum % mod;
      headnum += (S[j] - '0');
    }
    string sub;
    for (int j = 0; j < block; ++j) {
      sub = S.substr(len * j, len);
      if (j % 2 == 0) {
        if (head > sub) {
          break;
        } else if (head < sub) {
          ++headnum;
          break;
        }
      } else {
        if (head_rev > sub) {
          break;
        } else if (head_rev < sub) {
          ++headnum;
          break;
        }
      }
      if (j == block - 1) {
        ++headnum;
        break;
      }
    }
    co[i] = headnum % mod;
  }

  for (int i = sz - 1; i >= 0; --i) {
    for (int j = 0; j < i; ++j) {
      if (div[i] % div[j] == 0) {
        co[j] -= co[i];
      }
    }
  }
  ll ans = 0;
  rep(i, sz) {
    ans += 2 * N / div[i] * co[i];
    ans = ans % mod;
  }
  cout << ans << endl;

  return 0;
}

