const ll M = 998244353;
int st[MN];
bitset<MN> dv;
vi fac;
ll ct[MN];
inline ll mul(ll a, ll b) {return (a*b)%M;}
inline ll norm(ll n) {return ((n%M)+M)%M;}
int main() {
	ios::sync_with_stdio(0);cin.tie(0);
	int n;
	cin >> n;
	string s;
	cin >> s;
	for(int i=0;i<n;i++) {
		st[i] = s[i]-'0';
	}
	for(int i=1;i<=n;i+=2) {
		if(!(n%i)) {
			dv.set(n/i);
			fac.push_back(i);
		}
	}
	for(int i=0;i<fac.size();i++) {
		ll val = 0;
		ll sz = n/fac[i];
		ll sub = 0;
		for(int i=0;i<sz;i++) {
			val *= 2;
			val += st[i];
			val %= M;
		}
		for(int i=sz;i<n;i++) {
			if(st[i] > 1-st[i-sz]) {
				break;
			}
			if(st[i] < 1-st[i-sz]) {
				sub = 1;break;
			}
		}
		val += 1-sub;
		val %= M;
		ct[sz] = val;
	}
	for(int i=1;i<=n;i++) {
		if(dv[i]) {
			for(int j=2;j*i<=n;j++) {
				if(dv[i*j]) {
					ct[i*j] -= ct[i];
					ct[i*j] = norm(ct[i*j]);
				}
			}
		}
	}
	ll res = 0;
	for(int i=0;i<=n;i++) {
		if(dv[i]) {
			res += norm(2*i*ct[i]);
		}
	}
	cout << norm(res) << '\n';
}

