  for (long long i = 1; i * i <= N; i++) {
    if (N % i == 0) {
      if (i & 1) div.push_back(i);
      if (i * i < N && ((N / i) & 1)) div.push_back(N / i);
    }
  }
  sort(div.rbegin(), div.rend());
  int M = div.size();
  Mint dp[M];
  for (int i = 0; i < M; i++) {
    int D = N / div[i];
