int N;
string X;
ll ans = 0;

ll calc(int t) {
    // t 周期
    ll num = 0;
    rep(i, t) {
        num <<= 1;
        num += X[i] - '0';
        num %= MOD;
    }
    num++;
    rep(i, N) {
        int digit = X[i % t] - '0';
        if ((i / t) % 2 == 1) digit = 1 - digit;
        // dump(i, t, digit, X[i] - '0');
        if (digit == 0 && X[i] == '1') {
            break;
        }
        if (digit == 1 && X[i] == '0') {
            (num += MOD - 1) %= MOD;
            break;
        }
    }
    // dump(t, num);
    return num;
}

int main() {
    cin >> N >> X;
    vll num(N + 1, 0);
    num[N] = 0;
    rep(i, N) {
        num[N] <<= 1;
        num[N] += X[i] - '0';
        num[N] %= MOD;
    }
    num[N]++;

    repr(i, 1, N) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            num[i] = calc(i);
            // dump(i, num[i]);
        }
    }
    vvi divs(N + 1);
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            repr(j, 1, sqrt(N) + 1.5) {
                if (i % j == 0) {
                    if (j != i) {
                        divs[i].push_back(j);
                    }
                    if (j < i / j && i / j != i) {
                        divs[i].push_back(i / j);
                    }
                }
            }
        }
    }
    repr(i, 2, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            for (auto d : divs[i]) {
                // dump(i, d, num[d]);
                (num[i] += MOD - num[d]) %= MOD;
            }
            // dump(i, num[i]);
        }
    }
    ll ans = 0;
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            (ans += num[i] * 2 * i) %= MOD;
            // dump(i, num[i], ans);
        }
    }
    cout << ans << endl;

    return 0;
}

