    return os;
}

// list up all factors
template <typename T>
set<T> factors(T a) {
    set<T> facs;
    for (T i = 1; i * i <= a; ++i) {
        if (a % i == 0) {
            facs.insert(i);
            facs.insert(a / i);
        }
    }
    return facs;
}

int main() {
    int n;
    cin >> n;
    string x;
    cin >> x;
    auto facs = factors(n);
    facs.erase(n);
    mint ret   = 1;
    mint twoes = 1;
    for (int i = 0; i < n; ++i) {
        if (x[n - 1 - i] == '1')
            ret += twoes;
        twoes *= 2;
    }
    ret *= 2 * n;
    map<int, mint> cnt;
    for (auto it = facs.begin(); it != facs.end(); it = next(it)) {
        int f = *it;
        if ((n / f) % 2 == 0) {
            continue;
        } else {
            mint curr  = 0;
            mint times = f;
            mint twoes = 1;
            for (int i = f - 1; i >= 0; --i) {
                if (x[i] == '1')
                    curr += twoes;
                twoes *= 2;
            }
            string edge = x.substr(0, f);
            string orig = edge;
            string rev  = "";
            for (int j = 0; j < f; ++j) {
                if (edge[j] == '0')
                    rev += "1";
                else
                    rev += "0";
            }
            for (int j = 0; j < n / f - 1; ++j) {
                if (j % 2 == 0)
                    edge += rev;
                else
                    edge += orig;
            }
            if (edge <= x)
                curr += 1;
            for (auto &p : cnt) {
                if (f % p.first == 0)
                    curr -= p.second;
            }
            cnt[f] = curr;
            ret -= curr * 2 * n;
            ret += curr * 2 * times;
        }
    }
    cout << ret << "\n";

    return 0;
}

