int main()
{
	ll N;
	std::string X;
	cin >> N >> X;

	//Nの約数のうち奇数のものを求める
	lls oddVec;
	for (ll i = 1; i <= N; i++) {
		if (i * i > N) break;

		if (N % i != 0) continue;
		if (i % 2 == 1) oddVec.push_back(i);

		if (i != N / i) {
			if ((N / i) % 2 == 1) oddVec.push_back(N / i);
		}
	}
	//降順にソート
	std::sort(oddVec.begin(), oddVec.end(),
		[](ll& a, ll& b) {return a > b; }
	);

	//Xのはじめのn桁の数値を計算 valVec[n-1]
	lls valVec(N);
	{
		ll sum = 0;
		for (ll i = 0; i < N; i++) {
			sum = sum * 2 + (X[i] - '0');
			sum %= MOD;
			valVec[i] = sum;
		}
	}

	//---- 場合の数を計算
	lls baaiNumVec(oddVec.size());

	for (ll i=0;i<oddVec.size();i++){
		ll y = oddVec[i];
		ll bitNum = N / y;

		//X以下か判定
		bool isXika = true;
		for (ll idx = bitNum; idx < N; idx++) {
			if (X[idx - bitNum] != X[idx]) continue;
			if (X[idx] == '1') isXika = true;
			else isXika = false;
			break;
		}
		//場合の数
		ll baaiNumOrg;
		if (isXika) baaiNumOrg = valVec[bitNum-1] + 1;
		else        baaiNumOrg = valVec[bitNum - 1];

		//重複を引く
		for (ll j = 0; j < i; j++) {
			ll big_y = oddVec[j];
			if (big_y % y != 0) continue;

			baaiNumOrg = baaiNumOrg + (MOD - baaiNumVec[j]);
			baaiNumOrg %= MOD;
		}

		baaiNumVec[i] = baaiNumOrg;
	}

	//---- 総和計算
	{
		ll sum = 0;
		for (ll i = 0; i < oddVec.size(); i++) {
			ll y = oddVec[i];
			ll atai = (2 * N) / y;
			sum += (atai * baaiNumVec[i]);
			sum %= MOD;
		}
		cout << sum << '\n';
	}

	return 0;
}

