    memset(g, -1, sizeof(g));
    for(i = p[0] = 1; i < N; i ++)
        p[i] = (p[i - 1] << 1) % MOD;

    scanf("%d %s", &n, a);
    printf("%d\n", (Solve(n) + MOD) % MOD);

    return 0;
}

