const int MAXN = 2.1e5;
int N;
string X_;
bool X[MAXN];

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	cin >> N >> X_;
	for (int i = 0; i < N; i++) {
		X[i] = bool(X_[i] - '0');
	}

	num ans = 0;
	unordered_map<int, num> weights;
	for (int p = 1; p <= 2*N; p++) {
		if ((2*N) % p != 0 || N % p == 0) continue;
		assert(p % 2 == 0);

		num weight = 0;
		for (int i = 0; i < p/2; i++) {
			weight *= 2;
			weight += int(X[i]);
		}
		bool canEqual = true;
		for (int i = 0; i < N; i++) {
			bool v = X[i % (p/2)] ^ ((i / (p/2) & 1));
			if (v < X[i]) {
				break;
			}
			if (v > X[i]) {
				canEqual = false;
				break;
			}
		}
		weight += int(canEqual);

		for (auto it : weights) {
			if (p % it.first == 0) {
				weight -= it.second;
			}
		}
		ans += weight * p;
		weights[p] = weight;
	}
	cout << ans << '\n';

	return 0;
}

