        num += X[i] - '0';
        num %= MOD;
    }
    num++;
    rep(i, N) {
        int digit = X[i % t] - '0';
        if ((i / t) % 2 == 1) digit = 1 - digit;
        if (digit == 0 && X[i] == '1') {
            break;
        }
        if (digit == 1 && X[i] == '0') {
            (num += MOD - 1) %= MOD;
            break;
        }
    }
    return num;
}

