        num[N] <<= 1;
        num[N] += X[i] - '0';
        num[N] %= MOD;
    }
    num[N]++;

    repr(i, 1, N) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            num[i] = calc(i);
        }
    }
    // 約数列挙
    vvi divs(N + 1);
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            repr(j, 1, sqrt(i) + 1.5) {
                if (i % j == 0) {
                    if (j != i) {
                        divs[i].push_back(j);
                    }
                    if (j < i / j && i / j != i) {
                        divs[i].push_back(i / j);
                    }
                }
            }
        }
    }
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            for (int d : divs[i]) {
                (num[i] += MOD - num[d]) %= MOD;
            }
        }
    }
    ll ans = 0;
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // dump(i, num[i]);
            // 周期 i が成立
            (ans += num[i] * 2 * i) %= MOD;
        }
    }
    cout << ans << endl;

