int Calc(int len){
	int flag = 1,res = 0;
	for(int i = 1;i <= len;i++){
		if(s[i] == 1)
			res = (res + power[len - i]) % MOD;
	}
	for(int i = len + 1;i <= min(len << 1,n);i++){
		if(s[i] != (s[i - len] ^ 1)){
			flag = (s[i] > (s[i - len] ^ 1) ? 1 : 0);
			break;
		}
	}
	return (flag + res) % MOD;
}

