using namespace std;
char s[200007];
int mi2[200007],num[200007];
const int mod = 998244353;
int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    cout.tie(NULL);
    int n;
    cin>>n>>s;
    mi2[0]=1;
    for(int i=1;i<=n;++i)
        mi2[i]=2ll*mi2[i-1]%mod;
    for(int i=1;i<=n;i+=2)if(n%i==0){
        int length=n/i;
        bool flag=1;
        for(int j=0;j<n&&flag;++j){
            if(s[j]=='1'){
                if(j<length||s[j-length]=='1'){
                    num[length]=(num[length]+(j<length?mi2[length-j-1]:1))%mod;
                }
            }
            if(j>=length&&s[j]==s[j-length])
                flag=0;
        }
        if(flag)
            num[length]=(num[length]+1)%mod;
    }
    int ans=0;
    for(int i=1;i<=n;++i)if(n%i==0&&(n/i)&1&&num[i]){
        ans=(ans+2ll*num[i]*i)%mod;
        for(int j=i*2;j<=n;j+=i)
            num[j]=(num[j]+mod-num[i])%mod;
    }
    cout<<ans;
    return 0;
}

