const LL mod = 998244353;
const int MAXN = 201000;
LL cnt[MAXN];


int main() {
    ios::sync_with_stdio(false);
    cin.tie(0); // Remove in problems with online queries!
    int N;
    cin >> N;
    string X;
    cin >> X;
    LL res = 0;
    for (int d = 1; d <= N; d++) {
        if (N%d or (N%(2*d) == 0)) continue;
        LL a = 0;
        for (int i = 0; i < d; i++) a = (2*a + (X[i]=='1')) % mod;
        a++;
        for (int i = 0; i < N; i++) {
            char c = X[i%d];
            if ((i/d)%2 == 1) c = (c=='0')?'1':'0';
            if (c < X[i]) break;
            if (X[i] < c) {
                a--;
                break;
            }
        }
        cnt[d] = (cnt[d] + a)%mod;
        for (int z = 2*d; z <= N; z += d) cnt[z] = (cnt[z] - cnt[d])%mod;
        res = (res + cnt[d]*(2*d)) % mod;
    }
    if (res < 0) res += mod;
    cout << res << "\n";
}

