#define N 200005
#define ll long long
#define mod 998244353
char K[N];
int mul[N], f[N];
int n, ans, A[N];
void Getval(int x)
{
	for (int i = 1; i <= x; i++)
		if (A[i] == 1)
			f[x] = (f[x] + mul[x - i]) % mod;
	int flg = 0;
	for (int i = x + 1; i <= n; i++)
	{
		if (A[i] < !A[i - x])
		{
			flg = 1;
			break;
		}
		if (A[i] > !A[i - x])
			break;
	}
	if (!flg)
		f[x]++;
	for (int i = 1; i * i <= x; i++)
	{
		if (x % i == 0)
		{
			if (x != i && x / i % 2 == 1)
				f[x] = (f[x] - f[i]) % mod;
			if (i * i != x && i != 1 && i % 2 == 1)
				f[x] = (f[x] - f[x / i]) % mod;
		}
	}
	if (f[x] < 0)f[x] += mod;
}
int main()
{
	scanf("%d", &n);
	scanf("%s", K + 1);
	for (int i = 1; i <= n; i++)
		A[i] = K[i] - '0';
	mul[0] = 1;
	for (int i = 1; i <= n; i++)
		mul[i] = mul[i - 1] * 2ll % mod;
	for (int i = 1; i <= n; i++)
	{
		if (n % i == 0 && n / i % 2 == 1)
		{
			Getval(i);
			ans = (ans + f[i] * 2ll * i % mod) % mod;
		}
	}
	printf("%d\n", ans);
}

