	set<int> se;
	for(int i = 0; i < (1<<sz); ++ i) {
		int co = 0;
		int now = i;
		while(f(now, sz) != i) {
			now = f(now, sz);
			++ co;
		}
		if(se.find(co + 1) == se.end() && co + 1 != 2 * sz) {
			cerr << "example " << sz << " " << bitset<15>(i) << endl;
		}
		se.insert(co + 1);
	}
	return se;
}

string rev(string s) {
	int sz = (int)s.size();
	string res = "";
	rep(i, sz) {
		if(s[i] == '0') res += '1';
		else res += '0';
	}
	return res;
}

mint val(string s) {
	int sz = (int)s.size();
	mint res = 0;
	mint pw = (mint)1;
	per(i, sz) {
		if(s[i] == '1') res += pw;
		pw *= (mint)2;
	}
	return res;
}

vector<int> pf(int x) {
	vector<int> res;
	for(int i = 2; i * i <= x; ++ i) {
		if(x % i == 0) {
			res.pb(i);
			while(x % i == 0) x /= i;
		}
	}
	if(x != 1) res.pb(x);
	return res;
}

void solve() {
	// for(int i = 1; i <= 15; ++ i) {
	// 	cerr << i << " ";
	// 	for(auto x: cnt(i)) {
	// 		cerr << x << " ";
	// 	}
	// 	cerr << endl;
	// }
	int n; string x; cin >> n >> x;
	map<int, mint> mp;
	for(int d = 1; d * d <=2 * n; ++ d) {
		if((2 * n) % d == 0) {
			int d1 = d, d2 = (2 * n) / d1;
			if(d1 % 2 == 1) {
				//周期がd2
				string s = x.substr(0, d2 / 2);
				string revs = rev(s);
				string t = "";
				rep(i, d1) {
					if(i % 2 == 0) {
						t += s;
					} else {
						t += revs;
					}
				}
				if(t > x) {
					mp[d2] = val(s) - (mint)1;
				} else {
					mp[d2] = val(s);
				}
			}
			if(d2 % 2 == 1) {
				//周期がd1
				string s = x.substr(0, d1 / 2);
				string revs = rev(s);
				string t = "";
				rep(i, d2) {
					if(i % 2 == 0) {
						t += s;
					} else {
						t += revs;
					}
				}
				if(t > x) {
					mp[d1] = val(s) - (mint)1;
				} else {
					mp[d1] = val(s);
				}
			}
		}
	}
	mint ans = 0;
	for(auto p: mp) {
		int num = p.fr; mint co = p.sc;
		if(num == 0) continue;
		mint res = 0;
		auto pfs = pf(num);
		int sz = (int)pfs.size();
		for(int bit = 0; bit < (1<<sz); ++ bit) {
			int z = 1;
			rep(i, sz) {
				if(bit & (1<<i)) z *= pfs[i];
			}
			if(__builtin_popcount(bit) % 2 == 0) {
				res += mp[z];
			} else {
				res -= mp[z];
			}
		}
		ans += res * (mint)num;
	}
	cout << ans << endl;
}

