			for(int j = 0; j <= i; ++j) {
				if(s[j] == '0') {
					tmp += '1';
				} else {
					tmp += '0';
				}
			}
			for(int j = 0; j < n; ++j) {
				t += tmp[j % (i * 2 + 2)];
			}
			long long x = dp[i + 1][0] + (t <= s);
			f[i] = x % P;
			vis[i] = true;
		} 
	}

	for(int i = 1; i <= n; ++i) {
		if(vis[i - 1]) {
			for(int j = i + i; j <= n; j += i) {
				if(vis[j - 1]) {
					f[j - 1] = (f[j - 1] - f[i - 1] + P) % P;
				}
			}
		}
	}

	long long ans = 0;
	long long tot = (dp[n][0] + dp[n][1]) % P;
	for(int i = 0; i < n; ++i) {
		if(vis[i]) {
			tot = (tot - f[i] + P) % P;
		}
	}
	ans = (ans + tot * n * 2) % P;
	for(int i = 0; i < n; ++i) {
		if(vis[i]) {
			ans = (ans + f[i] * (i + 1) * 2) % P;
		}
	}

	cout << ans << '\n';

	return 0;
}

