    VL ansForDiv(d, 0);

    FOR(i,0,d-1) {
        int dv = divs[i];

        int freeBits = dv;
        VI info(dv, -1);

        int broken = 0;

        FOR(pref,0,n) {
            int pos = n - 1 - pref;

            int posInInfo = pos % dv;
            bool negatedInInfo = (pos / dv) % 2;

            bool didSet = false;
            bool didBreak = false;

            if (pref == n || x[pos]) {
                if (pref < n) {
                    int value = negatedInInfo xor (1 - x[pos]);

                    if (info[posInInfo] == -1) {
                        info[posInInfo] = value;
                        freeBits--;

                        didSet = true;
                    } else if (info[posInInfo] == 1 - value) {
                        broken++;

                        didBreak = true;
                    }
                }

                if (!broken) {
                    ansForDiv[i] += pows[freeBits];

                    if (ansForDiv[i] >= MOD) {
                        ansForDiv[i] -= MOD;
                    }
                }
            }

            if (pref < n) {
                if (didSet) {
                    info[posInInfo] = -1;
                    freeBits++;
                }

                if (didBreak) {
                    broken--;
                }

                int value = negatedInInfo xor x[pos];

                if (info[posInInfo] == -1) {
                    info[posInInfo] = value;
                    freeBits--;
                } else if (info[posInInfo] == 1 - value) {
                    broken++;
                }
            }
        }
    }

    VI sieve(n + 1, -1);

    FOR(i,2,n) if (sieve[i] == -1) {
        sieve[i] = i;

        for (int j = 2 * i; j <= n; j += i) if (sieve[j] == -1) {
            sieve[j] = i;
        }
    }

    VI mu(n + 1, 1);

    FOR(i,2,n) {
        int j = i / sieve[i];

        if (j % sieve[i] == 0) {
            mu[i] = 0;
        } else {
            mu[i] = -mu[j];
        }
