    VI ansForDivAfter(d, 0);

    FOR(i,0,d-1) FOR(j,0,i) if (divs[i] % divs[j] == 0) {
        ansForDivAfter[i] += mu[divs[i] / divs[j]] * ansForDiv[j];

        ansForDivAfter[i] %= MOD;
        if (ansForDivAfter[i] < 0) {
            ansForDivAfter[i] += MOD;
        }
    }

    long long ans = 0;

    int total = 1;
