    FOR(i,0,d-1) {
        int here = ansForDivAfter[i];

        ans = (ans + (long long) here * 2 * divs[i]) % MOD;

        total -= here;
        if (total < 0) {
            total += MOD;
        }
    }

    ans = (ans + (long long) total * 2 * n) % MOD;
    cout << ans;

    return 0;
}

