void cnt_pat_num(int pat_len) {
  if (cnt[pat_len] != -1) return;
  long long res = 0;
  long long cnter = 1;
  for (int i = pat_len - 1; i >= 0; i--) {
    if (x[i] == '1') res += cnter, res %= mod;
    cnter <<= 1;
    cnter %= mod;
  }
  bool def_smaller = false;
  bool def_larger = false;
  for (int k = 1; k < n / pat_len && !def_smaller && !def_larger; k++) {
    for (int i = 0; i < pat_len && !def_smaller && !def_larger; i++) {
      if (k % 2 == 0) {
        if (x[i] < x[k * pat_len + i]) def_smaller = true;
        else if (x[i] > x[k * pat_len + i]) def_larger = true;
      } else {
        if (x[i] == '1' && x[k * pat_len + i] == '1') def_smaller = true;
        else if (x[i] == '0' && x[k * pat_len + i] == '0') def_larger = true;
      }
    }
  }
  if (def_smaller || !def_larger) res++;
  cnt[pat_len] = res % mod;
  // cout << "cnt[" << pat_len << "] = " << cnt[pat_len] << endl;
  if (pat_len > 1) {
    for (int k = 1; k <= (int) sqrt(pat_len); k++) {
      if (pat_len % k == 0) {
        if ((pat_len / k) % 2 == 1) { // k = length of pattern
          cnt_pat_num(k);
          // cout << pat_len << "!: subtracting " << cnt[k] << endl;
          cnt[pat_len] -= cnt[k];
          if (cnt[pat_len] < 0) cnt[pat_len] += mod;
        }
        if (k % 2 == 1 && k > 1) { // pat_len / k = length of pattern
          cnt_pat_num(pat_len / k);
          // cout << pat_len / k << "!: subtracting " << cnt[pat_len / k] << endl;
          cnt[pat_len] -= cnt[pat_len / k];
          if (cnt[pat_len] < 0) cnt[pat_len] += mod;
        }
      }
    }
  }
}

int main() {
  memset(cnt, -1, sizeof cnt);
  cin >> n >> x;
  long long x2 = 0;
  for (int i = 0; i < x.size(); i++) {
    x2 <<= 1;
    x2 += x[i] == '1' ? 1 : 0;
    x2 %= mod;
  }
  long long res = ((x2 + 1) * 2 * n) % mod;
  for (int i = 1; i < n; i++) {
    if (n % i == 0 && (n / i) % 2 == 1) {
      cnt_pat_num(i);
      // cout << i << ": subtracting " << (cnt[i] * 2 * (n - i)) << endl;
      res -= (cnt[i] * 2 * (n - i)) % mod;
      if (res < 0) res += mod;
    }
  }
  cout << res << endl;
  return 0;
}

