auto solve_c(ll n, const string& s)->ll {
	auto s_bit = bitset<40>(s);
	ll ans = 0;
	unordered_map<ll, ll> mp;
	REP(i, s_bit.to_ullong() + 1) {
		ll cnt = 0;
		ll k = i;
		do {
			ll b = !(k & 1);
			k |= (b << n);
			k >>= 1;
			++cnt;
		} while (k != i);
		ans += cnt;
		mp[cnt]++;
	}
	return ans;
}

auto solve(ll n, const string& s) {

	VL dp(n + 1);
	FOR(i, 1, n + 1) {
		dp[i] = (dp[i - 1] << 1);
		dp[i] |= (s[i - 1] == '1');
		if (dp[i] >= MOD) { dp[i] %= MOD; }
	}
	dump(dp);

	VL ans_v(n + 1);
	FOR(i, 1, n + 1) {
		ll d = n / i;
		if (n % i > 0 || !(d & 1)) { ans_v[i] = -1; continue; }
		ll mx = dp[i];
		ans_v[i] += mx * i * 2;
		if (ans_v[i] >= MOD) { ans_v[i] %= MOD; }
		// ピッタリ賞
		bool ok = true;
		string t = s.substr(0, i);
		REP(j, n) {
			char base = s[j];
			char now = t[j % i];
			if ((j / i) & 1) { now = (now == '1') ? '0' : '1'; }
			if (base == '1' && now == '0') { break; }
			if (base == '0' && now == '1') { ok = false; break; }
		}
		if (ok) { ans_v[i] += i * 2; }
		if (ans_v[i] >= MOD) { ans_v[i] %= MOD; }
	}

	FOR(i, 1, n + 1)if (ans_v[i] > -1) {
		FOR(k, 2, n + 10) {
			ll ik = i * k;
			if (ik > n) { break; }
			if (ans_v[ik] == -1) { continue; }
			ll dec = (ans_v[i] * k);
			if (dec >= MOD) { dec %= MOD; }
			ans_v[ik] -= dec;
			if (ans_v[ik] < 0) { ans_v[ik] += MOD; }
		}
	}

	ll ans = 0;
	REPC(x, ans_v) if (x > -1) { 
		ans += x; 
		if (ans >= MOD) { ans -= MOD; }
	}
	return ans;
}
