    lint ret = 0;
    vector<lint> dp(N + 1);
    FOR(n, 1, N + 1)
    {
        if (n % 2 == 0) continue;
        if (N % n != 0) continue;
        string T = X;
        int shuki = N / n;
        FOR(i, shuki, N)
        {
            if ((i / shuki) % 2) T[i] = (char)(('1' - T[i % shuki]) + '0');
            else T[i] = T[i % shuki];
        }
        bool bad = false;
        REP(i, N)
        {
            int ddd = (int)(T[i] - (char)(X[i]));
            if (ddd < 0) break;
            if (ddd > 0) bad = true;
        }
        dp[n] = to_lint(X.substr(0, shuki)) + 1 - bad;
    }
    fast_integer_moebius(dp);
    REP(i, N + 1) if (i % 2 and dp[i]) ret = (ret + dp[i] * (N / i) % MOD * 2) % MOD;
    cout << ret << endl;
}

