    }
    if (y <= X) {
        cnt += 1;
    }

    return cnt;
}

ll solve() {
    vector<int> ls;
    for (int i = 1; i <= N; i++) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            ls.push_back(i);
        }
    }

    vector<gf> coeffs(ls.size());
    for (int i = (int)ls.size() - 1; i >= 0; i--) {
        coeffs[i] = 2 * ls[i];
        for (int j = i + 1; j < (int)ls.size(); j++) {
            if (ls[j] % ls[i] == 0 && (ls[j] / ls[i]) % 2 == 1) {
                coeffs[i] -= coeffs[j];
            }
        }
    }

    gf ans = 0;
    for (int i = 0; i < (int)ls.size(); i++) {
        ans += calc(ls[i]) * coeffs[i];
    }

    return ans.n;
}

int main() {
    cin >> N;
    cin >> X;

    cout << solve() << endl;

    return 0;
}

