const ll mod = 998244353; 
const int N = 500200; 

int n; 
int a[N], t[N]; 
int mx[N], mn[N]; 
ll F[N]; 

int main() {


  scanf("%d", &n); 
  for (int i = 1; i <= n; i++)
    scanf("%1d", &a[i]);
  for (int i = 1; i <= (n << 1); i++) {
    if ((n << 1) % i != 0 || !(((n << 1) / i) & 1)) 
      continue ; 
    for (int j = 1; j <= (n / (i / 2)); j++) 
      for (int k = 1; k <= i / 2; k++) {
        t[(j - 1) * (i / 2) + k] = (j % 2 == 1) ? a[k] : a[k] ^ 1;
    }
    ll C = 0; 
    for(int j = 1; j <= i / 2; j++) {
      C = (C * 2 % mod + t[j]) % mod; 
    }
    F[i] = C + (vector <int>(t + 1, t + n + 1) <= vector <int>(a + 1, a + n + 1)); 
  }
  ll ans = 0; 
  for (int i = 1; i <= 2 * n; i++) {
    if((2 * n % i == 0) && ((2 * n / i) & 1)) {
      ans = (ans + F[i] * i % mod) % mod; 
      for (int j = i + i; j <= 2 * n; j += i) {
        if((2 * n % j == 0) && ((2 * n / j) & 1))
          F[j] = (mod + (F[j] - F[i]) % mod) % mod; 
      }
    }
  }
  printf("%lld\n", ans); 
  return 0; 
}

