map<int, LL> memo;

LL Calc(int a) {
  int b = N/a;
  LL t = 0;
  rep(i, b) {
    t = t*2;
    if (X[i] == '1') ++t;
    t %= MOD;
  }

  bool nope = false;
  rep(i, N) {
    int idx = i%b;
    int val = X[idx]-'0';
    int times = i/b;
    if (times%2) {
      val = 1-val;
    }
    if (X[i]-'0' < val) {
      nope = true;
      break;
    }

    if (X[i]-'0' > val) {
      break;
    }
  }

  if (!nope) {
    ++t;
    //t += MOD-1;
    if (t >= MOD) t -= MOD;
  }
  return t;
}

signed main(){
  ios_base::sync_with_stdio(false);
