  cin >> X;

  LL ans = 0;
  rreps(a, 1, N+1) {
    if (a%2 == 0) continue;
    if (N%a) continue;
    memo[a] = Calc(a);
    //cout << a << ": " << memo[a] << endl;
    for (int t=a*3; t<=N; t+=a+a) {
      if (N%t) continue;
      assert(t%2);
      assert(memo.count(t));
      memo[a] += MOD - memo[t];
      if (memo[a] >= MOD) memo[a] -= MOD;
    }
    //cout << a << ": " << memo[a] << endl;
    int b = N/a;
    ans += 2 * memo[a] * b;
    ans %= MOD;
  }
  cout << ans << endl;
}

