template <typename T>
vector<T> prime_facs(T N){
    vector<T> ans;
    for(int i = 2; i*i <= N; i++){
        if(N%i == 0){
            ans.push_back(i);
            while(N%i == 0){
                N /= i;
            }
        }
    }
    if(N != 1) ans.push_back(N);
    return ans;
}

long pow[200001];

void init(){
    pow[0] = 1;
    for(int i = 1; i <= 200000; i++){
        pow[i] = pow[i-1]*2;
        pow[i] %= MOD;
    }
}

long count(int n){
    long ans = 1;
    int m = N/n;
    string pref;
    string pref1;
    for(int i = 0; i < n; i++){
        if(X[i] == '0'){
            pref += '0';
            pref1 += '1';
        }else{
            pref += '1';
            pref1 += '0';
            ans += pow[n-1-i];
            ans %= MOD;
        }
    }
    string cmp;
    for(int i = 0; i < m; i++){
        if(i%2 == 0) cmp += pref;
        else cmp += pref1;
    }
    if(cmp > X) ans--;
    ans += MOD;
    ans %= MOD;
    return ans;
}

int main(){
    init();
    cin >> N >> X;
    int M = N;
    long ans = 0;
    while(M%2 == 0){
        M /= 2;
    }
    vector<int> v;
    for(int i = 1; i*i <= M; i++){
        if(M%i == 0) {
            v.push_back(i);
            v.push_back(M/i);
        }
    }
    for(int i = 0; i < v.size(); i++){
        int K = N/v[i];
        vector<int> p = prime_facs(M/v[i]);
        int cnt = p.size();
        long tmp = 0;
        for(int j = 0; j < (1<<cnt); j++){
            long prod = 1;
            int c = 0;
            for(int k = 0; k < cnt; k++){
                if(j&(1<<k)){
                    c++;
                    prod *= p[k];
                }
            }
            if(c%2 == 0){
                tmp += count(N/(v[i]*prod));
            }else{
                tmp -= count(N/(v[i]*prod));
            }
            tmp %= MOD;
            tmp += MOD;
            tmp %= MOD;
        }
        tmp *= K*2;
        tmp %= MOD;
        ans += tmp;
        ans %= MOD;
    }
    cout << count(1) << endl;
    cout << count(3) << endl;
    cout << ans << endl;
}

