void Minus(vector<int> &x) {
	int i;

	x[0]--;
	if (x[0] < 0) {
		i = 1;
		while (true) {
			x[i - 1] += 2;
			x[i]--;
			if (x[i] >= 0) break;
			i++;
		}
	}
}

bool check(vector<int> &x, int d) {
	vector<int> y(n, 0);
	int i, j;

	int shift = 0;
	for (i = 0; i < n / d; i++) {
		if (i % 2 == 0) {
			for (j = 0; j < d; j++) {
				y[shift] += x[j];
				shift++;
			}
		}
		else {
			for (j = d - 1; j >= 0; j--) {
				y[shift] += x[j];
				shift++;
			}
		}
	}

	for (i = n - 1; i >= 0; i--) {
		int p = s[n - 1 - i] - '0';
		int q = y[i];
		if (q != p) {
			if (q > p) return false;
			return true;
		}
	}
	return true;
}

int calc(int d) {

	//まずは、2^((n/d)-1) * x <= int(s)なる最大のxを探す
	int i;
	vector<int> x;	//…x2x1x0 (10進数)
	x.resize(n - ((n / d) - 1));
	for (i = 0; i + ((n / d) - 1) < n; i++) {
		int val = s[i] - '0';
		x[n - ((n / d) - 1) - 1 - i] = val;
	}

	//x, x-1, x-2, x-3…あたりを試すと条件を満たす最大のxが分かる
	while (!check(x, d)) {
		Minus(x);
	}

	int ret = 0;
	int mul = 1;
	for (i = 0; i < x.size(); i++) {
		ret += x[i] * mul;
		ret %= mod;
		mul *= 2;
		mul %= mod;
	}
	return ret;
}

