typedef long long llong;

llong getX(string X) {
	int len = X.size();
	llong result = 0;
	REP(idx, len) {
		result *= 2;
		if (result > IMAX) {
			result %= IMAX;
		}
		if (X[idx] == '1') {
			++result;
		}
	}
	return result;
}
string getReverse(string X) {
	int len = X.size();
	string Y = "";
	REP(idx, len) {
		if (X[idx] == '0') {
			Y += '1';
		} else {
			Y += '0';
		}
	}
	return Y;
}

