int mul(int x, int y) {
	return (ll)x*y%mod;
}

int add(int x, int y) {
	int ret = (x + y);
	if (ret < 0) {
		ret += mod;
	}
	if (ret >= mod) {
		ret -= mod;
	}
	return ret;
}
int res[N];
void solve() {
	int n;
	string s;
	cin >> n >> s;
	int g = n; while (g % 2 == 0)g /= 2;
	int v = n / g;
	int pos = 0;
	int ar[N];
	for (int i = 1; i <= g; ++i) {
		if (g%i == 0) {
			ar[pos++] = i;
		}
	}
	int cc = 0;
	for (int i = 0; i < n; ++i) {
		cc = mul(cc, 2);
		cc = add(cc, s[i] - '0');
	}
	cc = add(cc, 1);
	int ret = 0;
	for (int i = 0; i < pos; ++i) {
		int size = n/ar[i];
		int bucket = ar[i];
		int tmp = 0;
		string tt[2];
		for (int j = 0; j < size; ++j) {
			tmp = mul(tmp, 2);
			tmp = add(tmp, s[j] - '0');
			tt[0] += s[j];
			if (s[j] == '0') {
				tt[1] += '1';
			}
			else {
				tt[1] += '0';
			}
		}
		string k;
		for (int x = 0; x < bucket; ++x) {
			k += tt[ (x &1)];
		}
		if (s >= k) {
			tmp = add(tmp, 1);
		}
		res[bucket] = tmp;
	}
	for (int i = g; i >= 1; --i) {
		if (g%i == 0 && res[i] > 0) {
			for (int j = i + i + i; j <= g; j += i) {
				if (g%j==0) {
					res[i] = add(res[i], -res[j]);
				}
			}
			int u = (n * 2) / i;
			ret = add(ret, mul(u, res[i]));
		}
	}
	printf("%d\n", ret);
}
