const ll mod = 998244353;
ll fact[200200];
ll invfact[200200];

inline ll take_mod(ll a){
    return (a % mod + mod) % mod;
}

inline ll add(ll a, ll b){
    return take_mod(a+b);
}

inline ll sub(ll a, ll b){
    return take_mod(a-b);
}


inline ll mul(ll a, ll b){
    return take_mod(a * b);
}

inline ll pow(ll x, ll n){
    ll res = 1LL;
    while(n > 0){
        if(n & 1) res = mul(res, x);
        x = mul(x, x);
        n >>= 1;
    }
    return res;
}

ll mod_inv(ll x){
    return pow(x, mod-2);
}

// nは上限
void make_fact(ll n){
    fact[0] = 1;
    ll res = 1;
    for(int i = 1; i <= n; i++){
        fact[i] = res;
        res = mul(res, i+1);
    }
}

// nは上限
void make_invfact(ll n){
    invfact[0] = 1;
    invfact[n] = mod_inv(fact[n]);
    for(int i = n-1; i >= 1; i--){
        invfact[i] = mul(invfact[i + 1], i + 1);
    }
}

ll perm(ll n, ll k){
    return mul(fact[n], invfact[n-k]);
}

ll comb(ll n, ll k){
    return mul(mul(fact[n], invfact[n-k]), invfact[k]);
}


vector<ll> getP(ll n){
    vector<ll> state;
    for(ll i = 1; i <= n; i++){
        if(n % i == 0 && (n / i) % 2 == 1){
            state.push_back(i);
        }
    }
    return state;
}

bool judgeJust(string x, int pos){
    string t[2];
    t[0] = x.substr(0, pos);
    string t2;
    for(int i = 0; i < pos; i++){
        if(x[i] == '1'){
            t2 += '0';
        }
        else{
            t2 += '1';
        }
    }
    t[1] = t2;

    for(int i = 0; i < x.length() / pos; i++){
        for(int j = 0; j < t[0].length(); j++){
            if(x[i * pos + j] > t[i%2][j]){
                return true;
            }
            else if(x[i * pos + j] < t[i%2][j]){
                return false;
            }
        }
    }
    return true;
}

int main(){
    ll N;
    cin >> N;
    string x;
    cin >> x;

    ll num = 0;
    ll already[210000];  fill(already, already+210000, 0);
    ll res = 0;
    ll total = 0;

    for(int i = 1; i <= N; i++){
        num = num * 2 + (x[i - 1] - '0');
        if(N % i == 0 && (N / i) % 2 == 1) {
            ll count = num;
            if (judgeJust(x, i)) {
                count++;
            }
            count = sub(count, already[i]);
            total = add(total, count);
            res = add(res, mul(count, 2 * i));

            ll now = i;
            while (now <= N) {
                already[now] = add(already[now], count);
                now += i;
            }
        }
    }

    cout << res << endl;

    return 0;
}

