int binpow(int a, int p)
{
    if (p == 0)
        return 1;
    if (p == 1)
        return a % mod;
    int b = binpow(a, p / 2);
    b = (b * b) % mod;
    if (p % 2)
        b = (b * a) % mod;
    return b;
}

bool ch(int u, string& s)
{
    if (u == n)
        return true;
    string kek = s.substr(0, u);
    for (int i = 0; i < u; i++)
        kek += ('0' + ('1' - kek[i]));
    string w = "";
    for (int i = 0; i <= (n / u) / 2; i++)
        w += kek;
    return w.substr(0, n) <= s;
}

void f(int u, string& s)
{
    //cout << u << "\n";
    int check = ch(u, s);
    //cout << "x";
    int cur = 0;
    for (int i = 0; i < u; i++)
    {
        if (s[i] == '0')
            continue;
        cur = (cur + binpow(2, u - i - 1)) % mod;
    }
    dp[u] = (cur + check) % mod;
}

