#include <bits/stdc++.h>
#define REP(i, n) for(int i = 0; i < n; i++)
#define REPR(i, n) for(int i = n; i >= 0; i--)
#define FOR(i, m, n) for(int i = m; i <= n; i++)
#define INF 2e9
#define IMAX 998244353
#define ALL(v) v.begin(), v.end()
using namespace std;
typedef long long llong;

llong getX(string X) {
	int len = X.size();
	llong result = 0;
	REP(idx, len) {
		result *= 2;
		if (result > IMAX) {
			result %= IMAX;
		}
		if (X[idx] == '1') {
			++result;
		}
	}
	return result;
}
string getReverse(string X) {
	int len = X.size();
	string Y = "";
	REP(idx, len) {
		if (X[idx] == '0') {
			Y += '1';
		} else {
			Y += '0';
		}
	}
	return Y;
}

llong checkPattern(string X) {
	llong len = X.size();
	llong maxBlock = len / 3;
	llong repeat;
	llong hosei = 0;
	FOR(iblock, 1, maxBlock) {
		// 初期リピート数3
		repeat = 3;
		while (iblock * repeat <= len) {
			// 文字数ピッタリ判定
			if (iblock * repeat == len) {
				// ブロック数を切り出す
				string firstBlock = X.substr(0, iblock);
				// パターン部分を整数化
				// この段階では 0 から (firstBlockの整数化) - 1
				llong firstNum = getX(firstBlock);
				// 上限チェック
				string firstPattern = firstBlock;
				for (int rIdx = 3; rIdx <= repeat; rIdx += 2) {
					firstPattern += getReverse(firstBlock);
					firstPattern += firstBlock;
				}
				if (X >= firstPattern) {
					 //最初のパターンは含まれるので1足す
					firstNum = (firstNum + 1) % IMAX;
				}

				hosei = (hosei + firstNum) % IMAX;
			}
			// repeat数+2
			repeat += 2;

		}
	}

	return hosei;
}

int main()
{
	// AGC039_C
	// ビット数
	llong N;
	cin >> N;
	// ビット数の上限文字列
	string X;
	cin >> X;

	// 通常の合計、N * 2 * (X + 1) を求める
	llong total = (N * 2 * (getX(X) + 1)) % IMAX;

	// 111000111
	// ブロック数(整数) * リピート数(3以上の奇数)
	llong maxBlock = N / 3;
	llong repeat;
	llong hosei = 0;
	FOR(block, 1, maxBlock) {
		// 初期リピート数3
		repeat = 3;
		while (block * repeat <= N) {
			// 文字数ピッタリ判定
			if (block * repeat == N) {
				// ブロック数を切り出す
				string firstBlock = X.substr(0, block);
				// パターン部分を整数化
				// この段階では 0 から (firstBlockの整数化) - 1
				llong firstNum = getX(firstBlock);
				// 上限チェック
				string firstPattern = firstBlock;
				for (int rIdx = 3; rIdx <= repeat; rIdx += 2) {
					firstPattern += getReverse(firstBlock);
					firstPattern += firstBlock;
				}
//				cout << firstBlock << endl;
//				cout << firstNum << endl;
//				cout << firstPattern << endl;
				if (X >= firstPattern) {
					 //最初のパターンは含まれるので1足す
					firstNum = (firstNum + 1) % IMAX;
				}
				// 中身がパターンになっている分は引く
				firstNum = firstNum - checkPattern(firstBlock);
				if (firstNum < 0) {
					firstNum += IMAX;
				}

				// 本来かかる手数(2N)からブロック長*2を引いた値が補正値
				hosei += (firstNum * (N - block) * 2) % IMAX;

			}

			// repeat数+2
			repeat += 2;
		}
	}

	// 補正値を引く
	total -= hosei;
	while (total < 0) {
		total += IMAX;
	}

	cout << total << endl;

	return 0;
}

