vector<int> divisors(int n) {
	vector<int> ret;
	for (int i = 2; i * i <= n; ++i) {
		if (n % i == 0) {
			ret.push_back(i);
		}
		while (n % i == 0) {
			n /= i;
		}
	}

	if (n > 1) {
		ret.push_back(n);
	}
	return ret;
}

map<int, MM> moeb(int n) {
	auto divs = divisors(n);
	int k = divs.size();

	map<int, MM> moe;
	REP(s, 0, 1 << k) {
		int prod = 1;
		int val = 1;
		REP(i, 0, k) {
			if (s & (1 << i)) {
				prod *= divs[i];
				val = -val;
			}
		}
		moe[prod] = val;
	}
	return moe;
}

MM sub(int k) {
	string T = S.substr(0, k);
	MM sum = 0;
	REP(i, 0, k) {
		sum *= 2;
		if (T[i] == '1') ++sum;
	}

	string Tp = T;
	for (auto&& c : Tp) {
		if (c == '1') {
			c = '0';
		} else {
			c = '1';
		}
	}

	string U;
	REP(z, 0, N / k) {
		U += T;
		U += Tp;
	}
	if (U <= S) ++sum;
	return sum;
}

MM A[400001];
MM B[400001];
int main() {
	cin >> N >> S;
	REP(i, 0, N) {
		S += S[i] ^ 1;
	}

	REP(k, 1, 2 * N + 1) {
		if (2 * N % k != 0) continue;
		int d = 2 * N / k;
		if (d % 2 == 0) continue;
		A[k] = sub(k / 2);
	}

	auto mp = moeb(2 * N);
	MM sum = 0;
	REP(k, 1, 2 * N + 1) {
		if (2 * N % k != 0) continue;
		for (auto p : mp) {
			int d = p.first;
			MM coeff = p.second;
			if (k % d != 0) continue;
			B[k] += coeff * A[k / d];
