string bar(string const &S)
{
  stringstream SS;
  for (auto x : S)
  {
    if (x == '0')
    {
      SS << '1';
    }
    else
    {
      SS << '0';
    }
  }
  return SS.str();
}

mint binary(string S)
{
  mint base{1};
  mint ans{0};
  reverse(S.begin(), S.end());
  for (auto x : S)
  {
    ans += base * (x - '0');
    base *= 2;
  }
  return ans;
}

string expand(string S, int K)
{
  assert(K % 2 == 1);
  string T{bar(S)};
  T += S;
  K = (K - 1) / 2;
  stringstream SS{};
  SS << S;
  for (auto i = 0; i < K; i++)
  {
    SS << T;
  }
  return SS.str();
}

mint count(int N, string const &X, int K)
{
  assert(N % K == 0);
  assert(K % 2 == 1);
  int L = N / K;
  string S{X.substr(0, L)};
  mint ans{binary(S)};
  string E{expand(S, K)};
  assert(static_cast<int>(E.size()) == N);
  if (E <= X)
  {
    ans += 1;
  }
  return ans;
}

using table = map<int, mint>;

table make_table(int N, string const &X)
{
  table t;
  for (auto i = 1; i <= N; i += 2)
  {
    if (N % i == 0)
    {
      mint c{count(N, X, i)};
      t[N / i] = c;
    }
  }
  for (auto &x : t)
  {
    for (auto i = 2;; i++)
    {
      int tmp{x.first * i};
      if (tmp > N)
      {
        break;
      }
      if (t.find(tmp) != t.end())
      {
        t[tmp] -= x.second;
      }
    }
  }
  return t;
}

mint calc(table const &t)
{
  mint ans{0};
  for (auto &x : t)
  {
    ans += static_cast<mint>(x.first) * x.second;
  }
  return ans * 2;
}

int main()
{
  int N;
  string X;
  cin >> N >> X;
  cout << calc(make_table(N, X)) << endl;
}

