using namespace std;
typedef long long ll;
const int MAXN = 200100;
const ll MOD = 998244353;

int N;
string X;
vector <int> pfac;
ll rv[MAXN];

ll gogo (int K)
{
    ll cv = 0;
    for (int i = 0; i < K; i++)
        cv = (2 * cv + (X[i] - '0')) % MOD;
    if (K == N) cv++;
    for (int i = K; i < N; i++)
    {
        int ov = 1 - (X[i-K] - '0');
        int nv = X[i] - '0';
        if (ov > nv)
        {
            break;
        }
        else if (ov < nv)
        {
            cv++;
            break;
        }
        else if (i == N - 1)
        {
            cv++;
            break;
        }
    }
    cv %= MOD;
    return cv;
}

int main()
{
    ios_base::sync_with_stdio(0);

    cin >> N;
    cin >> X;

    for (int i = 1; i <= N; i++)
    {
        if (N % i == 0)
        {
            if ((N / i) % 2 == 1)
                pfac.push_back(i);
        }
    }

    for (int i = 0; i < pfac.size(); i++)
    {
        rv[i] = gogo (pfac[i]);
        //cout << pfac[i] << " " << rv[i] << "\n";
    }

    for (int i = 0; i < pfac.size(); i++)
    {
        for (int j = i + 1; j < pfac.size(); j++)
            if (pfac[j] % pfac[i] == 0)
            {
                rv[j] -= rv[i];
            }
    }

    ll ans = 0;
    for (int i = 0; i < pfac.size(); i++)
    {
        //cout << pfac[i] << " " << rv[i] << "\n";
        ans = ans + (2 * pfac[i] * rv[i]);
        ans %= MOD;
    }
    cout << ans << "\n";
}

