const ll MOD = 998244353;

int n;

ll fooalgorithm(string &s, string &t, int l){
    ll res = 0;
    int p = 0;
    for(int i = 0; i < l * 2; i++){
        for(; p < n; p++){
            if(s[p] != t[i + p]){
                if(s[p] > t[i + p]){
                    if(i >= l) res++;
                    else{
                        res += l * 2 - i;
                        return res;
                    }
                }
                else{
                    if(i >= l){
                        return res;
                    }
                }
                break;
            }
        }
        if(p >= l * 2) p = 0;
    }
    return res;
}

int main()
{
    string x;
    cin >> n >> x;
    vector<int> v;
    ll ans = n * 2;
    ll b = 1;
    for(int i = n - 1; i >= 0; i--){
        if(x[i] == '1') ans = (ans + b * n * 2) % MOD;
        b = b * 2 % MOD;
    }
    for(int i = 3; i <= n; i += 2) if(n % i == 0) v.push_back(n / i);
    for(int j : v){
        string zero(j, '0');
        string one(j, '1');
        string s = one;
        for(int i = 0; i < (n / j) / 2 + 1; i++) s += zero + one;
//        cout << s << endl;
        ans = (ans - (n * 2 - j * 2) * fooalgorithm(x, s, j) + MOD) % MOD;
    }
    cout << ans << endl;
}

