const int CN = 210;

class fs{
  public: int to,nxt;
    void init(int t,int n) {to = t;nxt = n;}
}E[CN * CN];
int hd[CN],ecnt = 0;
void add(int x,int y) {E[++ecnt].init(y,hd[x]);hd[x] = ecnt;}

int n,ans = -1,ind[CN];

int dep[CN]; queue<int> Q;
int bfs(int s){
    memset(dep,0,sizeof(dep)); 
    Q.push(s); dep[s] = 1;
    while(!Q.empty()){
        int u = Q.front(); Q.pop();
        for(int k = hd[u];k;k=E[k].nxt){
            int v = E[k].to;
            if(dep[v] == dep[u]) return -1;
            if(!dep[v]) dep[v] = dep[u] + 1,Q.push(v);
        }
    }
    int mx = 0;
    for(int i=1;i<=n;i++) mx = max(mx, dep[i]);
    return mx;
}

int main()
{
    scanf("%d",&n);
    for(int i=1;i<=n;i++)
        for(int j=1;j<=n;j++){
            char c; cin>>c;
            if(c == '1') add(i,j),ind[j]++;
        }

    int mn = 0x3f3f3f3f;
    for(int i=1;i<=n;i++) mn = min(mn, ind[i]);
    for(int st=1;st<=n;st++) ans = max(ans, bfs(st));
    printf("%d",ans);

    return 0;
}

