using namespace std;
typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;
typedef vector<int> vi;
typedef vector<ll> vl;

vl divisor(ll n) {
	vl divlist;
	for (ll i = 1; i * i <= n; i++) {
		if (n % i == 0) {
			divlist.push_back(i);
			if (i * i != n)
				divlist.push_back(n / i);
		}
	}
	sort(divlist.begin(), divlist.end(), less<ll>());
	return divlist;
}

int main() {
	ll N;
	string X;
	cin >> N;
	cin >> X;
	ll ans = 0;
	vl divlist = divisor(N);
	map<ll, ll> sum_a, sum_a_strictly; // 周期がa以下の和, ちょうどaの和
	rep(i, divlist.size()) {
		// 小さい約数(周期a)から順に判定
		ll a = divlist[i]; // 周期
		ll b = N / a; // 周波数
		if (b % 2 == 0) // (n !n ... n !n)
			continue;

		// 上位a[bit] がX.substr(0, a)未満ならOK
		string Xsubstr = X.substr(0, a);
		reverse(Xsubstr.begin(), Xsubstr.end());
		ll pow2 = 1;
		rep(j, a) {
			sum_a[a] += ((Xsubstr[j] == '1') * pow2);
			sum_a[a] %= mod;
			pow2 *= 2;
			pow2 %= mod;
		}

		// 上位a[bit] がX.substr(0, a)と等しいときの判定
		Xsubstr = X.substr(0, a);
		string Xcomp;
		rep(f, b) {
			rep(j, a) {
				char Xtmp = Xsubstr[j];
				if (f % 2 == 1)
					Xtmp = ('1' - Xtmp + '0');
				Xcomp.push_back(Xtmp);
			}
		}
		sum_a[a] += (X >= Xcomp);

		// 周期が(ちょうどaの約数,a自身を除く)の場合を引く
		sum_a_strictly[a] = sum_a[a];
		vl divlist_a = divisor(a);
		rep(j, divlist_a.size()) {
			ll atmp = divlist_a[j]; // 周期
			ll btmp = N / atmp; // 周波数
			if (atmp == a)
				continue;
			if (btmp % 2 == 0) // (n !n ... n !n)
				continue;
			sum_a_strictly[a] -= sum_a_strictly[atmp];
			sum_a_strictly[a] += mod;
			sum_a_strictly[a] %= mod;
		}
		ans += sum_a_strictly[a] * 2 * a;
		ans %= mod;
	}
	cout << ans << endl;
	return 0;
}

