using namespace std;

typedef long long ll;
typedef pair<int,int> Pair;

const int Nmax = 5e5 + 5;
const int Mod = 998244353;

int n;
ll cnt[Nmax];
char A[Nmax];
ll pw[Nmax];

int color[Nmax], t[Nmax];
vector<int> changed, edge[Nmax];


void init()
{
    int i;
    for(i=1; i<=n; ++i) t[i] = i, edge[i].clear();
    for(i=1; i<=n; ++i) color[i] = -1;
}

void add_edge(int x, int y)
{
    edge[x].push_back(y); edge[y].push_back(x);
}

int boss(int x)
{
    if(x == t[x]) return x;
    return t[x] = boss(t[x]);
}

bool unite(int x, int y)
{
    x = boss(x); y = boss(y);
    if(x == y) return 0;
    t[x] = y;
    return 1;
}


void dfs(int node, int C = 0)
{
    changed.push_back(node);
    color[node] = C;

    for(auto it : edge[node])
        if(color[it] == -1)
            dfs(it, C ^ 1);
}

void solve(int d)
{
    int i;
    init();

    if(d == 2*n)
    {
        ll ans = 0;

        for(i=1; i<=n; ++i)
            if(A[i] == '1')
            {
                ans += pw[n-i];
                if(ans >= Mod) ans -= Mod;
            }

        ++ans;

        for(i=1; i < d; ++i)
            if(d % i == 0)
            {
                ans -= cnt[i];
                if(ans < 0) ans += Mod;
            }

        ans %= Mod;
        cnt[d] = ans;
        return;
    }





    for(i=1; i<=n-d; ++i)
        unite(i, i+d);

    for(i=1; i<=d; ++i)
        add_edge(boss(i), boss(n-d+i));

    int rest = 0;
    for(i=1; i<=n; ++i)
        if(i == boss(i) && color[i] == -1)
        {
            dfs(i);
            ++rest;
        }

    for(i=1; i<=n; ++i)
        for(auto it : edge[i])
            if(color[it] == color[i]) return; /// nu e bipartit

    for(i=1; i<=n; ++i) color[i] = -1;
    changed.clear();

    ll ans = 0;
    //OK = 1;

    bool state = 1;

    for(i=1; i<=n; ++i)
    {
        bool ok = (color[boss(i)] == -1);

        if(A[i] == '1')
        {
            if(ok) dfs(boss(i), 0);

            if(color[boss(i)] != 1)
                ans += pw[rest - ok];

            ans %= Mod;

            for(auto it : changed) color[it] = -1;
            changed.clear();
        }

        if(ok) dfs(boss(i), A[i] - '0');
            else state &= (color[boss(i)] == A[i] - '0');

        if(ok) --rest;
        changed.clear();

        if(!state) break;
    }

    if(state)
    {
        ans += pw[rest];
        ans %= Mod;
    }

    for(i=1; i < d; ++i)
        if(d % i == 0)
        {
            ans -= cnt[i];
            if(ans < 0) ans += Mod;
        }

    cnt[d] = ans;
}

int main()
{
 //   freopen("input", "r", stdin);
    // freopen("output", "w", stdout);
    cin.sync_with_stdio(false); cin.tie(0);

    cin >> n;
    cin >> (A+1);

    int i;
    ll ans = 0;

    pw[0] = 1;
    for(i=1; i<=2*n; ++i) pw[i] = pw[i-1] * 2 % Mod;

    for(i=1; i<=2*n; ++i)
        if((2*n) % i == 0)
        {
            solve(i);
            ans += (ll) cnt[i] * i;
            ans %= Mod;
        }

    cout << ans << '\n';

    return 0;
}

