struct edge_t {
  int to;
  int w;
};

mint pw2[200000 + 10];

mint solve(int N, const vector<int>& X, int L) {
  vec<edge_t, 2> G(N);
  for (int i = 0; i < N; i++) {
    int j = (i + L) % N;
    int w = ((i + L) / N) % 2;
    G[i].push_back({ j, w });
  }
  vector<int> id(N, -1), color(N, -1);
  vec<int, 2> group;
  for (int i = 0; i < N; i++) {
    if (id[i] != -1) continue;
    int v = i, c = 0, k = group.size();
    group.push_back({});
    while (id[v] == -1) {
      id[v] = k;
      color[v] = c;
      group[k].push_back(v);
      assert(G[v].size() == 1);
      int nv = G[v][0].to;
      int w = G[v][0].w;
      v = nv;
      c ^= w;
    }
    assert(v == i);
    if (c) return 0;
  }
  mint res = 0;
  int rem = group.size();
  vector<int> bit(N, -1);
  for (int i = N - 1; i >= 0; i--) {
    if (bit[i] != -1) {
      if (bit[i] > X[i]) {
        return res;
      }
      if (bit[i] < X[i]) {
        res += pw2[rem];
        return res;
      }
      continue;
    }
    int k = id[i];
    --rem;
    if (X[i] == 0) {
      for (int v : group[k]) bit[v] = (0 ^ color[i] ^ color[v]);
    } else {
      res += pw2[rem];
      for (int v : group[k]) bit[v] = (1 ^ color[i] ^ color[v]);
    }
  }
  res += 1;
  return res;
}

