bool isBig = 0;
int getCount (int P)
{
    int D = gcd (P, N); ///number of cycles
    if ((P / D) % 2 == 1) return 0;
    if (isBig) return p2[D];
    int ans = 0;
    for (int i=N - 1; i>=N - D; i--)
        if (bit[i])
            adto (ans, p2[D - (N - i)]);
    for (int i=N - 1; i>=N-D; i--)
    {
        v[i] = bit[i];
        for (int step = 1, j = i; step < N / D; step ++, j = (j + P) % N)
            v[(j + P) % N] = v[j] ^ (j + P >= N);
    }
    int i = N - 1;
    while (v[i] == bit[i] && i >= 0)
        i --;
    if (i >= 0 && bit[i] == 1)
        adto (ans, 1);
    return ans;
}

