constexpr lint MOD = 998244353;
void fast_integer_moebius(vector<lint> &f)
{
    int N = f.size() - 1;
    vector<int> is_prime(N + 1, 1);
    for (int p = 2; p <= N; p++) if (is_prime[p])
    {
        for (int q = p * 2; q <= N; q += p) is_prime[q] = 0;
        for (int j = p; j <= N; j += p) f[j / p] -= f[j];
    }
}

lint to_lint(const string &X)
{
    lint ret = 0;
    for (auto c : X)
    {
        ret = (ret * 2 + c - '0') % MOD;
    }
    return ret;
}
int main()
{
    int N;
    cin >> N;
    string X;
    cin >> X;
    lint ret = 0;
    vector<lint> dp(N + 1);
    FOR(n, 1, N + 1)
    {
        if (n % 2 == 0) continue;
        if (N % n != 0) continue;
        string T = X;
        int shuki = N / n;
        FOR(i, shuki, N)
        {
            if ((i / shuki) % 2) T[i] = (char)(('1' - T[i % shuki]) + '0');
            else T[i] = T[i % shuki];
        }
        bool bad = false;
        REP(i, N)
        {
            int ddd = (int)(T[i] - (char)(X[i]));
            if (ddd < 0) break;
            if (ddd > 0) bad = true;
        }
        dp[n] = to_lint(X.substr(0, shuki)) + 1 - bad;
    }
    fast_integer_moebius(dp);
    REP(i, N + 1) if (i % 2 and dp[i]) ret = (ret + dp[i] * (N / i) % MOD * 2) % MOD;
    cout << ret << endl;
}

