template <typename T>
vector<T> prime_facs(T N){
    vector<T> ans;
    for(int i = 2; i*i <= N; i++){
        if(N%i == 0){
            ans.push_back(i);
            while(N%i == 0){
                N /= i;
            }
        }
    }
    if(N != 1) ans.push_back(N);
    return ans;
