ll calc_dp(ll len) {
    dp[0][0] = 1;
    for(ll i = 0; i < X.size(); i++) {
        dp[i + 1][0] = dp[i + 1][1] = 0;
        if(i < len) {
            dp[i + 1][0] += dp[i][0];
            dp[i + 1][1] += 2 * dp[i][1] % mod;
            if(X[i] == '1') (dp[i + 1][1] += dp[i][0]) %= mod;
        } else {
            dp[i + 1][1] += dp[i][1];
            ll idx = i / len;
            bool one = X[i % len] == '1';
            if(idx & 1) one = !one;
            if(one && X[i] == '0') {
                dp[i + 1][0] = 0;
            } else if(!one && X[i] == '1') {
                dp[i + 1][1] += dp[i][0];
                dp[i][0] = 0;
            } else {
                dp[i + 1][0] += dp[i][0];
            }
        }

        dp[i + 1][0] %= mod;
        dp[i + 1][1] %= mod;
    }
    return (dp[X.size()][0] + dp[X.size()][1]) % mod;
}

