using namespace std;
using int64 = long long;

constexpr int DEBUG = 0;

constexpr int64 P = 998244353;

struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalied FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

FiniteField ParseBinary(string s) {
  FiniteField x = 0;
  for (int d = 0; d < s.size(); d++) {
    x *= 2;
    if (s[d] == '1') x += 1;
  }
  return x;
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n;
  string s;
  cin >> n >> s;

  FiniteField x = ParseBinary(s);
  if (DEBUG) cout << "x: " << x.Value() << endl;
  FiniteField sum = (x + 1) * 2 * n;
  vector<FiniteField> as(n + 1);
  for (int l = 1; l <= n; l++) {
    if (n % l == 0) {
      int d = n / l;
      if (d % 2 == 0) continue;
      if (d == 1) continue;
      if (DEBUG) cout << "l: " << l << endl;
      string t = s.substr(0, l);
      FiniteField y = ParseBinary(t);
      FiniteField count = y;
      string tr = t;
      for (int i = 0; i < tr.size(); i++) {
        if (tr[i] == '1') tr[i] = '0';
        else tr[i] = '1';
      }
      string u = "";
      for (int i = 0; i < d; i++) {
        if (i % 2 == 0) u.append(t);
        else u.append(tr);
      }
      if (DEBUG) cout << "u: " << u << endl;
      if (u <= s) {
        count += 1;
      }
      if (DEBUG) cout << "count before ajudst: " << count.Value() << endl;
      count -= as[l];
      if (DEBUG) cout << "count: " << count.Value() << endl;
      FiniteField cycle = 2 * l;
      sum -= count * (FiniteField(2 * n) - cycle);
      for (int k = 2; l * k <= n; k++) {
        as[l * k] += count;
      }
    }
  }
  cout << sum.Value() << endl;
}

