vi divisors(int v) {
    vi res;
    double lim = std::sqrt(v);
    for (int i = 1; i <= lim; ++i) { if (v % i == 0) { res.push_back(i);/*                if (i != v / i)res.push_back(v / i);*/            }}
    rer(i, sz(res) - 1) { if (res[i] != v / res[i])res.push_back(v / res[i]); }
    return res;
}
signed main() {
    int N;
    string X;
    cin >> N >> X;
    vi K;
    {
        auto D = divisors(N * 2);
        for (auto &&k: D) {
            if ((k % 2) == 0)K.push_back(k);//kは偶数でN*2の約数
        }
    }
    int lim = N * 2 + 1;
    vector<mint> cou(lim);//周期が[k]となるような物の数
    mint res = 0;

    bitset<bsetlen> bx(X);
    for (auto &&k:K) {
        mint part = 0;
        //先頭k/2桁を決めれば後は一意に定まる
        //先頭k/2桁の自明に小さい取り方を数える
        rep(i, k / 2) {
            if (X[i] == '1')part += mpow(2, k / 2 - 1 - i);
        }
        {
            string def = X.substr(0, k / 2);
            string abc = ~def;//mainの上

            string tx = def;
            string af = abc + def;
            //size
            while (sz(tx) < N) tx += af;
            if (sz(tx) != N)continue; //予防だが使われない txのサイズは必ずN
            bitset<bsetlen> btx(tx);
            if (bx >= btx) part += 1;
        }
        cou[k] += part;
        res += cou[k] * k;
        for (int s = k * 2; s < lim; s += k) {
            cou[s] -= cou[k];//周期kはkの倍数sでも数えられるため引いておく
        }
    }
    cout << res << endl;
    return 0;
}

