using i64 = long long;

int main() {
    constexpr i64 mod = 998244353;
    int n;
    std::string s;
    std::cin >> n >> s;

    i64 c = 0, ret = 0;
    std::vector<std::pair<int, i64>> memo;
    for (int i = 0; i < n; i++) {
        c = (c * 2 + (s[i] == '1')) % mod;

        int d = i + 1;
        if (n % d || (n / d) % 2 == 0) continue;

        i64 overlap = 0;
        for (auto &e : memo) if (d % e.first == 0 && (d / e.first) % 2) {
            overlap = (overlap + e.second) % mod;
        }

        int flg = 1;
        for (int i = 0; i < n; i++) {
            if (i / d % 2) {
                if (s[i] == '0' && s[i % d] == '0') {
                    flg = 0;
                    break;
                } else if (s[i] == '1' && s[i % d] == '1') break;
            } else {
                if (s[i] == '0' && s[i % d] == '1') {
                    flg = 0;
                    break;
                } else if (s[i] == '1' && s[i % d] == '0') break;
            }
        }

        i64 count = (c + flg + mod - overlap) % mod;
        memo.emplace_back(d, count);
        ret = (ret + count * d % mod * 2 % mod) % mod;
    }

    std::cout << ret << std::endl;

    return 0;
}

