	for(k=1;k<=n/3;++k)if(!(n%k)&&n/k%2==1){
		res[k]=tmp[k];
		for(i=1;i<=k;++i)a[i]=b[i];
		for(;i<=n;i+=k)
			for(j=0;j<k;++j)a[i+j]=a[i+j-k]^1;
		if(cmp())res[k]=(res[k]+1)%mod;
		if(k>1)for(i=1;i*i<=k;++i)if(!(k%i))res[k]=(res[k]-res[i]+mod)%mod;
		ans=(ans-(ll)res[k]*(n-k<<1)%mod+mod)%mod;
	}
	printf("%d\n",ans);
	return 0;
}

