namespace Sieve
{
    int p[N], c;
    bool u[N];
    int f[N];

    void Sieve(void)
    {
        int i, j;

        f[1] = 1;
        for(i = 2; i < N; i ++)
        {
            if(!u[i])
            {
                p[c ++] = i;
                f[i] = -1;
            }
            for(j = 0; j < c && i * p[j] < N; j ++)
            {
                u[i * p[j]] = true;
                if(!(i % p[j]))
                    break;
                f[i * p[j]] = -f[i];
            }
        }

        // for(i=1;i<10;i++)cout<<f[i]<<' ';cout<<endl;

        return;
    }
}

