int check(int x)
{
	if(n % x == 0) return 0;

	int ret = 0;
	rep(i, x / 2) {
		ret = 2LL * ret % MOD; 
		if(ch[i] == '1') ret = (ret + 1) % MOD;
	}

	rep(i, x) ns[i] = ch[i % (x / 2)] ^ (i / (x / 2));
	rep(i, n) ns[i] = ns[i % x];

	rep(i, n) if(ns[i] > ch[i]) return ret;
	else if(ns[i] < ch[i]) return (ret + 1) % MOD;
	return (ret + 1) % MOD;
}

