ll modnum(string S) {
	ll cur = 1;
	ll ret = 0;
	reverse(all(S));
	for (int i = 0; i < S.size(); i++) {
		if (S[i] - '0' == 1)ret += cur;
		cur *= 2;
		cur %= mod;
	}
	return ret;
}

ll count(int d) {
