	for (int i = 0; i < N/d; i++)Xtemp += X[i];
	ll ret = modnum(Xtemp);
	string Xcomp;
	for (int i = 0; i < N; i++) {
		if ((i / d) % 2 == 0) {
			if (X[i%d] == '0')Xcomp += '0';
			else Xcomp += '1';
		}
		else {
			if (X[i%d] == '1')Xcomp += '0';
			else Xcomp += '1';
		}
	}

	int ok = 1;
	for (int i = 0; i < N; i++) {
		if (X[i] == '0' && Xcomp[i] == '1') {
			ok = 0;
			break;
