mint solve(int k) {
	mint res = imos[k];
	bool flag = true;
	for (int i = 0; i < k; ++i) {
		if (X[i + k] > Y[i]) {
			break;
		}
		else if (X[i + k] < Y[i]) {
			flag = false;
			break;
		}
	}
	if (flag)res++;
	return res;
}

int main() {
	cin >> N >> X;
	Y.resize(N);
	for (int i = 0; i < N; ++i) {
		imos[i + 1] = imos[i] + imos[i];
		if (X[i] == '1') {
			imos[i + 1]++;
			Y[i] = '0';
		}
		else {
			Y[i] = '1';
		}
	}
	two[0] = 1;
	for (int i = 0; i <= N; ++i) {
		two[i + 1] = two[i] + two[i];
	}
	vector<int>yak;
	for (int i = 1; i <= N; ++i) {
		if (N % i == 0) {
			yak.push_back(i);
		}
	}
	map<int, mint>dp;
	map<int, vector<int>>to;
	for (int elm : yak) {
		int pack = N / elm;
		if (pack % 2 == 0) {
			continue;
		}
		for (int i = pack + pack; i <= N; i += pack) {
			if (N % i == 0)
				to[i].push_back(pack);
		}
	}
	for (int elm : yak) {
		int pack = N / elm;
		if (pack % 2 == 0) {
			continue;
		}
		if (elm != N)
			dp[pack] = solve(elm);
		else
			dp[pack] = imos[elm] + mint(1);
	}
	//reverse(yak.begin(), yak.end());
	mint ans = 0;
	for (int x : yak) {
		int pack = N / x;
		if (pack % 2 == 0) {
			continue;
		}
		//ans += dp[pack];
		for (int t : to[pack]) {
			dp[t] -= dp[pack];
		}
	}
	for (auto p : dp) {
		ans += p.second * mint(N / p.first) * mint(2);
	}
	cout << ans << endl;
	return 0;
}

