void getMin(string& s, const string& t, int st, int len) {
    for (int i = 0; i < len; ++i) {
        if (s[i] < t[st + i]) {
            return;
        }
        if (s[i] > t[st + i]) {
            s = string(t.begin() + st, t.begin() + st + len);
            return;
        }
    }
}

ll getAdd(const string& s) {
    ll res = 0;
    for (int i = 0; i < s.size(); ++i) {
        res = (res * 2 + s[i] - '0') % mod;
    }
    return res + 1;
}

void solve() {
    int n;
    cin >> n;
    string x;

    cin >> x;
    string xx(x);
    for (int i = 0; i < n; ++i) {
        if (x[i] == '1')
            xx[i] = '0';
        else 
            xx[i] = '1';
    }
    xx = x + xx;
    ll res = 0;
    vector<ll> add(2 * n + 1, 0);
    for (int d1 = 1; d1 <= n; ++d1) {
        if (n % d1 != 0)
            continue;
        ll d = 2 * d1;
        int m = n / d1;
        if (m % 2 == 0)
            continue;
        string s(x.begin(), x.begin() + d1);
        s.reserve(n);
        /*for (int i = 2; i < m; i += 2) {
            getMin(s, x, i * d1, d1);
        }*/
        ll a = getAdd(s);
        if (d1 != n) {
            string ss;
            ss.resize(d);
            for (int i = 0; i < d1; ++i) {
                if (s[i] == '0')
                    ss[i] = '1';
                else {
                    ss[i] = '0';
                }
            }
            s.resize(n);
            for (int i = 0; i < m / 2; ++i) {
                for (int j = 0; j < d1; ++j) {
                    s[i * 2 * d1 + d1 + j] = ss[j];
                }
                for (int j = 0; j < d1; ++j) {
                    s[i * 2 * d1 + 2 * d1 + j] = s[j];
                }
            }
            if (s > x)
                --a;
        }
        //cerr << a << endl;
        add[d] = (((add[d] + a) % mod) + mod) % mod;
        //cout << d << " "  << add[d] << endl;
        for (int j = 2 * d; j <= 2 * n; j += d) {
            add[j] -= add[d];
        }
        res = (res + add[d] * d) % mod;
    }
    cout << res << endl;

}


