            g[j][0] = g[j][1] = 0;
            for (int t = 0; t < 2; t++) {
                (g[j][1] += g[j - 1][1]) %= P;
                char c = t + '0';
                if (c <= s[j]) (g[j][c < s[j]] += g[j - 1][0]) %= P;
            }
        }
        bool flag = 1;
        for (int j = i + 1; j <= n; j++) {
            char c = s[j % i == 0 ? i : j % i];
