        if (flag) (f[i] += g[i][0]) %= P;
        for (int j = 1; j * j <= i; j++) {
            if (j < i) f[i] = (f[i] - f[j] + P) % P;
            if (j > 1 && j * j < i) f[i] = (f[i] - f[i / j] + P) % P;
