const int N = 2e5 + 5, djq = 998244353;

int n, tot, p[N], p2[N], f[N], ans;
char s[N];

char inv(char c) {return c == '0' ? '1' : '0';}

char conv(int d, int i) {return i / d & 1 ? inv(s[i % d]) : s[i % d];}

int calc(int d)
{
	int res = 0;
	for (int i = 0; i < d; i++) if (s[i] == '1')
		res = (res + p2[d - i - 1]) % djq;
	for (int i = 0; i < n; i++)
		if (conv(d, i) < s[i]) return (res + 1) % djq;
		else if (conv(d, i) > s[i]) return res;
	return (res + 1) % djq;
}

int main()
{
	scanf("%d%s", &n, s);
	int S = sqrt(n); p2[0] = 1;
	for (int i = 1; i <= n; i++) p2[i] = (p2[i - 1] << 1) % djq;
	for (int i = 1; i <= S; i++)
	{
		if (n % i) continue; p[++tot] = i;
		if (i < n / i) p[++tot] = n / i;
	}
	std::sort(p + 1, p + tot + 1);
	for (int i = 1; i <= tot; i++)
	{
		int x = p[i]; if (!(n / x & 1)) continue;
		f[x] = calc(x);
		for (int j = 1; j < i; j++)
			if (x % p[j] == 0) f[x] = (f[x] - f[p[j]] + djq) % djq;
		ans = (2ll * x * f[x] + ans) % djq;
	}
	return std::cout << ans << std::endl, 0;
}

