        (a*=R(b.a))%=mod;
        return *this;
    }

    M operator / (const M &b) const {
        M c=*this;
        return c/=b;
    }

    M & mod_pow_equal(ll x){
        ll ans=1;
        while(x>0){
            if(x&1){ans*=a; ans%=mod;}
            a*=a;
            a%=mod;
            x>>=1;
