template <typename S>
vector<int> Z_Algorithm(const S &s) {
    //先頭i文字目(0-indexed)から見て一致した文字数
    vector<int> prefix(s.size());

    prefix[0] = s.size();
    int i = 1, j = 0;
    while (i < s.size()) {
        while (i+j < s.size() && (s[j] == s[i+j])) ++j;
        prefix[i] = j;
        if (j == 0) { ++i; continue;}
        int k = 1;
        while (i+k < s.size() && k+prefix[k] < j) prefix[i+k] = prefix[k], ++k;
        i += k; j -= k;
    }

    return prefix;
}

