        ll skiyabit=0;

        rep(j,now){
            skiyabit*=2;
            skiyabit+= (S[j]=='1');
            skiyabit%=MOD;
        }

        vector<int> div2=divisors(now);

        rep(j,div2.size()){
            skiyabit-=dp[div2[j]];
        }

        rep(j,S.size()){
            int x=(S[j%now]=='1' xor !((j/now)%2==0) );

            int kazu= (S[j]=='1');
            if(kazu>x){
                ++skiyabit;
                break;
            }
            if(kazu<x){
                break;
            }
            if(j==S.size()-1){
                ++skiyabit;
                break;
            }
        }

        dp[now]=skiyabit;

        ct+=skiyabit;

        ct2+=skiyabit*now;
        ct2%=MOD;
    }

    ll ans=0;

    rep(i,N){
        ans*=2;
        ans+= (S[i]=='1');
        ans%=MOD;
    }

    ans+=1;

    ans=(ans-ct%MOD+MOD)%MOD;

    ans=ans*2*N%MOD;

    ans=(ans+ct2*2)%MOD;

    cout<< ans<<"\n";


