}

vector<int> divisor(int n){
  vector<int> v;
  for(int i=1; i<=sqrt(n); i++){
    if(n%i == 0){
      v.push_back(i);
      if(i!=n/i)v.push_back(n/i);
    }
  }
  sort(all(v),greater<int>());
  return v;
}

//素因数分解O(root n)
vector<PII> prime_factor(int n){
  vector<PII> v;
  for(int i=2; i<=sqrt(n); i++){
    int num=0;
    while(n%i==0){
      num++;
      n/=i;
    }
    if(num!=0) v.push_back(PII(i,num));
  }
  if(n!=1) v.push_back(PII(n,1));
  return v;
}

