        char a;
        cin >> a;
        if (a == '1') x[N - i - 1] = true;
        else if (a == '\n') --i;

    }

    llm result = 1;

    for0(i, N){
        if (x[i]) {
            llm a = llm(2).pow(i);
            result += a;
        }
    }

    int dec = 0;
    int add = 0;

    for1n(i, N / 3){
        int inc = 0;

        if ((N - i) % (2 * i) == 0) {
            deque<bool> y(N, false);

            for0(j, N){
                if ((j / i) % 2 == 0) y[j] = true;
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }

            for0(j, N){
                y[j] = !y[j];
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }
        }
        add += 2 * i * inc;
    }

    for1n(i, N / 6){
        int inc = 0;
        if (((N - 2 * i) % 4 * i) == 0){
            bool now = true;

            deque<bool> y(N, false);
            for0(j, N){
                if (now) {
                    if(j % (2 * i) <= 1){
                        y[j] = 1;
                    } else {
                        y[j] = 0;
                    }
                } else {
                    if(j % (2 * i) <= 1){
                        y[j] = 0;
                    } else {
                        y[j] = 1;
                    }
                }
                if (j % (2 * i) == 2 * i - 1) now = !now;
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }

            for0(j, N){
                y[j] = !y[j];
            }

            if (!g(x, y, N)) {
                --dec;
                ++inc;
            }
        }
        add += 4 * i * inc;
    }

    result += dec;

    result *= 2 * N;

    result += add;

    cout << result;

    return 0;
}

