std::vector<int64_t> divisor(int64_t n) {
    // nの約数をソートして列挙。1とnも含む。計算量はO(sqrt(n))なので、int64_tも入り得る。
    std::vector<int64_t> res;
    for (int64_t i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            res.push_back(i);
            if (i != n / i) {
                res.push_back(n / i);
            }
        }
    }
    std::sort(res.begin(), res.end());
    return res;
}


