void add_mod( int &a, int b ) {
	a += b;
	a -= a >= MOD ? MOD : 0;
}

void sub_mod( int &a, int b ) {
	a -= b;
	a += a < 0 ? MOD : 0;
}

int mu[N];

int calc_mu( int x ) {
	int ans = 1;
	for( int i = 2; i*i <= x; ++i )
		if( x % i == 0 ) {
			x /= i;
			ans = -ans;
			if( x % i == 0 ) return 0;
		}
	if( x != 1 ) ans = -ans;
	return ans;
}

void init_mu() {
	for( int i = 1; i < N; ++i )
		mu[i] = calc_mu(i);
}

int n, a[N];
