vector<int> fac;

void factor( int x ) {
	for( int i = 1; i <= x; i += 2 )
		if( x % i == 0 )
			fac.push_back(x/i);
	sort(fac.begin(), fac.end());
}

int get_num( int len ) {
	int x = 0;
	for( int i = 1; i <= len; ++i ) {
		x = (x * 2 + a[i]) % MOD;
	}
	return x;
}

int chk[N];

int check( int len ) {
	for( int i = 1; i <= len; ++i ) {
		chk[i] = a[i];
		for( int j = len+i; j <= n; j += len )
			chk[j] = 1 - chk[j-len];
	}
	for( int i = 1; i <= n; ++i ) {
		if( chk[i] < a[i] )
			return 1;
		else if( chk[i] > a[i] )
			return 0;
	}
	return 1;
}

int calc( int len ) {
	int rtn = get_num(len);
	add_mod(rtn, check(len));
	return rtn;
}

