	for( int len : fac ) {
		int tmp = calc(len);
		// printf( "calc(%d) = %d\n", len, tmp );
		add_mod( ans[len], tmp );
		for( int j = len+len; j <= n; j += len ) {
			if( mu[j/len] == 1 ) {
				add_mod( ans[j], tmp );
			} else if( mu[j/len] == -1 ) {
				sub_mod( ans[j], tmp );
			}
		}
	}
	int tot = 0;
	for( int i : fac ) {
		add_mod( tot, int(1LL * ans[i] * i * 2 % MOD) );
		// printf( "ans[%d] = %d\n", i, ans[i] );
	}
	cout << tot << endl;
}

