    static class TaskC {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            char[] x = in.readCharArray(n);
            long[] qty = new long[n + 1];
            char[] current = new char[n];
            long[] pow = IntegerUtils.generatePowers(2, n + 1, MiscUtils.MODF);
/*        long xx = 0;
