vector<LL> divi(LL K){
    vector<LL> v;
    for(int i=1;i*i<=K;i++){
        if(K%i) continue;
        v.pb(i);
        v.pb(K/i);
    }
    sort(ALL(v));
    v.erase(unique(ALL(v)),v.end());
    return v;
}


int main(){
    int n;
    cin >> n;
    string s;
    cin >> s;
    vector<vector<LL>> dp(n+1,vector<LL> (2,0));
    dp[0][1] = 1;
    for (int i = 0; i < n; i++) {
        for (int f = 0; f < 2; f++) {
            if(f){
                int x = s[i] - '0';
                for (int j = 0; j <= x; j++) {
                    if(j==x) dp[i+1][1] = (dp[i+1][1] + dp[i][1])%mod;
                    else dp[i+1][0] = (dp[i+1][0] + dp[i][1])%mod;
                }
            }
            else{
                dp[i+1][0] = (dp[i+1][0] + 2 * dp[i][0])%mod;
            }
        }
    }
    LL ans = (dp[n][0] + dp[n][1]) * n % mod * 2 % mod;
    auto p = divi(n);
    reverse(ALL(p));
    vector<LL> dp2(n+1,0);
    for(auto a:p){
        LL x = n / a;
        if(n % 2 == 0){
            if(x % 2) continue;
            if(x % 2 || n / x % 2 == 0) continue;
        }
        string t = "";
        for (int j = 0; j < n; j++) {
            if(j / x % 2){
                t += '0' + (s[j % x] ^ '1');
            }
            else{
                t += s[j % x];
            }
        }
        if(t <= s){
            dp2[x] = (dp[x][0] + dp[x][1])%mod;
        }
        else{
            dp2[x] = dp[x][0];
        }
        for(auto b:p){
            LL y = n / b;
            if(x % y == 0 && x != y) dp2[x] = (dp2[x] - dp2[y] + mod) %mod;
        }
        ans = (ans - ((2 * (n - x + mod)%mod) * dp2[x] %mod) + mod)%mod;
    }
    cout << ans << endl;
    return 0;
}

