			a[i] = 0;
			forn(j,i){
				a[i] = (a[i] << 1);
				if(s[j]=='1') a[i]++;
				if(a[i] >= MOD) a[i] %= MOD;
			}
			if(check(i)){
				a[i]++;
				if(a[i] >= MOD) a[i] = 0;
			}
		}
		else{
