void Minus(vector<int> &x) {
	int i;

	x[0]--;
	if (x[0] < 0) {
		i = 1;
		while (true) {
			x[i - 1] += 2;
			x[i]--;
			if (x[i] >= 0) break;
			i++;
		}
	}
}

bool check(vector<int> &x, int d) {
	vector<int> y(n, 0);
	int i, j;

	//cout << "d = " << d << ", x = ";
	//for (i = x.size() - 1; i >= 0; i--) cout << x[i];
	//cout << endl;

	int shift = 0;
	for (i = 0; i < n / d; i++) {
		if (i % 2 == 0) {
			for (j = 0; j < d; j++) {
				y[shift] += x[j];
				shift++;
			}
		}
		else {
			for (j = 0; j < d; j++) {
				y[shift] += (!x[j]);
				shift++;
			}
		}
	}

	//cout << "y = ";
	//for (i = n - 1; i >= 0; i--) cout << y[i];
	//cout << endl;

	for (i = n - 1; i >= 0; i--) {
		int p = s[n - 1 - i] - '0';
		int q = y[i];
		if (q != p) {
			if (q > p) return false;
			return true;
		}
	}
	return true;
}

int calc(int d) {

	//まずは、2^((n/d)-1) * x <= int(s)なる最大のxを探す
	int i;
	vector<int> x;	//…x2x1x0 (10進数)
	x.resize(d);
	//cout<< "x.size() = " << x.size() << endl;

	int xval = 0;
	for (i = 0; i < d; i++) {
		int val = s[d - 1 - i] - '0';
		x[i] = val;
		xval *= 10;
		xval += x[i];
		if (xval >= 100) xval = 100;
	}

	//x, x-1, x-2, x-3…あたりを試すと条件を満たす最大のxが分かる
	while (true) {
		if (check(x, d)) break;
		xval--;
		if (xval <= -1) break;
		Minus(x);
	}
	if (xval <= -1) return 0;

	int ret = 0;
	int mul = 1;
	for (i = 0; i < x.size(); i++) {
		ret += x[i] * mul;
		ret %= mod;
		mul *= 2;
		mul %= mod;
	}
	ret++;
	ret %= mod;
	return ret;
}

signed main() {
	int i, j, k;

	cin >> n >> s;

	static int memo[200001];
	for (i = 1; i <= n; i++) {
		if (n % i != 0) continue;
		if ((n / i) % 2 == 0) continue;
		memo[i] = calc(i);
		//cout << "memo[" << i << "] = " << memo[i] << endl;
	}

	//約数包除？冷静に考えると包除さえいらない.
	//f(x) = 最小周期xの文字列の個数
	//g(x) = 周期xの文字列の個数
	//とおくとg(x) = sum(d, f(d), where x % d == 0)
	//g(x)からf(x)を求めたい。とりあえず、
	//f(x) = g(x) - sum(d, f(d), where x % d == 0 and d < x)
	//となるが、d < xよりf(0)から順番に求めていけば、これは普通に計算できる。
	//fをgだけで表そうとするとヤバいが、漸化式を使えば簡単という.. (個人的にここが一番山場です）
	static int cnt[200001];	//cnt[x] = f(x). n / xが奇数でないxについてはドントケア(0とは限らない).
	for (i = 1; i <= n; i++) { cnt[i] = memo[i]; }
	for (i = 1; i <= n; i++) {
		for (j = i * 2; j <= n; j += i) {
			cnt[j] -= cnt[i];
			if (cnt[j] < 0) cnt[j] += mod;
		}
	}

	int ans = 0;
	for (i = 1; i <= n; i++) {
		if (n % i != 0 || (n / i) % 2 == 0) continue;
		ans += 2 * i * cnt[i] % mod;
		ans %= mod;
		//cout << "cnt[" << i << "] = " << cnt[i] << endl;
	}
	cout << ans << endl;
	return 0;
}

