template <int mod = (int)(998244353)>
struct ModInt {
  int x;
  constexpr ModInt() : x(0) {}
  constexpr ModInt(int64_t y)
      : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}
  constexpr ModInt &operator+=(const ModInt &p) noexcept {
    if ((x += p.x) >= mod) x -= mod;
    return *this;
  }
  constexpr ModInt &operator-=(const ModInt &p) noexcept {
    if ((x += mod - p.x) >= mod) x -= mod;
    return *this;
  }
  constexpr ModInt &operator*=(const ModInt &p) noexcept {
    x = (int)(1LL * x * p.x % mod);
    return *this;
  }
  constexpr ModInt &operator/=(const ModInt &p) noexcept {
    *this *= p.inverse();
    return *this;
  }
  constexpr ModInt operator-() const { return ModInt(-x); }
  constexpr ModInt operator+(const ModInt &p) const noexcept {
    return ModInt(*this) += p;
  }
  constexpr ModInt operator-(const ModInt &p) const noexcept {
    return ModInt(*this) -= p;
  }
  constexpr ModInt operator*(const ModInt &p) const noexcept {
    return ModInt(*this) *= p;
  }
  constexpr ModInt operator/(const ModInt &p) const noexcept {
    return ModInt(*this) /= p;
  }
  constexpr bool operator==(const ModInt &p) const noexcept { return x == p.x; }
  constexpr bool operator!=(const ModInt &p) const noexcept { return x != p.x; }
  constexpr ModInt inverse() const noexcept {
    int a = x, b = mod, u = 1, v = 0, t = 0;
    while (b > 0) {
      t = a / b;
      swap(a -= t * b, b);
      swap(u -= t * v, v);
    }
    return ModInt(u);
  }
  constexpr ModInt pow(int64_t n) const {
    ModInt res(1), mul(x);
    while (n) {
      if (n & 1) res *= mul;
      mul *= mul;
      n >>= 1;
    }
    return res;
  }
  friend constexpr ostream &operator<<(ostream &os, const ModInt &p) noexcept {
    return os << p.x;
  }
  friend constexpr istream &operator>>(istream &is, ModInt &a) noexcept {
    int64_t t = 0;
    is >> t;
    a = ModInt<mod>(t);
    return (is);
  }
  constexpr int get_mod() { return mod; }
};

int n;
string x;
vector<int> v;
vector<ModInt<>> cnt;
vector<vector<ModInt<>>> dp;

ModInt<> solve();

int main() {
  cin >> n >> x;
  cout << solve() << endl;
  return 0;
}

ModInt<> solve() {
  ModInt<> res;
  dp.assign(n + 1, vector<ModInt<>>(2, 0));
  dp[0][0] = 1;
  for (int i = 0; i < n; ++i) {
    dp[i + 1][1] += dp[i][1] * 2;
    if (x[i] - '0') dp[i + 1][0] += dp[i][0];
    dp[i + 1][x[i] - '0'] += dp[i][0];
  }
  res = (dp[n][0] + dp[n][1]) * 2 * n;
  // search divisor
  {
    for (int i = 1; i * i <= n; ++i)
      if (n % i == 0) {
        if ((n / i) & 1) v.push_back(i);
        if (i * i != n && (i & 1) && i != 1) v.push_back(n / i);
      }
    sort(v.begin(), v.end());
  }
  cnt.assign(n + 1, 0);
  for (auto p : v) {
    cnt[p] += dp[p][1];
    {
      int cycle = n / p;
      string now;
      for (int i = 0; i < cycle; ++i)
        for (int j = 0; j < p; ++j) now += '0' + ((x[j] - '0') ^ (i & 1));
      if (now <= x) cnt[p] += 1;
    }
    res -= cnt[p] * 2 * (n - p);
    for (int i = 2; i * p <= n; ++i) cnt[i * p] -= cnt[p];
  }
  return res;
}

