void solve(istream &cin = std::cin, ostream &cout = std::cout)
{
    int n;

    auto solve_test = [&] () {
        string x;
        cin >> x;
        assert(int(x.size()) == n);

        vector<int> mu(n + 1, +1);
        for (int i = 2; i * i <= n; i++) {
            for (int j = i * i; j <= n; j += i * i)
                mu[j] = 0;
        }

        vector<char> isprime(n + 1, 1);
        for (int i = 2; i <= n; i++) {
            if (isprime[i]) {
                for (int j = i; j <= n; j += i)
                {
                    mu[j] *= -1;
                    if (j > i)
                        isprime[j] = 0;
                }
            }
        }

        int two = 1;
        while (n % (2 * two) == 0)
            two *= 2;

        int total = 0;

        vector<vector<int>> divs(n + 1);
        for (int i = 1; i <= n; i++) {
            for (int j = 2 * i; j <= n; j++)
                divs[j].push_back(i);
        }

        auto with_blocks = [&](int l) {
            assert(n % l == 0 && (n / l) % 2 == 1);

            int ans = 0;
            for (int i = 0; i < l; i++)
                ans = mult(ans, 2), add(ans, x[i] - '0');

            bool ok = true;
            for (int i = 0; i < n; i++) {
                const char cur = ((i / l) % 2 == 0 ? x[i % l] : x[i % l] ^ '0' ^ '1');
                if (cur < x[i])
                    break;
                if (cur > x[i]) {
                    ok = false;
                    break;
                }
            }

            if (ok)
                add(ans, 1);
            return ans;
        };

        vector<int> f(n / two + 1);
        for (int i = 1; i <= n / two; i += 2) {
            if (n % i != 0)
                continue;

            f[i] = with_blocks(two * i);
            for (int j : divs[i]) {
                if (mu[i / j] == +1)
                    add(f[i], f[j]);
                else
                    sub(f[i], f[j]);
            }
        }

        int ans = 0;
        for (int i = 1; i <= n / two; i++)
        {
            add(ans, mult(i == n / two ? 2 * n : 2 * two * i, f[i]));
        }
        return ans;
    };

    while (cin >> n)
    {
        auto res = solve_test();
        cout << res << endl;
//        break;
    }
}

