inline long long imod(long long a, long long b)
{
	return (a >= 0) ? (a % b) : (a % b + b);
}

//mintが引数の繰り返し2乗法
class mint;
mint pow(mint x, long long n);

//modの整数クラス
class mint
{
public:
	static void set_mod(long long m_)
	{
		//無効な値は無視
		if (m_ < 2)return;
		//modの値を更新
		mod = m_;
		//オイラー関数Φ(mod)を計算する
		e_phi = m_;
		for (int i = 2; i * i <= m_; ++i)
		{
			if (m_ % i == 0)
			{
				e_phi = e_phi / i * (i - 1);
				for (; m_ % i == 0; m_ /= i);
			}
		}
		if (m_ != 1)e_phi = e_phi / m_ * (m_ - 1);
	}
	mint operator+(const mint& other)const
	{
		return mint(a + other.a >= mod ? a + other.a - mod : a + other.a, true);
	}
	mint operator-(const mint& other)const
	{
		return mint(a - other.a < 0 ? a - other.a + mod : a - other.a, true);
	}
	mint operator*(const mint& other)const
	{
		return mint(imod(a * other.a, mod));
	}
	mint operator+=(const mint& other)
	{
		a = a + other.a >= mod ? a + other.a - mod : a + other.a;
		return mint(a, true);
	}
	mint operator-=(const mint& other)
	{
		a = a - other.a < 0 ? a - other.a + mod : a - other.a;
		return mint(a, true);
	}
	mint operator*=(const mint& other)
	{
		a = imod(a * other.a, mod);
		return mint(a);
	}
	mint operator+()const
	{
		return *this;
	}
	mint operator-()const
	{
		return mint(mod - a >= mod ? -a : mod - a, true);
	}
	mint& operator++()
	{
		*this += 1;
		return *this;
	}
	mint operator++(int)
	{
		auto tmp = *this;
		*this += 1;
		return tmp;
	}
	mint& operator--()
	{
		*this -= 1;
		return *this;
	}
	mint operator--(int)
	{
		auto tmp = *this;
		*this -= 1;
		return tmp;
	}
	mint operator~()const
	{
		return pow(*this, e_phi - 1);
	}
	mint& operator=(const mint& other)
	{
		a = other.a;
		return *this;
	}
	operator long long()const
	{
		return a;
	}
	explicit operator int()const
	{
		return (int)a;
	}
	static long long getmod()
	{
		return mod;
	}
	mint(long long a_) :a(imod(a_, mod)) {}
	mint() :a(0) {}
private:
	static long long mod;
	static long long e_phi;
	long long a;
	mint(long long a_, bool) : a(a_) {}
};

//mintの累乗
//x^nを計算します
mint pow(mint x, long long n)
{
	mint res = 1;
	while (n > 0)
	{
		if (n & 1)res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

