using Poly = vector<mint>;

Poly operator*(const Poly& p1, const Poly& p2) {
	Poly res(p1.size() + p2.size() - 1);
	for (int j = 0; j < p2.size(); ++j) {
		for (int i = 0; i < p1.size(); ++i) {
			res[i + j] += p1[i] * p2[j];
		}
	}
	return res;
}

Poly operator/(const Poly& p1, const Poly& p2) {
	Poly p3 = p1;
	Poly res(p1.size() + 1 - p2.size());
	for (int i = res.size() - 1; i >= 0; --i) {
		res[i] = p3[p2.size() - 1 + i] * minv[p2[p2.size() - 1]];
		for (int j = i; j < i + p2.size(); ++j) {
			p3[j] -= res[i] * p2[j - i];
		}
	}
	return res;
}

mint calc(const Poly& pol, mint x) {
	mint ans = 0;
	mint tak = 1;
	for (int i = 0; i < pol.size(); ++i) {
		ans += tak * pol[i];
		tak *= x;
	}
	return ans;
}

