mint opt[234567];
mint shsh[234567];
mint hshs[234567];

mint solve(int k) {
	mint res = imos[k];
	bool flag = true;
	for (int g = 1; g < N / k; ++g) {
		LL now = shsh[g * k + k] - shsh[g * k] * opt[k];
		if (g % 2 == 1) {
			now = hshs[g * k + k] - hshs[g * k] * opt[k];
		}
		if (now == shsh[k]) {
			continue;
		}
		else {
			if (g % 2 == 1) {
				for (int i = 0; i < k; ++i) {
					if (X[i + k * g] > Y[i]) {
						break;
					}
					else if (X[i + k * g] < Y[i]) {
						flag = false;
						break;
					}
				}
			}
			else {
				for (int i = 0; i < k; ++i) {
					if (X[i + k * g] > X[i]) {
						break;
					}
					else if (X[i + k * g] < X[i]) {
						flag = false;
						break;
					}
				}
			}
			break;
		}
	}
	if (flag)res++;
	return res;
}

