void check(int x)
{
	for(int i = 0; i < n; i++)
	{
		if(s[i] == 1)
		{
			if(i < x || lst[i % x] == 1)
			{
				if(i < x) g[x] = (g[x] + mi[x - i - 1]) % mod;
				else g[x] = (g[x] + 1) % mod;
			}
		}
		if(i == n - 1)
		{
			if(i < x || s[i] != lst[i % x]) g[x] = (g[x] + 1) % mod;
			continue;
		}
		if(i >= x)
		{
			if(s[i] == lst[i % x]) return;
		}
		lst[i % x] = s[i];
	}
}

