	for(int i = 1; i <= n; i++)
	{
		if(n % i == 0 && n / i % 2 == 1)
		{
			f[i] = g[i];
			for(int j = 1; j * j <= i; j++)
			{
				if(i % j == 0)
				{
					if(j != i) f[i] = (f[i] - f[j] + mod) % mod;
					if(i / j != j && i / j != i) f[i] = (f[i] - f[i / j] + mod) % mod;
				}
			}
		}
	}
	int ans = 0;
	for(int i = 1; i <= n; i++)
	{
		ans = (ans + 1ll * i * 2 * f[i]) % mod;
	}
	printf("%d\n", ans);
}

