#define MOD   998244353LL

ll solve(ll n, const string &x, ll div)
{
    ll count = 0LL;
    rep (i, div) {
        count *= 2LL;
        count %= MOD;
        if (x[i] == '1') {
            count++;
            count %= MOD;
        }
    }
    count++;
    count %= MOD;

    rep (i, n) {
        char divc = x[i%div];
        if ((i/div)&1LL) divc = (divc == '0' ? '1' : '0');
        if (x[i] < divc) {
            count--;
            while (count < 0LL) count += MOD;
        }
        if (x[i] != divc) break;
    }

    return count;
}

int _main()
{
    ll n; llin(n);
    string x; CIN(x);

    V<ll> divisors_v;
    set<ll> divisors;
    get_divisors(divisors_v, n);
    for (auto div : divisors_v) divisors.insert(div);

    M<ll, ll> counts;
    for (auto div : divisors) counts[div] = 0LL;

    for (auto div : divisors) {
        if (((n / div) & 1LL) == 0LL) continue;

        counts[div] += solve(n, x, div);
        counts[div] %= MOD;

        for (auto div2 : divisors) {
            if (div2 <= div) continue;
            if ((div2 == n) || ((div2 % div == 0LL) && ((div2 / div) & 1LL)) ) {
                counts[div2] -= counts[div];
                while (counts[div2] < 0LL) counts[div2] += MOD;
            }
        }
    }

    ll ans = 0LL;

    for (auto count : counts) {
        ll div = count.first;
        ll cnt = count.second;
        ans += (cnt * div * 2LL);
        ans %= MOD;
    }

    cout << ans << endl;

    return 0;
}

