template<class T>
void prime_factors(T n, map<T, int>&out) {
    if(n == 1) { // n=1 の素因数分解はなし
        return;
    }
    for(T i = 2, _n = n; i*i <= _n; ++i) {
        while(n % i == 0) {
            ++out[i]; // 素数i^{out[i]}
            n /= i;
        }
    }
    if(n != 1) out[n] = 1;
}

inline ll square(ll a){return a*a;}

ll pow(ll a, ll b){
    if(b==0)return 1;
    if(b==1)return a;
    if(b%2)return square(pow(a,b/2))*b;
    else return square(pow(a,b/2));
}

bool next_divisor(const map<ll,int>&primes, map<ll,int>&prime_chosen, ll&divisor){
    dprint(primes);
    dprint(prime_chosen, '=', divisor);
    bool carry=true;
    for(auto iter=primes.rbegin();iter!=primes.rend();){
        const auto& p=*iter;
        if(carry){
            if(++prime_chosen[p.F]>p.S){
                divisor/=pow(p.F, prime_chosen[p.F]-1);
                prime_chosen[p.F]=0;
                carry=1;
            }else{
                divisor*=p.F;
                carry=0;
            }
        }
        //
        ++iter;
        if(iter==primes.rend() && carry){
            dprint("over!");
            return false;
        }
    }
    if(carry){
        dprint("over!");
        return false;
    }
    dprint("=>");
    dprint(prime_chosen, '=', divisor);
    return true;
}

