ll rv[MAXN];

ll gogo(int K){
    ll cv = 0;
    for(int i = 0; i < K; i++) cv = (2 * cv + (X[i] - '0')) % MOD;
    if(K == N) cv++;
    for(int i = K; i < N; i++){
        int ov = 1 - (X[i-K] - '0');
        int nv = X[i] - '0';
        if (ov > nv){
            break;
        }else if(ov < nv){
            cv++;
            break;
        }else if (i == N - 1){
            cv++;
            break;
        }
    }
    cv %= MOD;
    return cv;
}

