  for(int i=0;i<data.size();i++){
    //std::cout << data[i][0] << '\n';
    for(int j=2;j*j<=data[i][0];j++){
      if(data[i][0]%j==0){
        //std::cout << PL[N/j] << " " << data[i][1] << '\n';
        ans = (ans + PL[N/j]*data[i][1])%P;
