    for(int i = 1; i*i <= n; ++i) {
        if(n % i != 0) continue;
        res.push_back(i);
        if(n/i == i) continue; // 上の行で追加済み。
        res.push_back(n/i);
    }
    return res;
}

ll dp[200010];

void Main(){

    int N; cin>>N;
    string S; cin>>S;

    vector<int> div=divisors(N);

    ll ct=0;
    ll ct2=0;

    repr(i,div.size()-1,0){
        int kiyaku=div[i]; // Nの約数
        if(kiyaku%2==0) continue;
        ll now=N/kiyaku; //kiyaku個の(任意のnow文字+その反転)があるなら2*nowになる
        if(now==N) continue;

        ll skiyabit=0;

        rep(j,now){
            skiyabit*=2;
            skiyabit+= (S[j]=='1');
            skiyabit%=MOD;
        }

        vector<int> div2=divisors(now);

        rep(j,div2.size()){
            skiyabit-=dp[div2[j]];
        }


        //skiyabit=(skiyabit+MOD)%MOD;

        rep(j,S.size()){
            int x=(S[j%now]=='1' xor !(j/now%2==0) );

            int kazu= (S[j]=='1');
            if(kazu>x){
                ++skiyabit;
                break;
            }
            if(kazu<x){
                break;
            }
            if(j==S.size()-1){
                ++skiyabit;
                break;
            }
        }

        dp[now]=skiyabit;

        ct+=skiyabit;

        ct2+=skiyabit*now;
        ct2%=MOD;
    }

    ll ans=0;

    rep(i,N){
        ans*=2;
        ans+= (S[i]=='1');
        ans%=MOD;
    }

    ans+=1;

    ans=(ans-ct%MOD+MOD)%MOD;

    //db(ans);

    ans=ans*2*N%MOD;

    //db(ct);
    //db(ct2);

    ans=(ans+ct2*2)%MOD;

    cout<< ans<<"\n";


}

