mint func(int i, int state, std::string& str)
{
	if (N < len) {
		return 0_mi;
	}

	if (str.size() < len) {
		mint res = 0;
		str = "";
		for (int i = 0; i < len; i++)
		{
			if (X[i] == '0') {
				str.push_back('0');
			}
			else {
				res += pow2[len - i - 1];
				str.push_back('1');
			}
		}
		res += func(len, len, str);
		return res;
	}
	if (i == N) {
		return 1_mi;
	}

	if (X[i] == '0') {
		if ((state / len == 1) == (str[state % len] == '1')) {
			return func(i + 1, (state + 1) % (2 * len), str);
		}
		return 0_mi;
	}
	else {
		if ((state / len == 1) == (str[state % len] == '1')) {
			return 1_mi;
		}
		return func(i + 1, (state + 1) % (2 * len), str);
	}
}

