ll mod = 998244353;
ll modnum(string S) {
	ll res = 0;
	ll cur = 1;
	reverse(all(S));
	for (int i = 0; i < S.size(); i++) {
		if (S[i] - '0')res += cur;
		cur *= 2;
		cur %= mod;
	}
	return res;
}
int co(string a,string b) {
	for (int i = 0; i < a.size(); i++) {
		if (a[i] == '0' && b[i] == '1')return 1;
		else if (a[i] == '1' && b[i] == '0')return 0;
	}
	return 1;
}

int main() {
	ios::sync_with_stdio(false);
