	int N;
	string X;
	cin >> N >> X;
	if (N % 3 != 0) {
		puts((2LL*N*(modnum(X)+1))%mod);
		return 0;
	}

	string Xtemp;
	for (int i = 0; i < N / 3; i++)Xtemp += X[i];
	ll cnt1 = modnum(Xtemp);


	string comp;
	comp += Xtemp;
	for (int i = 0; i < N / 3; i++) {
		if (Xtemp[i] == '1')comp.pb('0');
		else comp.pb('1');
	}
	comp += Xtemp;

	if (co(comp, X))cnt1 += 1;


	ll ans = 0;
	ll cnt2 = modnum(X) + 1;
	cnt2 -= cnt1;
	cnt2 += mod;
	cnt2 %= mod;
	ans = 2LL*cnt1 * ((ll)N / 3LL) + cnt2 * ((ll)N * 2LL);
	ans %= mod;
	puts(ans);

	return 0;
}

