using MM = IntMod<998244353>;

int N;
string S;
MM A[200001];

vector<bool> primeTable(int n) {
	vector<bool> table(n + 1, true);
	table[0] = false;
	table[1] = false;

	auto nextPrime = [n, &table](int p) -> int {
		do {
			++p;
		} while (p <= n && !table[p]);
		return p;
	};

	for (int p = 2; p * p <= n; p = nextPrime(p)) {
		for (int i = p * p; i <= n; i += p) {
			table[i] = false;
		}
	}
	return table;
}

void moebiusInversion() {
	vector<bool> is_prime = primeTable(N);
	for (int p = 2; p <= N; ++p) {
		if (!is_prime[p]) continue;
		for (int i = N / p; i >= 1; --i) {
			A[i * p] -= A[i];
		}
	}
}

string flip(string s) {
	for (char& c : s) {
		c ^= 1;
	}
	return s;
}

MM sub(int k) {
	string T = S.substr(0, k);

	MM sum = 0;
	for (int i = 0; i < k; ++i) {
		sum *= 2;
		if (T[i] == '1') ++sum;
	}

	string U;
	for (int z = 0; z < N / k; ++z) {
		U += T;
		U += flip(T);
	}

	if (U <= S) {
		++sum;
	}
	return sum;
}

int main() {
	cin >> N >> S;
	S += flip(S);
	for (int i = 1; i <= N; ++i) {
		if (N % i != 0) continue;
		if (N / i % 2 == 0) continue;
		A[i] = sub(i);
	}

	moebiusInversion();
	MM sum = 0;
	for (int i = 1; i <= N; ++i) {
		if (N % i != 0) continue;
		if (N / i % 2 == 0) continue;
		sum += 2 * i * A[i];
	}
	cout << sum << endl;
	return 0;
}

