int getc ( int l )
{
	int ans = 0;
	lp ( i, 0, l ) {
		addv ( ans, ans );
		addv ( ans, s[i] - '0' );
	}
	char nt;
	bool flag = true;
	lp ( i, 0, n ) {
		nt = s[i%l];
		if ( ( i / l ) & 1 ) {
			nt ^= '0' ^ '1';
		}
		if ( nt < s[i] ) {
			break;
		} else if ( nt > s[i] ) {
			flag = false;
			break;
		}
	}
	if ( flag ) addv ( ans, 1 );
	return ans;
}

int getdp ( int l )
{
	INIT ( dp, 0 );
	int nc;
	lpi ( i, 1, l ) {
		if ( mp.find ( i ) != mp.end () ) {
			nc = mp[i];
			addv ( dp[i], nc );
			for ( int j = i << 1; j <= l; j += i ) subv ( dp[j], dp[i] );
		}
	}
	return dp[l];
}

