namespace Calc_with_MOD{
	const int mod=1e9+7;
	int add(ll a,ll b){
		ll ret=a+b;
		if(ret<=0)ret+=mod;
		ret%=mod;
		return ret;
	}
	int dec(ll a,ll b){
		ll ret=a-b;
		if(ret<=0)ret+=mod;
		ret%=mod;
		return ret;
	}
	int mul(ll a,ll b){
		a%=mod;b%=mod;
		ll ret=a*b%mod;
		//ret%=mod;
		if(ret<=0)ret+=mod;
		return ret;
	}
	ll fpm(ll a,ll b){
		ll ret=1ll;
		for(;b;b>>=1,a=a*a%mod)
			if(b&1)ret=ret*a%mod;
		return ret;
	}
}
