int calc(int x){
	int k=n/x,res=0;
	for(int i=1;i<=k;++i){
		res=add(res,res);
		if(s[i]=='1')res=add(res,1);
	}
	int flag=1;
	for(int i=k+1;i<=n;++i){
		int r=(i-1)%(2*k)+1,c;
		if(r<=k)c=s[r]-'0';
		else c=s[r-k]-'0',c^=1;

		if(c<s[i]-'0')break;//if T is lexicographically less than T'
		else if(c==s[i]-'0')continue;//continue for compare
		else {flag=0;break;} //not satisfy
	}

	res+=flag;
	return res;
}
