    // t 周期
    ll num = 0;
    rep(i, t) {
        num <<= 1;
        num += X[i] - '0';
        num %= MOD;
    }
    num++;
    rep(i, N) {
        int digit = X[i % t] - '0';
        if ((i / t) % 2 == 1) digit = 1 - digit;
        // dump(i, t, digit, X[i] - '0');
        if (digit == 0 && X[i] == '1') {
            break;
        }
        if (digit == 1 && X[i] == '0') {
            (num += MOD - 1) %= MOD;
            break;
        }
    }
    // dump(t, num);
    return num;
}

