        num[N] <<= 1;
        num[N] += X[i] - '0';
        num[N] %= MOD;
    }
    num[N]++;

    repr(i, 1, N) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            num[i] = calc(i);
            // dump(i, num[i]);
        }
    }
    vvi divs(N + 1);
    repr(i, 1, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            repr(j, 1, sqrt(N) + 1.5) {
                if (i % j == 0) {
                    if (j != i) {
                        divs[i].push_back(j);
                    }
                    if (j < i / j && i / j != i) {
                        divs[i].push_back(i / j);
                    }
                }
            }
        }
    }
    repr(i, 2, N + 1) {
        if (N % i == 0 && (N / i) % 2 == 1) {
            // 周期 i が成立
            for (auto d : divs[i]) {
