//////      階乗を全て求める -> 二項係数を求める

long invs[MAX], facts[MAX], finvs[MAX];
long listlen = 0;  // invs, facts, finvsの配列長
void computeAll(long n) {
    if (n >= MAX)
        cerr << "modlong error: index out of range in computeAll" << '\n';
    long i;
    if (listlen == 0) {
        invs[1] = 1;
        facts[0] = 1;
        facts[1] = 1;
        finvs[0] = 1;
        finvs[1] = 1;
        i = 2;
    } else {
        i = listlen;
    }
    if (n < 2) return;
    for (; i <= n; i++) {
        invs[i] = -invs[MOD % i] * (MOD / i) % MOD;
        facts[i] = facts[i - 1] * i % MOD;
        finvs[i] = finvs[i - 1] * invs[i] % MOD;
    }
    listlen = n + 1;  // 次呼び出すときはn+1以降から再開すれば良い
}
// コンビネーション
modlong modComb(long n, long k) {
    if (k < 0 || k > n) return 0;
    if (k == 0 || k == n) return 1;
    if (listlen <= n) computeAll(n);  // 毎回足りない分だけ補う
    return modlong(facts[n]) * finvs[k] * finvs[n - k];
}
// 階乗
modlong modFact(long n) {
    if (listlen <= n) computeAll(n);  // 毎回足りない分だけ補う
    return modlong(facts[n]);
}

#define MAX_N 200000
using bs = bitset<MAX_N>;

modlong from_bs(bs x) {
    modlong ans=0, pow=1;
    for (int i=0; i<MAX_N; i++) {
        if (x[i]) ans += pow;
        pow *= 2;
    }
    return ans;
}

int main() {
    int n;
    bs x;
    cin >> n >> x;
    modlong dp[n+1][4], ans = 0;
    fill(dp[0], dp[n+1], 0);
    dp[0][0] = 1;
    modlong used = 0;
    bool chodo = false;
    for (int i=1; i<=n; i++) {
        dp[i][0] = dp[i-1][0];
        dp[i][1] = dp[i-1][1] + (x[n-1] ? dp[i-1][0] : 0);
        if ((i % 2 != 0 || i == n) && n % i == 0) {
            int res = 1;
            for (int j = i+1; j<=n; j--) {
                bool ref = x[n - j % i] ^ ((j / i) % 2);
                if (x[n - j] > ref) {
                    res = 2;
                    break;
                } else if (x[n - j] < ref) {
                    res = 0;
                    break;
                }
            }
            modlong add = from_bs(x >> (n - i)) + (res ? 1 : 0) - used;
            if (chodo && res == 1) add -= 1;
            if (!chodo && res == 1) chodo = true;
            ans += add * i * 2;
            used += add;
        }
    }
    cout << ans << '\n';
    return 0;
}

