  return res;
}

//約数の列挙O(√n)
vector<int> divisor(int n){
    vector<int> res(0);
    for(int i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}


int N;
string X;
ll loop[200010];
void solve(){
  cin >> N;
  cin >> X;
  for(int i = 1; i <= N; i+=2){
    if(N % i) continue;
    int len = N / i;
    ll sum = 0;
    rep(j, len) sum = (sum * 2 + (X[j] == '1')) % MOD;
    loop[i] += sum;
    string MA;
    string one = X.substr(0, len);
    string rev = one;
    rep(_, len) rev[_] = '0' + (rev[_] == '0');
    rep(_, N/len){
      if(_&1) MA += rev;
      else MA += one;
    }
    if(MA <= X) loop[i]++;
  }
  for(int i = N; i >= 1; i--)if(i & 1)if(N % i == 0){
    vector<int> divs = divisor(i);
    for(int j: divs){
      if(j == i) continue;
      loop[j] += MOD - loop[i];
      loop[j] %= MOD;
    }
  }
  ll ans = 0;
  for(int i = 1; i <= N; i++){
    ans += 2 * (N / i) * loop[i] % MOD;
    ans %= MOD;
  }
  cout << ans << endl;
}

int main(){
  ios_base::sync_with_stdio(0);
  cin.tie(0), cout.tie(0);
  solve();
}

