const ll mod = 998244353;

ll calc(ll x, ll n){
    ll ret = 0;
    ll y = x;
    do{
        ret++;
        if (y % 2) y /= 2;
        else y = y / 2 + (1LL << (n - 1));
    }while (y != x);
    return ret;
}

ll count(VI &a, ll c){
    ll n = a.size(), m = n / c;
    VVL dp(c + 1, VL(2));
    dp[0][0] = 1;
    REP(i,c) REP(f,2) REP(x,2){
        if (!f && x > a[i]) continue;
        int ff = f | (x < a[i]);
        (dp[i+1][ff] += dp[i][f]) %= mod;
    }
    // REP(i,c+1){
    //     REP(f,2){
    //         cout << dp[i][f] << " ";
    //     }
    //     cout << endl;
    // }
    ll ret = 0;
    REP(f,2){
        ret = (ret + dp[c][f]) % mod;        
    }
    VI b;
    REP(i,n){
        int p = (i / c) % 2;
        b.push_back(a[i % c] ^ p);
    }
    if (b > a) ret = (ret - 1 + mod) % mod;
    return ret;
}

