using Graph = vector<vi>;  // vi <=> vl
using P = pair<int, int>;  // int <=> ll
const int MOD = 998244353;
const double EPS = 1e-9;

int main() {
  int n; cin >> n;
  bitset<200000> s; cin >> s;

  vl power(n);
  power[0] = 1;
  rep(i,n-1) power[i+1] = power[i] * 2 % MOD;
  ll num = 1;
  rep(i,n) if (s.test(i)) (num += power[i]) %= MOD;
  ll ans = n*2 * num % MOD;

  map<int, ll> decrease;
  ll tmp = 0;

  for (int i=1; i<=n/3; ++i) {
    ((tmp *= 2) += s[n-i]) %= MOD;

    if (n%i == 0 && n/i%2 == 1) {
      decrease[i] = tmp;

      bool x = true;
      bool exit = false;

      for (int j=1; j<n/i; ++j) {
        for (int k=1; k<=i; ++k) {
          int bit = s[n-k];
          if (j%2) bit = 1 - bit;

          if (s[n-j*i-k] == bit) continue;

          if (s[n-j*i-k] < bit) x = false;
          exit = true;
          break;
        }
        if (exit) break;
      }

      if (x) ++decrease[i];
    }
  }

  vi length;

  for (auto p : decrease) {
    int key = p.first;

    for (auto d : length) {
      if (key%d == 0 && key/d%2 == 1) {
        decrease[key] -= decrease[d];
        if (decrease[key] < 0) decrease[key] += MOD;
      }
    }

    ans -= (n*2 - key*2) * decrease[key] % MOD;
    if (ans < 0) ans += MOD;
    length.push_back(key);
  }

  cout << ans << endl;
  return 0;
}

