using namespace std;

const ll mod = 998244353; 
const int N = 200200; 

int n; 
int a[N]; 
int mx[N], mn[N]; 
ll F[N], G[N]; 

void chkmax(int *t, int n) {
  int flag = 0; 
  for (int i = 1; i <= n; i++) {
    if (t[i] < mx[i]) return ; 
    if (t[i] > mx[i]) {
      flag = 1; break ; 
    }
  }
  if (flag) {
    for (int i = 1; i <= n; i++) 
      mx[i] = t[i]; 
  }
}

void chkmin(int *t, int n) {
  int flag = 0; 
  for (int i = 1; i <= n; i++) {
    if (t[i] > mn[i]) return ; 
    if (t[i] < mn[i]) {
      flag = 1; break ; 
    }
  }
  if (flag) {
    for (int i = 1; i <= n; i++) {
      mn[i] = t[i]; 
    }
  }
}

int tmp[N]; 

ll calc(int n) {
  int flag = 1; 
  for (int i = 1; i <= n; i++) {
    if (mn[i] < mx[i]) {
      flag = 0; break ; 
    } 
    if (mn[i] > mx[i]) {
      break ; 
    }
  }
  if (!flag) return 0; 
  ll X1 = 0, X2 = 0; ll pw = 1; 
  for (int i = n; i >= 1; i--) 
    X1 += pw * mx[i] % mod, X1 %= mod, pw *= 2, pw %= mod; 
  pw = 1;  
  for (int i = n; i >= 1; i--) 
    X2 += pw * mn[i] % mod, X2 %= mod, pw *= 2, pw %= mod; 
  return ((X2 - X1 + 1) % mod + mod) % mod; 
}

