#endif

  scanf("%d", &n); 
  for (int i = 1; i <= n; i++)
    scanf("%1d", &a[i]);
  for (int i = 1; i <= (n << 1); i++) {
    if ((n << 1) % i != 0 || !(((n << 1) / i) & 1)) 
      continue ; 
    for (int j = 1; j <= i / 2; j++) {
      mx[j] = 0, mn[j] = 1; 
    }
    int T = 0; 
    for (int j = 1; j <= n; j += i / 2) {
      T++; 
      for (int k = 1; k <= i / 2; k++) {
        tmp[k] = a[j + k - 1]; 
        if(T % 2 == 0) tmp[k] ^= 1; 
      }
      if (T % 2 == 0) chkmax(tmp, i / 2); 
      else chkmin(tmp, i / 2); 
    }
    F[i] = calc(i / 2); 
    // printf("%d %lld ",i, F[i]); 
  }
  ll ans = 0; 
  for (int i = 1; i <= 2 * n; i++) {
    if((2 * n % i == 0) && ((2 * n / i) & 1)) {
      ans = (ans + F[i] * i % mod) % mod; 
      for (int j = i + i; j <= 2 * n; j += i) {
        if((2 * n % j == 0) && ((2 * n / j) & 1))
          F[j] = (mod + F[j] - F[i]) % mod; 
      }
    }
  }
  printf("%lld\n", ans); 
  return 0; 
}

