  bool cur = false;
  int cnt = 0;
  do {
    vs[p] = cur;
    cur ^= ((p + x) / n) & 1;
    p = (p + x) % n;
    ++cnt;
  } while (p != 0);
  int sz = n / cnt, ret = 0;
  for (int i = 1; i <= sz; ++i)
    ret = (ret * 2 + s[n - i]) % P;
  for (int i = n - 1; i; --i) {
    int p = i % sz;
    bool dig = s[n - sz + p] ^ vs[i - p] ^ vs[n - sz];
    if (dig > s[i])
      return ret;
    if (dig < s[i])
      return norm(ret + 1);
  }
  return norm(ret + 1);
}

