				farestID = next;
			}
			return true;
			});
		return { farestID, far };
	}
	//木の半径
	//ループがあるときの動作は未検証
	int radius() {
		if (vertex.size() <= 1)return 0;
		auto res = radiusImpl(0);
		res = radiusImpl(res.first);
		return res.second;
	}
