    int t = x[i - 1] - '0';
    temp = (temp * 2 + t) % MOD;
    if ((n % i != 0) || (n / i % 2 == 0)) continue;

    int dictcheck = 0;
    string loop = makeloop(x, n, i);
    if (x >= loop) {
      dictcheck = 1;
    }

    vector<int> divisor;
    rep(j, i - 1) {
      if (i % (j + 1) == 0) divisor.push_back(j + 1);
    }
    int done = 0;
    for (auto& d : divisor) {
      done += num[d];
    }
    ans = (ans + (MOD + temp + dictcheck - done) % MOD * 2 * i % MOD) % MOD;
    num[i] = temp + dictcheck - done;
  }

