ll mod = 998244353;
int N;
string X;
set<int>dv;

void divisor(ll n) {
	for (ll i = 1; i*i <= n; i++) {
		if (n%i == 0) {
			if (i == n / i) {
				dv.insert(i);
			}
			else {
				dv.insert(i);
				dv.insert(n / i);
			}
		}
	}
}

ll modnum(string S) {
	ll cur = 1;
	ll ret = 0;
	reverse(all(S));
	for (int i = 0; i < S.size(); i++) {
		if (S[i] - '0' == 1)ret += cur;
		cur *= 2;
		cur %= mod;
	}
	return ret;
}

ll count(int d) {
	string Xtemp;
	int len = N / d;
	for (int i = 0; i < len; i++)Xtemp += X[i];
	ll ret = modnum(Xtemp);
	string Xcomp;
	for (int i = 0; i < N; i++) {
		if ((i / len) % 2 == 0) {
			if (X[i%len] == '0')Xcomp += '0';
			else Xcomp += '1';
		}
		else {
			if (X[i%len] == '1')Xcomp += '0';
			else Xcomp += '1';
		}
	}


	int ok = 0;
	vector<string>dic;
	dic.pb(Xcomp);
	dic.pb(X);
	sort(all(dic));
	if (dic[0] == Xcomp)ok = 1;
	ret += ok;
	return ret;
}


int main() {
	ios::sync_with_stdio(false);
	cin.tie(nullptr);


	cin >> N >> X;
	divisor(N);
	fore(x, dv)if (x % 2 == 0)dv.erase(x);

	map<int, int>mp;
	fore(d, dv)mp[d] = count(d);
	set<int>sttemp;
	fore(x, dv)sttemp.insert(x);

	while (sttemp.size()) {
		auto it = sttemp.end();
		it--;
		int b = *it;
		sttemp.erase(b);
		dv.clear();
		divisor(b);
		fore(x, dv) {
			if (x != b && count(x))mp[x] -= mp[b];
		}
	}

	ll ans = 0;
	fore(x, mp) {
		ll num = x.first;
		ll cnt = x.second;
		ll len = N / num;
		ans += 2LL * len*cnt;
		ans %= mod;
	}
	puts(ans);
	return 0;
}

