const int mod = 998244353;

ll solve(string X){
	int n = X.size();

	for(int i=1;i<=n;++i) divs[i].clear();
	for(int i=1;i<=n;++i) for(int j=i;j<=n;j+=i) if((j/i)%2==1 && n%j==0) divs[j].push_back(i);

	vector<int> p2(n+1);
	for(int i=p2[0]=1; i<=n; ++i) p2[i]=p2[i-1]*2 %mod;

	vector<int> F(n+1);

	ll ans = 0;

	vector<int> h(n+1);
	for(int k : divs[n]){
		bool ok = true;
		for(int i=0;i<n;++i){
			ok&= X[i] == (X[i%k]^(i/k%2));
			if(!ok){
				h[k] = i;
				break;
			}
		}
		if(ok) h[k] = n;
	}

	for(int pref=0;pref<=n;++pref){
		if(pref<n && X[pref]=='0') continue;

		int len = (pref==n ? n : pref + 1);
		for(int k : divs[n]){
			if(len <= k){
				F[k] = p2[k-len];

			}else{
				bool ok = h[k]>len-2;
				char c = pref<n ? '0' : X.back();
				ok&= c==(X[(len-1)%k]^((len-1)/k%2));
				F[k] = ok;
			}
			for(int k2 : divs[k]) if(k2<k){
				F[k]-=F[k2];
				if(F[k]<0) F[k]+=mod;
			}
			ans+= 2LL*k*F[k];
			ans%=mod;
			//cerr<<"?"<<pref<<": "<<k<<": "<<F[k]<<endl;
		}
	}

	return ans;
}

