//約数の列挙O(√n)
vector<ll> divisor(ll n){
    vector<ll> res(0);
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.push_back(i);
            if(i != n/i) res.push_back(n/i);
        }
    }
    sort(res.begin(), res.end());
    return res;
}

ll N;
string S;
vector<ll> loop(200010);

void solve(){
  ll x = 0;
  rep(i, N){
    x *= 2;
    if(S[i] == '1') x++;
    x %= MOD;
  }
  ll ans = (x + 1) * N * 2 % MOD;
  for(ll i = 1; i < N; i++){//i個
    if(N % i) continue;
    if(N / i % 2 == 0) continue;
    ll x = 0;
    rep(j, i){
      x = x * 2;
      if(S[j] == '1') x++;
      x %= MOD;
    }
    string H, W, X;
    rep(j, i) H += S[j];
    W = H;
    rep(j, i){
      if(W[j] == '1') W[j] = '0';
      else W[j] = '1';
    }
    rep(j, N/i){
      if(j % 2) X += W;
      else X += H;
    }
    if(S >= X) x++;
    loop[i] = x;
  }
  for(ll i = 1; i <= N; i++){
    for(ll j = i * 2; j <= N; j += i){
      loop[j] -= loop[i];
    }
  }
  for(ll i = 1; i <= N; i++){
    if(N % i) continue;
    if(N / i % 2 == 0) continue;
    ans -= 2 * N * loop[i] % MOD;
    ans += i * 2 * loop[i] % MOD;
    ans %= MOD;
  }
  ans = (ans + MOD) % MOD;
  cout << ans << endl;

}

