            }
            for(j = 0; j < c && i * p[j] < N; j ++)
            {
                u[i * p[j]] = true;
                f[i * p[j]] = -f[i];
                if(!(i % p[j]))
                    break;
            }
        }

        for(i = 0; i < N; i ++)
