int Approach(int d)
{
    int i, j, o;

    for(i = o = 0; i < d; i ++)
        if(a[i] == '1')
            o = (o + p[d - i - 1]) % MOD;
    for(i = d; i < n; i += d)
        for(j = 0; j < d; j ++)
        {
            if((i / d) & 1 && (a[j] == '0' && a[i + j] == '0'))
                return o;
            if((i / d) & 1 && (a[j] == '1' && a[i + j] == '0'))
                return (o + 1) % MOD;
            if(~(i / d) & 1 && (a[j] == '1' && a[i + j] == '0'))
                return o;
            if(~(i / d) & 1 && (a[j] == '0' && a[i + j] == '1'))
                return (o + 1) % MOD;
        }

    // printf("can add 1 at %d\n", d);

    return (o + 1) % MOD;
}

int Solve(int n)
{
