LL GET(int pos){
	LL now=0;
	rep(i,1,pos)now=(now<<1)+b[i],now%=MOD;
	int p=0,flg=0;
	rep(i,1,n){
		p++;
		if(p==pos+1)p=1,flg^=1;
		int x=b[p]^flg;
		if(x>b[i])return now;
		if(x<b[i])return now+1;
	}
	return now+1;
}

void SOLVE(){
	int cnt=0;
	LL ans=0;
	for(int i=1;i*i<=n;i++){
		if(n%i)continue;
		if(i&1)d[++cnt]=n/i;
		if(i*i==n)break;
		if((n/i)&1)d[++cnt]=i;
	}
	sort(d+1,d+cnt+1);
	rep(i,1,cnt){
		c[i]=GET(d[i]);
		rep(j,1,i-1)if(d[i]%d[j]==0)c[i]-=c[j];
		ans+=c[i]*d[i]%MOD*2%MOD;ans%=MOD;
	}
	printf("%lld\n",ans);
}

