int main(){
    int n;
    cin >> n;
    string x;
    cin >> x;
    long long ans = 0;
    int r = 0;
    for (int i = 0; i < n; i++){
        if (x[i] != '1') {
            r = i + 1;
            break;
        }
        if (i == n - 1) r = i + 1;
    }
    ans += (long long)r * 2 * n % mod;
    int l = 0;
    for (int i = 0; i < n; i++){
        if (x[i] == '1') {
            l = i;
            break;
        }
        if (i == n - 1) l = i;
    }
    bool flag = true;
    for (int i = l; i < n; i++){
        if (x[i] == '0') flag = false;
    }
    if (!flag) l++;
    ans += (long long)(n - l) * 2 * n % mod;

    vector<int> prime;
    for (int i = 1; i * i <= n; i += 2){
        if (n % i == 0){
            prime.push_back(i);
            if (i == 1) continue;
            if (i * i != n && (n / i) % 2) prime.push_back(n / i);
        }
    }
    sort(prime.begin(), prime.end());
    int ok = - 1;
    int ng = prime.size();
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (r > prime[mid]) ok = mid;
        else {
            bool flag = false;
            bool check = true;
            for (int i = 0; i < n; i++){
                if ((i / prime[mid]) % 2){
                    if (x[i] == '1') {
                        if (check) flag = true;
                    }
                }
                else {
                    if (x[i] == '0') check = false;
                }
            }
            if (flag || check) ok = mid;
            else ng = mid;
        }
    }
    for (int i = 0; i <= ok; i++) ans += 2 * prime[i];
    ok = prime.size();
    ng = - 1;
    while (abs(ok - ng) > 1){
        int mid = (ok + ng) / 2;
        if (l <= prime[mid]) ok = mid;
        else {
            bool flag = false;
            bool check = true;
            for (int i = 0; i < n; i++){
                if ((i / prime[mid]) % 2 == 0){
                    if (x[i] == '1') {
                        if (check) flag = true;
                    }
                }
                else {
                    if (x[i] == '0') check = false;
                }
            }
            if (flag || check) ok = mid;
            else ng = mid;
        }
    }
    for (int i = ok; i < prime.size(); i++) ans += 2 * prime[i];
    cout << ans << endl;
}

