int main(){
	cin>>N>>S;
	for (int i=3;i<=N;i+=2)if (!(N%i)){
		bucket_sizes.pb(N/i);
	}
	// for (auto i : bucket_sizes)cout<<i<<' ';cout<<'\n';
	reverse(ALL(bucket_sizes));

	ll m = 1;
	ans = 1;
	for (int i=N-1;i>=0;--i){
		if(S[i] == '1'){ans += m; ans %= MOD;}
		mod2[N-1-i] = m;
		m = (m*2)%MOD;
	}
