	for (auto bsiz : bucket_sizes){
		ll offset = 0;
		for (auto j:bucket_sizes)if(bsiz%j == 0){offset += mem[j];offset %= MOD;}
		// cout<<bsiz<<' '<<offset<<'\n';
		ll s = 0;
		rep = con = opp = "";

		for (int j=0;j<bsiz;++j){
			if (S[bsiz - 1 - j] == '1'){
				s += mod2[j];
				s %= MOD;
			}
			rep += S[j];
			opp += ('0' + '1' - S[j]);
