			in = 1 - in;
		}
		if (con <= S)++s;
		s = (s+MOD-offset)%MOD;
		// cout<<"Discount "<<bsiz<<' '<<s<<'\n';
		ans = (ans + MOD - (s * (2*N - 2*bsiz))%MOD)%MOD;
		mem[bsiz] = s;
	}

	cout<<ans;
}

