		res=(res*2ll%mod+a[i])%mod;
	}
	for (int i=0;i<2*n;i+=len*2){
		for (int j=1;j<=len;j++) b[i+j]=a[j];
		for (int j=len+1;j<=2*len;j++) b[i+j]=!a[j-len];
	}
