template <typename T> inline void read(T &AKNOI) {
    T x = 0, flag = 1;
    char ch = getchar();
    while (!isdigit(ch)) {
        if (ch == '-') flag = -1;
        ch = getchar();
    }
    while (isdigit(ch)) {
        x = x * 10 + ch - '0';
        ch = getchar();
    }
    AKNOI = flag * x;
}

int n, ok[MAXN], f[MAXN], ans;
char s[MAXN], t[MAXN];

inline void Inc(int &x, int y) {
	x += y; if (x >= MOD) x -= MOD;
}

inline void Dec(int &x, int y) {
	x -= y; if (x < 0) x += MOD;
}

inline int Mul(int x, int y) {
	return 1LL * x * y % MOD;
}

inline int Calc(int x) {
	int ret = 0;
	for (int i = 1; i <= x; ++i) {
		ret = (ret * 2 + s[i] - '0') % MOD;
	}
	for (int i = 1, j = 1; i <= n; ++i, j = (j == x * 2)? 1 : (j + 1)) {
		t[i] = (j <= x)? s[j] : (s[j - x] ^ 1);
	}
	for (int i = 1; i <= n; ++i) {
		if (s[i] > t[i]) return ret + 1;
		if (s[i] < t[i]) return ret;
	}
	return ret + 1;
}

void init() {
	read(n);
	scanf("%s", s + 1);
}

void solve() {
	for (int i = 1; i <= n; ++i) {
		ok[i] = (n % i == 0 && (n / i) % 2 == 1);
	}
	ans = Mul(Calc(n), n * 2);
	for (int i = n - 1; i >= 1; --i) {
		if (!ok[i]) continue;
		int tmp = n * 2;
		for (int j = i; j <= n; j += i) {
			Inc(tmp, f[j]);
		}
		f[i] = i * 2;
		Dec(f[i], tmp);
		Inc(ans, Mul(Calc(i), f[i]));
	}
	printf("%d\n", ans);
}

int main() {
	init();
	solve();
	return 0;
}

