int Power(int x, int y)
{
    int o;

    for(o = 1; y; y >>= 1)
    {
        if(y & 1)
            o = (long long)o * x % MOD;
        x = (long long)x * x % MOD;
    }

    return o;
}

int Approch(int d)
{
    int i, j, o;

    for(i = o = 0; i < d; i ++)
        if(a[i] == '1')
            o = (o + p[d - i - 1]) % MOD;
    for(i = d; i < n; i += d)
        for(j = 0; j < d; j ++)
        {
            if((i / d) & 1 && (a[j] == '0' && a[i + j] == '0'))
                return o;
            if((i / d) & 1 && (a[j] == '1' && a[i + j] == '0'))
                return (o + 1) % MOD;
            if(~(i / d) & 1 && (a[j] == '1' && a[i + j] == '0'))
                return o;
            if(~(i / d) & 1 && (a[j] == '0' && a[i + j] == '1'))
                return (o + 1) % MOD;
        }

    // printf("can add 1 at %d\n", d);

    return (o + 1) % MOD;
}

int Solve(int n)
{
    int i, o, c;

    if(g[n] != -1)
        return 0;

    for(i = 1, o = c = 0; i <= n; i += 2)
        if(!(n % i))
        {
            if(i != 1)
                o = (o + Solve(n / i)) % MOD;
            c += (Sieve::f[i] * Approch(n / i)) % MOD;
        }
    // printf("at %d : app %d\n", n, c);

    return g[n] = (o + (long long)c * n * 2 % MOD) % MOD;
}

