bool same_jedynki(string s){
    for(auto & u : s)
        if(u != '1')
            return false;
    return true;
}

string dodaj(string s){
    if(same_jedynki(s)){
        string ret = s;
        ret.pb('1');
        FOR(i, n)
            ret.pb('0');
    }
    else{
        while(s.back() == '1')
            s.pop_back();
        s.pop_back();
        s.push_back('1');
        while(sz(s) < n)
            s.push_back('0');
        return s;
    }
    assert(false);
}

bool mniejszy(string s){
    for(int i = 0; i <= n; i++){
        if(s[i] == '1' and X[i] == '0')
            return false;
        if(s[i] == '0' and X[i] == '1')
            return true;
    }
    return true;
}

string zrob(string&cykl, int poz){
    string ret;
    while(sz(ret) < n){
        ret.pb(cykl[poz]);
        poz++;
        if(poz == sz(cykl))
            poz = 0;
    }
    return ret;
}

