bool check_pref(int K, vi& X, int N) {
    vi pref(K);
    vi nstr(N);
    for (int i=0;i<N/K;i++) {
        for (int j=0;j<K;j++) {
            if (i%2 == 0) nstr[K*i + j] = X[j];
            else nstr[K*i + j] = 1-X[j];
        }
    }
    return compare_strs(N, nstr, X);
}

ll eval_pref(int K, vi& X) {
    ll pow = 1;
    ll ans = 0;
    for (int i=K-1;i>=0;i--) {
        if (X[i] == 1) {
            ans += pow;
            ans %= MOD;
        }
        pow *= 2;
        pow %= MOD;
    }
    return ans;
}

