vector<int> divisor(int n){
  vector<int> v;
  for(int i=1; i<=sqrt(n); i++){
    if(n%i == 0){
      v.push_back(i);
      if(i!=n/i) v.push_back(n/i);
    }
  }
  sort(all(v));
  return v;
}

int main(void){
  SPEEDUP
  cout << setprecision(15);
  int N;cin >> N;
  string s;cin >> s;
  vector<int> v = divisor(N);
  mint num = 1;
  mint n_2 = 1;
  rep(i,N){
    if(s[N-i-1] == '1') num += n_2;
    n_2*=MINT 2;
  }

  mint ans = 0;
  for(const int & x : v){
    if(x == 1||x%2==0)continue;
    //lenは続く長さ
    //xは繰り返す個数
    int len = N/x;
    string S;
    rep(i,x+1) S += string(len,i%2 + '0');
    int pre = s[0];
    int count = 0;
    rep(i,len){
      if(pre == s[i])++count;
      else break;
    }
    string t = string(count,pre);
    mint n = 0;
    if(pre == '0'){
      reverse(all(S));
      t += S;
      n += MINT len-count;
    }else{
      t += S;
      n += MINT len + count-1;
    }
    t = t.substr(0,N);
    if(t<=s)n+=MINT 1;
    num -= MINT n;
    ans += MINT 2*len*n;
  }

  ans += MINT num*2*N;
  cout << ans << endl;
  return 0;
}

