}

/* Mod must be a prime. */
template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::inverse() const {
	assert(value_m != 0);
	return power(Mod - 2);
}

template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::power(uint64_t exp) const {
	IntMod product(1);
	IntMod factor(*this);
	while (exp > 0) {
		if (exp& 1) {
			product *= factor;
		}
		factor *= factor;
		exp >>= 1;
	}
	return product;
}

template <uint32_t Mod>
inline uint32_t IntMod<Mod>::get() const {
	return value_m;
}

template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::fact(uint32_t num) {
	assert(num <= 0x80000000);

	static std::vector<IntMod<Mod>> table(1, 1);
	if (table.size() > num) return table[num];

	int old_size = table.size();
	table.resize(num + 1);
	for (int i = old_size; i <= num; ++i) {
		table[i] = table[i - 1] * i;
	}
	return table[num];
}

template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::combi(uint32_t n, uint32_t r) {
	assert(n >= r);
	return fact(n) / (fact(n - r) * fact(r));
}

template <uint32_t Mod>
inline IntMod<Mod> IntMod<Mod>::perm(uint32_t n, uint32_t r) {
	assert(n >= r);
	return fact(n) / fact(n - r);
}

template <uint32_t Mod>
inline std::vector<IntMod<Mod>> IntMod<Mod>::calcInverseList(int max) {
	assert(max < Mod);

	std::vector<IntMod> table(max + 1);
	table[1] = 1;
	for (int i = 2; i <= max; ++i) {
		table[i] = (uint64_t(Mod - Mod / i) * table[Mod % i].Get()) % Mod;
	}
	return table;
}

