vector<int> divisors(int n) {
	vector<int> ret;
	for (int i = 2; i * i <= n; ++i) {
		if (n % i == 0) {
			ret.push_back(i);
		}
		while (n % i == 0) {
			n /= i;
		}
	}

	if (n > 1) {
		ret.push_back(n);
	}
	return ret;
}

map<int, MM> moeb(int n) {
	auto divs = divisors(n);
	int k = divs.size();

	map<int, MM> moe;
	REP(s, 0, 1 << k) {
		int prod = 1;
		int val = 1;
		REP(i, 0, k) {
			if (s & (1 << i)) {
				prod *= divs[i];
				val = -val;
			}
		}
		moe[prod] = val;
	}
	return moe;
}

