inline int add(int x, int y){ x += y; if(x >= mod) x -= mod; return x;}
inline int sub(int x, int y){ x -= y; if(x < 0) x += mod; return x;}
inline int mul(int x, int y){ return (x * 1ll * y) % mod;}
inline int powr(int a, ll b){
	int x = 1 % mod;
	while(b){
		if(b & 1) x = mul(x, a);
		a = mul(a, a);
		b >>= 1;
	}
	return x;
}
inline int inv(int a){ return powr(a, mod - 2);}

const int N = 200005;
char num[N];
int ways[N];
int pw2[N];
int f[N];
vector<int> divisors[N];
int main(){
	int n; sd(n);
	scanf("%s", num);
	// reverse(num, num + n);
	int ans = 2 * n;
	int x = 0;
	for(int i = 0; i < n; i++){
		x = (2 * x) % mod;
		if(num[i] == '1') x ++;
		x %= mod;
	}
	ans = add(ans, mul(2 * n, x));
	pw2[0] = 1;
	// trace(x, ans);
	for(int i = 1; i < N; i++) pw2[i] = mul(2, pw2[i - 1]);
	for(int d = 1; d <= n; d++) if(n % d == 0){
		for(int i = 0; i < d; i++) if(num[i] == '1'){
			// first difference at i
			f[d] = add(f[d], pw2[d - 1 - i]);
		}
		int v = 1;
		for(int i = 0; i < n; i++){
			int pos = i  % (2 * d);
			int val1 = num[i] - '0';
			int val2 = pos >= d ? (1 ^ (num[pos - d] - '0')) : (num[pos] - '0');
			if(val1 < val2){
				v = 0;
				break;
			}
			else if(val1 > val2) break;
		}
		// trace(d, f[d], v);
		f[d] = add(f[d], v);
	}
	for(int t = 1; t <= n; t++){
		int l = n % t;
		int g = __gcd(l, t);
		if(l == 0 || (t / g) % 2 == 1) continue;
		ways[t] = f[g];
		for(int h = 2 * t; h <= n; h += t) divisors[h].push_back(t);
	}
	for(int i = 1; i <= n; i++){
		for(int j : divisors[i]) ways[i] = sub(ways[i], ways[j]);
		// if(n==30)trace(i, ways[i]);
		ans = sub(ans, mul(2 * n - i, ways[i]));
	}
	printf("%d\n", ans);
}

