bool dfs(int v, int k, int nc, int ncid, vector<int>& c, vector<int> &cid) {
  if (c[v] != -1) {
    return c[v] == nc;
  }
  c[v] = nc;
  cid[v] = ncid;
  if (!dfs((v + k) % c.size(), k, nc, ncid, c, cid)) return false;
  return dfs((v + c.size() / 2) % c.size(), k, nc ^ 1, ncid, c, cid);
}

