    mint ans = 0;
    S = X+T;
    vector<mint> cnt(2*N+1,0);
    vector<mint> beki(2*N+1,1);
    vector<int> check(2*N+1,0);
    for(int i=1;i<=2*N;i++) beki[i] = beki[i-1]*2;
    for(int k=1;k<=2*N;k++){
        if(2*N%k!=0) continue;
        if(k%2==1) continue;
        if((2*N/k)%2==0) continue;
        check[k] = true;
//        cerr << k << endl;
        int n = k/2;
        string t = S.substr(0,n);
        string rt = "";
        for(int i=0;i<n;i++){
            if(t[i]=='0') rt += '1';
            else rt += '0';
        }
        //tより小さい部分を数える
        for(int i=n-1;i>=0;i--){
            if(t[i]=='1') cnt[k] += beki[n-1-i];
        }
        //tと同じものが条件を満たすか判定
        string now = "";
        for(int i=0;i<N;i+=k){
            if((i/k)%2==0) now += t;
            else now += rt;
        }
        if(now<=X) cnt[k] += 1;
    }
    for(int i=1;i<=2*N;i++){
        for(int j=2*i;j<=2*N;j+=i){
            if(!check[j]) continue;
            cnt[j] -= cnt[i];
        }
    }
    for(ll k=1;k<=2*N;k++){
        ans += cnt[k]*k;
//        cerr << k << " " << cnt[k].x << endl;
    }
    cout << ans.x << endl;
}

