#ifdef LOCAL
  assert(freopen("c.in", "r", stdin));
#endif
  cin >> n;
  cin >> r;
  reverse(r.begin(), r.end());
  vector<pair<int, int>> res;
  for (int d = 1; d <= 2 * n; ++d) {
    if ((2 * n) % d != 0) {
      continue;
    }
    int cnt = calc(d);
    res.emplace_back(d, cnt);
  }
  for (int i = 0; i < (int) res.size(); ++i) {
    for (int j = i + 1; j < (int) res.size(); ++j) {
      if (res[j].first % res[i].first) {
        continue;
      }
      res[j].second = sub(res[j].second, res[i].second);
    }
  }
  int ans = 0;
  for (auto [d, cnt] : res) {
    udd(ans, mul(d, cnt));
  }
  cout << ans << '\n';
}

