struct UF {
		vi e,d;
			UF(int n) : e(n, -1),d(n,0) {}
				bool same_set(int a, int b) { return find(a) == find(b); }
					int size(int x) { return -e[find(x)]; }
						int find(int x) { if(e[x] < 0) return x;  else {
							int p = e[x] ; int pp = find(e[x]); 
							d[x] = d[p]^d[x];
							e[x] = pp;
							return e[x];
						}
						}
							bool join(int a, int b,int w) {
								int aa = a,bb=b;
										a = find(a), b = find(b);
												if (a==b && d[aa]^w == d[bb]) return true;
												else if(a==b) return false; 
												w=d[aa]^d[bb]^w;
														if (e[a] > e[b]) swap(a, b);
																e[a] += e[b]; e[b] = a;
																d[b] =w;
																return true;
																	}
};
bool fg0[200009],fg1[200009];
int solve(int i){
	fill(fg0);
	fill(fg1);
	g.clear();
	g.resize(n);
	UF dsu(n);
	rep(j,n){
		if(i+j>=n){
			if(!dsu.join(j,(i+j)-n,1)) return 0;
		}
		else if(!dsu.join(j,i+j,0)) return 0;
	}
	int cmp = 0;
	rep(i,n){
		if(dsu.find(i)==i) cmp++;
	}
	ll ans = 0;
	rep(i,n){
		int j = dsu.find(i);
		int w = dsu.d[i];
		if(!fg0[j]&&!fg1[j]) cmp--;
		if(!w&&!fg0[j]&&x[i]=='1') ans+=pw[cmp],fg0[j]=1;
		if(w&&!fg1[j]&&x[i]=='1') ans+=pw[cmp],fg1[j]=1;
		if(!w&&!fg1[j]&&x[i]=='0') fg0[j]=1;
		if(w&&!fg0[j]&&x[i]=='0') fg1[j]=1;
		if(fg0[j]&&fg1[j]) return ans%mod;
	}
	return (ans+1)%mod;
}

