int gojo(int p, int x, int y){
    if(p == 0){
        if(x % y == 0) return -1;
        return gojo(1, y, x % y);
    }else if(p == 1){
        if(x / y % 2){
            if(x % y == 0) return -1;
            return gojo(2, y, x % y);
        }else{
            if(x % y == 0) return y;
            return gojo(0, y, x % y);
        }
    }else{
        if(x / y % 2){
            if(x % y == 0) return -1;
            return gojo(0, y, x % y);
        }else{
            if(x % y == 0) return y;
            return gojo(2, y, x % y);
        }
    }
}

int main(){
    int n;
    string s;
    cin >> n >> s;
    ll ans = 0;
    ll num = 0;
    repl(i, 1, n){
        int k = gojo(0, n, i);
        if(k != -1){
            num = (num + modpow(2, k)) % MOD;
            ans = (ans + i * modpow(2, k)  % MOD) % MOD;
        }
    }
    ans = (ans + 2 * n * (modpow(2, n) - num + MOD) % MOD) % MOD;
    cout << ans << endl;
    return 0;
}

