	if (!num)return s;
	if (num < loop / 2) {
		string ret;
		for (int i = num; i < s.size(); i++)ret.push_back(s[i]);
		for(int i=0;i<num;i++)ret.push_back('1');
		return ret;
	}
	else {
		string ret;
		num -= loop / 2 - 1;
		for (int i = 0; i < num; i++)ret.push_back('1');
		for (int i = 0; i < s.size() - num; i++)ret.push_back(s[i]);
		return ret;
	}
}

long long int lcm(long long int a, long long int b) {
	long long int ret = a * b;
	while (b) {
		a %= b;
		swap(a, b);
	}
	ret /= a;
	return ret;
}

