void chkmax(int *t, int n) {
  int flag = 0; 
  for (int i = 1; i <= n; i++) {
    if (t[i] < mx[i]) return ; 
    if (t[i] > mx[i]) {
      flag = 1; break ; 
    }
  }
  if (flag) {
    for (int i = 1; i <= n; i++) 
      mx[i] = t[i]; 
  }
}

void chkmin(int *t, int n) {
  int flag = 0; 
  for (int i = 1; i <= n; i++) {
    if (t[i] > mn[i]) return ; 
    if (t[i] < mn[i]) {
      flag = 1; break ; 
    }
  }
  if (flag) {
    for (int i = 1; i <= n; i++) {
      mn[i] = t[i]; 
    }
  }
}

int tmp[N]; 

ll calc(int n) {
  int flag = 1; 
  for (int i = 1; i <= n; i++) {
    if (mn[i] < mx[i]) {
      flag = 0; break ; 
    } 
    if (mn[i] > mx[i]) {
      break ; 
    }
  }
  if (!flag) return 0; 
  ll X1 = 0, X2 = 0; ll pw = 1; 
  for (int i = n; i >= 1; i--) 
    X1 += pw * mx[i] % mod, X1 %= mod, pw *= 2, pw %= mod; 
  pw = 1;  
  for (int i = n; i >= 1; i--) 
    X2 += pw * mn[i] % mod, X2 %= mod, pw *= 2, pw %= mod; 
  return ((X2 - X1 + 1) % mod + mod) % mod; 
}

int main() {
  scanf("%d", &n); 
  for (int i = 1; i <= n; i++)
    scanf("%1d", &a[i]);
  for (int i = 1; i <= (n << 1); i++) {
    if ((n << 1) % i != 0 || !(((n << 1) / i) & 1)) 
      continue ; 
    for (int j = 1; j <= i / 2; j++) {
      mx[j] = 0, mn[j] = 1; 
    }
    int T = 0; 
    for (int j = 1; j <= n; j += i / 2) {
      T++; 
      for (int k = 1; k <= i / 2; k++) {
        tmp[k] = a[j + k - 1]; 
        if(T % 2 == 0) tmp[k] ^= 1; 
      }
      if (T % 2 == 0) chkmax(tmp, i / 2); 
      else chkmin(tmp, i / 2); 
    }
    F[i] = calc(i / 2); 
    // printf("%d %lld ",i, F[i]); 
  }
  ll ans = 0; 
  for (int i = 1; i <= 2 * n; i++) {
    if((2 * n % i == 0) && ((2 * n / i) & 1)) {
      ans = (ans + F[i] * i % mod) % mod; 
      for (int j = i + i; j <= 2 * n; j += i) {
        if((2 * n % j == 0) && ((2 * n / j) & 1))
          F[j] = (mod + F[j] - F[i]) % mod; 
      }
    }
  }
  printf("%lld\n", ans); 
  return 0; 
}

