int gcd(int a, int b) { return a ? gcd(b%a,a) : b; }

bool check_col() {
    forn(i,n) if (col[i] != x[i]) return col[i] < x[i]; 
    return true;
}

int main() {
    cin >> n >> x;
    forn(i,n) x[i] -= '0';
    forn(i,n) {
        cum[i+1] = cum[i]*2 + x[i];
        cum[i+1] %= MOD;
    }
    for (int d = 1; d*d <= 2*n; d++) check(d), check(2*n/d);

    for (auto d : div) {
        int rem = gcd(d,n);
        len[d] = cum[rem];
        forn(i,n) col[i] = -1;
        forn(i,rem) {
            int j = i, c = x[i];
            while (col[j] == -1) {
                col[j] = c;
                j += d;
                if (j >= n) {
                    j %= n;
                    c = 1-c;
                }
            }
        }
        add(len[d], check_col());
    }

    for (auto lc : len) {
        int l,c; tie(l,c) = lc;
        for (int l2 = 2*l; l2 <= 2*n; l2 += l) {
            if (len.count(l2)) 
                add(len[l2], MOD - len[l]);
        }
    }

    int ans = 0;
    for (auto xy : len) {
        int x,y; tie(x,y) = xy;
        add(ans, ll(x)*y%MOD);
    }
    cout << ans << endl;
    return 0;
}

