using namespace std;

int n;

constexpr int mod = 998'244'353;
constexpr int N = 300'000;

int f[N];
int comps;

bool ok = false;

int pw2[N];
vector<int> ed[N];
int used[N];
int color[N];
int good[N];
int xr[N];
bool was_m[N];

int my_pow(int x, int k) {
  if (k == 0) {
    return 1;
  }
  int g = my_pow(x, k / 2);
  g = 1ll * g * g % mod;
  if (k & 1) {
    g = 1ll * g * x % mod;
  }
  return g;
}

void go(int v, int t) {
  used[v] = t;
  color[v] = comps;
  for (auto to : ed[v]) {
    if (used[to] == 0) {
      go(to, 3 - t);
    } else if (used[to] != 3 - t) {
      ok = false;
    }
  }
}

int oper(int x) {
  if (x % 2 == 0) {
    return (x / 2) + (1 << (n - 1));
  } else {
    return (x / 2);
  }
}

int main() {
  string s;
  cin >> n;
  cin >> s;
  reverse(s.begin(), s.end());
  vector<int> d;

  pw2[0] = 1;
  for (int i = 1; i <= n; i++) {
    pw2[i] = pw2[i - 1] * 2 % mod;
  }

  for (int i = 1; i <= 2 * n; i++) {
    if ((2 * n) % i == 0) {
      d.push_back(i);
    }
  }

  for (int i = 0; i < d.size(); i++) {
    for (int j = 0; j < i; j++) {
      if (d[i] % d[j] == 0) {
        f[i] += mod - f[j];
        if (f[i] >= mod) {
          f[i] -= mod;
        }
      }
    }

    int k = d[i];
    if (k == 2 * n) {
      f[i]++;
      if (f[i] >= mod) {
        f[i] -= mod;
      }
      for (int it = 0; it < s.size(); it++) {
        f[i] += (s[it] - '0') * my_pow(2, it);
        if (f[i] >= mod) {
          f[i] -= mod;
        }
      }
      continue;
    }
    assert(k <= n);
    for (int it = 0; it < k; it++) {
      ed[it].clear();
      was_m[it] = 0;
      used[it] = 0;
      good[it] = 0;
    }

    for (int it = 0; it < k; it++) {
      ed[it].push_back((n - k + it) % k);
    }

    ok = true;
    comps = 0;
    for (int it = 0; it < k; it++) {
      if (used[it] == 0) {
        go(it, 1);
        comps++;
      }
    }


    if (!ok) {
      continue;
    }

    for (int it = 0; it < k; it++) {
      used[it]--;
    }

    int sz = comps;

    for (int it = n - 1; it >= 0; it--) {
      int v = it % k;
      int bt = s[it] - '0';
      if (was_m[color[v]]) {
        int c = used[v] ^ xr[color[v]];
        if (c < bt) {
          f[i] += pw2[sz];
          if (f[i] >= mod) {
            f[i] -= mod;
          }
          ok = false;
          break;
        }
        if (c > bt && !good[color[v]]) {
          ok = false;
          break;
        }
      } else {
        sz--;
        if (bt == 0) {
          xr[color[v]] = used[v];
        } else {
          xr[color[v]] = (used[v] ^ bt);
          f[i] += pw2[sz];
          if (f[i] >= mod) {
            f[i] -= mod;
          }
        }
        was_m[color[v]] = 1;
      }
    }
    if (ok) {
      f[i]++;
      if (f[i] >= mod) {
        f[i] -= mod;
      }
    }
  }
  int ans = 0;
  for (int i = 0; i < d.size(); i++) {
    ans += 1ll * d[i] * f[i] % mod;
     if (ans >= mod) {
      ans -= mod;
    }

  }

  cout << ans << "\n";
  return 0;
}

