bool dfs(int node, int c, int cid){
	col[node]=c;
	comp[node]=cid;
	for (pii p:G[node]){
		if (comp[p.first] && col[p.first]!=c^p.second) return 0;
		if (!comp[p.first] && !dfs(p.first, p.second^c, cid)) return 0;
	}
	return 1;
}

ll solve(ll k){
	//debug(k)
	for (int i=1; i<=n; i++) G[i].clear();
	if (k<n){
		for (int i=1; i+k<=n; i++){
			G[i].pb({i+k, 0});
			G[i+k].pb({i, 0});
		}
		for (int i=1; i<=k; i++){
			G[i].pb({i+n-k, 1});
			G[i+n-k].pb({i, 1});
		}
	}
	else{
		k-=n;
		for (int i=1; i+k<=n; i++){
			G[i].pb({i+k, 1});
			G[i+k].pb({i, 1});
		}
		for (int i=1; i<=k; i++){
			G[i].pb({i+n-k, 0});
			G[i+n-k].pb({i, 0});
		}
	}
	memset(comp, 0, sizeof(comp));
	//memset(col, 0, sizeof(col));
	int cnt=0;
	for (int i=1; i<=n; i++) if (!comp[i]){
		if (!dfs(i, 0, i)) return 0;
		cnt++;
	}

	for (int i=1; i<=n; i++) C[comp[i]]=-1;
	ll res=0;
	for (int i=1; i<=n; i++){
		if (X[i] && (C[comp[i]]==-1 || C[comp[i]]==col[i])){
			res+=tav[cnt-(C[comp[i]]==-1)];
		}
		if (C[comp[i]]==-1) C[comp[i]]=X[i]^col[i], cnt--;
		else if (C[comp[i]]!=col[i]^X[i]) return res;
	}
	res++;
	return res%mod;
}

