mint convert(const string &s){
  mint ret = 0;

  for(auto c : s){
    ret *= 2;
    ret += (int)(c-'0');
  }

  return ret;
}

string flip(string s){
  for(auto &c : s){
    if(c == '0') c = '1';
    else c = '0';
  }

  return s;
}


vector<bool> eratosthenes_sieve(int n){
  vector<bool> res(n+1, true);
  res[0] = res[1] = false;
  FOR(i,2,n) if(res[i]) for(int j=2*i; j<=n; j+=i) res[j] = false;
  return res;
}

auto is_prime = eratosthenes_sieve(1000000);



vector<int> mobius(int n){
  vector<int> ret(n+1);
  vector<int> ps;
  ret[1] = 1;
  FORE(i,2,n){
    if(is_prime[i]){
      ps.push_back(i);
      ret[i] = -1;
    }
    for(auto &j : ps){
      if(i*j > n) break;
      if(i%j == 0) ret[i*j] = 0;
      else ret[i*j] = ret[i] * ret[j];
    }
  }

  return ret;
}



