  rep(ii, ds.size()) {
    int d = ds[ii];
    if (d == N || N / d % 2 == 0) continue;
    static mint dp[200001][3][3];
    rep(i, d + 1) rep(j, 3) rep(k, 3) dp[i][j][k] = 0;
    dp[0][EQ][EQ] = 1;
    rep(i, d) rep(j, 3) rep(k, 3) rep(x, 2) {
      int u = X[i] - '0';
      int v = X[i + d] - '0';
      int y = x ^ 1;
      int nj = then(j, cmp(x, u));
      int nk = then(k, cmp(y, v));
      dp[i + 1][nj][nk] += dp[i][j][k];
    }
    bool bad = false;
    rep(i, N) {
      if (X[i] > X[i % (d * 2)]) {
        break;
      }
      if (X[i] < X[i % (d * 2)]) {
        bad = true;
        break;
      }
    }
    rep(i, 3) rep(j, 3) {
      if (then(i, j) == LT) {
        ans[ii] += dp[d][i][j];
      } else if (then(i, j) == EQ && !bad) {
        ans[ii] += dp[d][i][j];
      }
    }
  }
  rep(i, N) ans[ds.size() - 1] = ans[ds.size() - 1] * 2 + (X[i] - '0');
  ans[ds.size() - 1] += 1;
  rep(i, ds.size()) {
    rep2(j, i + 1, ds.size()) if (ds[j] % ds[i] == 0) {
      ans[j] -= ans[i];
    }
  }
  mint out = 0;
  rep(i, ds.size())  {
    out += ds[i] * 2 * ans[i];
  }
  cout << out << endl;
}

