ll solve(string X){
	int n = X.size();

	for(int i=1;i<=n;++i) divs[i].clear();
	for(int i=1;i<=n;++i) for(int j=i;j<=n;j+=i) if((j/i)%2==1 && n%j==0) divs[j].push_back(i);

	vector<int> p2(n+1);
	for(int i=p2[0]=1; i<=n; ++i) p2[i]=p2[i-1]*2 %mod;

	vector<int> F(n+1);

	ll ans = 0;

	vector<int> h(n+1);
	for(int k : divs[n]){
		bool ok = true;
		for(int i=0;i<n;++i){
			ok&= X[i] == (X[i%k]^(i/k%2));
			if(!ok){
				h[k] = i;
				break;
			}
		}
		if(ok) h[k] = n;
	}

