                tmp++;
                tmp-=vis;
                for(int k=1;k<=cnt;k++)if(j%Div[k]==0)tmp-=t[Div[k]];
                ans-=2*tmp*(n-j)%mod;
            }
            if(i==j)break;
            if(j&1)
            {
                bool vis=0,flag=0;
                LL tmp=0;
                for(int k=0;k<n;k++)
                {
                    if(k<i)
                    {
