long long calc(int c) {
    int i, j;
    long long ans = 0;

    for (i = 0; i < c; i++) {
        ans *= 2;
        if (ans >= mod) ans -= mod;

        if (s[i] == '1') {
            ans++;
            if (ans >= mod) ans -= mod;
        }
    }

    for (i = 0; i < n / c; i++) {
        for (j = 0; j < c; j++) {
            int x, y;

            if (i % 2 == 0) {
                x = s[i * c + j] - '0';
                y = s[j] - '0';
            } else {
                x = s[i * c + j] - '0';
                y = 1 - (s[j] - '0');
            }

            if (x > y) {
                return ans + 1;
            } else if (x < y) {
                return ans;
            }
        }
    }

    return ans + 1;
}

