    x2 %= mod;
  }
  long long res = ((x2 + 1) * 2 * n) % mod;
  for (int i = 1; i < n; i++) {
    if (n % i == 0 && (n / i) % 2 == 1) {
      cnt_pat_num(i);
      // cout << i << ": subtracting " << (cnt[i] * 2 * (n - i)) << endl;
      res -= (cnt[i] * 2 * (n - i)) % mod;
      if (res < 0) res += mod;
