using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

vector<UL> Divs(UL a, UL p = 2) {
	if (a == 1) return { 1 };
	for (; a % p != 0; p++) if (p * p > a) return { 1, a };
	UL n = 1;
	for (; a % p == 0; n++) a /= p;
	vector<UL> buf = Divs(a, p + 1 | 1);
	UL i = buf.size(), l = buf.size();
	buf.resize(i * n);
	for (; i < buf.size(); i++) buf[i] = buf[i - l] * p;
	return buf;
}

const ULL M = 998244353;

ULL F(const string& a, UL s) {
	bool less = false;
	for (UL i = 0; i < a.size() - s; i++) {
		if (a[i] != a[i + s]) continue;
		less = a[i] == '0';
		break;
	}
	ULL tmp = 0;
	rep(i, s) {
		tmp <<= 1;
		tmp += a[i] - '0';
		if (tmp >= M) tmp -= M;
	}
	if (!less) tmp = (tmp + 1) % M;
	return tmp;
}

struct Problem {

	void Solve() {
		UL N; cin >> N;
		vector<UL> D = Divs(N);
		sort(D.begin(), D.end());
		string S; cin >> S;
		rep(i, N) S.push_back('0' + '1' - S[i]);

		vector<ULL> V(D.size());
		rep(i, D.size()) {
			UL d = D[i];
			if (N / d % 2 == 0) continue;
			ULL f = F(S, d);
			V[i] += f;
			V[i] %= M;
			for (UL j = i + 1; j < D.size(); j++) {
				if (D[j] % d == 0) {
					V[j] += (M - V[i]);
				}
			}
		}
		ULL ans = 0;
		rep(i, D.size()) {
			ans += (ULL)D[i] * V[i];
			ans %= M;
		}
		ans = ans * 2 % M;
		cout << ans << endl;
	}

	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

