std::istream& operator>> (istream &stream, llm &m) {
    long long tmp;
    stream >> tmp;
    m.l = tmp % mod;
    return stream;
}

bool g(deque<bool> x, deque<bool> y, int N){
    bool flag = true;
    for(int i = N - 1; i >= 0; --i){
        if (x[i]) {
            if(y[i]){
                continue;
            } else {
                flag = false;
                break;
            }
        } else {
            if (y[i]) {
                break;
            } else {
                continue;
            }
        }
    }
    return flag;
}

