template <typename T>
vector<T> prime_facs(T N){
    vector<T> ans;
    for(int i = 2; i*i <= N; i++){
        if(N%i == 0){
            ans.push_back(i);
            while(N%i == 0){
                N /= i;
            }
        }
    }
    if(N != 1) ans.push_back(N);
    return ans;
}

long pow[200001];

void init(){
    pow[0] = 1;
    for(int i = 1; i <= 200000; i++){
        pow[i] = pow[i-1]*2;
        pow[i] %= MOD;
    }
}

long count(int n){
    long ans = 1;
    int m = N/n;
    string pref;
    string pref1;
    for(int i = 0; i < n; i++){
        if(X[i] == '0'){
            pref += '0';
            pref1 += '1';
        }else{
            pref += '1';
            pref1 += '0';
            ans += pow[n-1-i];
            ans %= MOD;
        }
    }
    string cmp;
    for(int i = 0; i < m; i++){
        if(i%2 == 0) cmp += pref;
        else cmp += pref1;
    }
    if(cmp > X) ans--;
    return ans;
}

