    for ( ; x*x < n; x++) if (n % x == 0) a.push_back(x), b.push_back(n/x);
    if (x*x == n) a.push_back(x);
    a.reserve(a.size()+b.size());
    copy(b.rbegin(), b.rend(), back_inserter(a));
    return a;
}

