#include"bits/stdc++.h"
using namespace std;
using ll = int64_t;

constexpr ll MOD = 998244353;

ll MODpow(ll n, ll m) {
    ll result = 1;
    while (m) {
        if (m % 2 == 1) {
            result *= n;
            result %= MOD;
        }

        m /= 2;
        n *= n;
        n %= MOD;
    }

    return result;
}

int main() {
    ll N;
    string X;
    cin >> N >> X;

    bool all1 = true;
    for (ll i = 0; i < N; i++) {
        if (X[i] != '1') {
            all1 = false;
        }
    }

    assert(all1);

    map<ll, ll> n;
    ll ans = 0;
    for (ll bit = 1; bit <= N; bit++) {
        if (N % bit != 0) {
            continue;
        }
        if ((N / bit) % 2 == 0) {
            continue;
        }

        //bit * 2回操作すると戻るような数字が2^bit個ありえる
        //ただしbitの約数個はすでに数えているので引く
        ll num = MODpow(2, bit);
        for (ll i = 1; i * i <= bit; i++) {
            if (bit % i == 0) {
                if (i * i == bit) {
                    num = (num + MOD - n[i]) % MOD;
                } else {
                    num = (num + MOD - n[i]) % MOD;
                    num = (num + MOD - n[bit / i]) % MOD;
                }
            }
        }

        n[bit] = num;

        (ans += num * (bit * 2) % MOD) %= MOD;
    }
    cout << ans << endl;
}

