#include <bits/stdc++.h>

const int XN=4e5+11,P=998244353;

void M(int &x) {
    ((x>=P) && (x-=P)) || ((x<0) && (x+=P));
}

int main() {
    std::ios::sync_with_stdio(0);
    std::cin.tie(0);
    //freopen("input","r",stdin);
    static char x[XN];
    int n;std::cin>>n>>(x+1);
    auto IsValid=[&](int i)->bool {
        return 2*n%i==0 && (2*n/i)%2==1;
    };
    static int f[XN],sum[XN];
    for(int i=1;i<=n;++i)
        M(sum[i]=sum[i-1]*2LL+x[i]-'0');
    for(int i=1;i<=2*n;++i) {
        if(IsValid(i)) {
            assert(i%2==0);
            f[i]=sum[i/2];
            bool tak=1;
            if(i!=2*n) {
                assert(i<=n);
                std::string s(x+1,x+1+i/2);
                for(int j=0;j<i/2;++j)
                    s+=s[j]^1;
                if(s>std::string(x+1,x+1+i))
                    tak=0;
            }
            M(f[i]+=tak);
        }
    }
    for(int i=1;i<=2*n;++i)
        if(IsValid(i))
            for(int j=2;i*j<=2*n;++j)
                if(IsValid(i*j))
                    M(f[i*j]-=f[i]);
    int Ans=0;
    for(int i=1;i<=2*n;++i)
        if(IsValid(i))
            M(Ans+=1LL*i*f[i]%P);

    int gs=0;
    for(int i=1;i<=2*n;++i)
        M(gs+=f[i]);
    assert(sum[n]==gs);
    std::cout<<Ans<<'\n';
    return 0;
}

