    for (int i=0;i<interesting.size();i++){
    	ans=(ans-(n*2)*count_with[i]+2*interesting[i]*count_with[i]);
    	ans%=bs;
    	if (ans<0)
    		ans+=bs;
    }

    cout<<ans<<endl;

//    cin.get(); cin.get();
    return 0;
}

