	//ループ有					:O(V^2)	※未検証
	//ループ有(負の閉路)		:ダイクストラは適用外
	void dijkstraOLD(int posStart) {
		val(posStart).dis = 0;
		//
		bfs(posStart, [&](int now, int next, int w) {
			if (val(next).dis > val(now).dis + w) {
				val(next).dis = val(now).dis + w;
				return true;
			}
			return false;
			});
