using mll = map<ll, ll>;
// 素因数分解O(sqrt(n))
mll prime_factor(ll n){
    mll res;
    for(ll i = 2; i * i <= n; i++){
        while(n % i == 0){
            ++res[i];
            n /= i;
        }
    }
    if(n != 1) res[n] = 1;
    return res;
}
// 約数の列挙O(sqrt(n))
vll divisor(ll n){
    vll res;
    for(ll i = 1; i * i <= n; i++){
        if(n % i == 0){
            res.emplace_back(i);
            if(i * i != n) res.emplace_back(n / i);
        }
    }
    sort(ALL(res));
    return res;
}

