int pw(int n,int k){
  int res=1;
  while(k){
    if(k&1)res*=n;res%=MOD;
    n*=n;n%=MOD;
    k>>=1;
  }
  return res;
}

int f(int a){//長さaのループがX以下に何種類存在するか
  int res=0;
  for(int i=0;i<a;i++) if(x[i]=='1') res+=pw(2,a-i-1),res%=MOD;//桁DPっぽいところ
  //最初a文字がXと完全に一致しているやつがx以下かどうかの判定
  string s,A=x.substr(0,a);
  while(s.size()<N)s+=A;
  for(int i=0;i<s.size();i++) if((i/a)&1) s[i]=(s[i]^'1')+'0';
  //sがx以下かどうか判定する
  for(int i=a;i<N;i++){
    if(x[i]^s[i]) {res+=s[i]^'1';break;}
    res+=(i==N-1);
  }
  return res+(a==N);
}

