	map<int,mint> dcnt;
	for (int i=0;i<vd.size();i++) {
		int d=vd[i];
		if (p-1<=repmax[i] && (p-d<0||s[p]!=s[p-d])) {
			int fr=0;
			if (p+1<d) {
				fr=d-p-1;
			}
			dcnt[i]=p2[fr];
		}
	}
	mint ans=0;
	for (int o=0;o<vd.size();o++) {
		int od=vd[o];
		mint onlycnt=dcnt[o];
		for (int i=0;i<o;i++) {
			int id=vd[i];
			if (od%id==0) {
				int mo=mu[od/id];
				if (mo==1) onlycnt+=dcnt[i];
				else if (mo==-1) onlycnt-=dcnt[i];
			}
		}
		int orbit = 2*od;
		ans+=onlycnt*orbit;
	}
	return ans;
}

