            Div.emplace(n);
            Div.emplace(N/n);
        }
    }

    ll Res = 0;
    map<int, ll> mapDivToNum;
    for (int d : Div) {
        int Rep = N/d;
        if (Rep%2 == 0) continue;
        int Score = 2 * d;

        ll Temp = 0;
        for (int i = 0; i < d; ++i) {
            (Temp *= 2) %= MOD;
            if (X[i] == '1') (Temp += 1) %= MOD;
        }
