        for (int r = 0; r < Rep; ++r) {
            if (r % 2 == 0) {
                Y += A;
            } else {
                Y += B;
            }
        }
        if (Y <= X) {
            (Temp += 1) %= MOD;
        }

        (Temp += mapDivToNum[d]) %= MOD;

        for (int d2 : Div) {
            if (d2 % d == 0) {
                mapDivToNum[d2] -= Temp;
            }
        }

        Res = (Res + Score * Temp) % MOD;
    }

