    for (int len = 1; len <= n; ++len) {
        if (n % len)
            continue;
        if (((n / len) & 1) == 0)
            continue;
        int eq = 1;
        int B = n / len;
        vvi dp(B, {0, 0});
        for (int i = 0; i < len; ++i) {
            int neq = 0;
            vvi ndp(B, {0, 0});
            for (int item = 0; item < 2; ++item) {
                int cur = item;
                bool les = false;
                int id = -1;
                for (int j = i; j < n; j += len, cur ^= 1) {
                    if (cur < x[j]) {
                        les = true;
                        id = j / len;
                    } else if (cur > x[j]) {
                        id = j / len;
                        les = false;
                    } else {
                        continue;
                    }
                    break;
                }
                if (id == -1) {
                    insum(neq, eq);
                    fori (j, B) {
                        fori (z, 2) {
                            insum(ndp[j][z], dp[j][z]);
                        }
                    }
                } else {
                    int toz = les ? 0 : 1;
                    insum(ndp[id][toz], eq);
                    fori (j, B) {
                        fori (z, 2) {
                            if (id < j) {
                                insum(ndp[id][toz], dp[j][z]);
                            } else {
                                insum(ndp[j][z], dp[j][z]);
                            }
                        }
                    }
                }
            }
            eq = neq;
            dp = ndp;
        }

        fori (j, B) {
            insum(cnt[len], dp[j][0]);
        }
        insum(cnt[len], eq);
        for (int j = 2; j * len <= n; ++j) {
            insum(cnt[j * len], M - cnt[len]);
        }
        insum(ans, 2LL * cnt[len] * len % M);
    }
    cout << ans;
}

