  bitset<400000> bs(t);
  vecll p2(n2+1);
  p2[0] = 1;
  for(ll i:irange(1l,n2+1)) {
    p2[i] = 2 * p2[i-1];
    p2[i] %= MOD;
  }
  map<ll,ll> dp;
  dp[1] = 0;
  vecll divs;
  for(ll d:irange(2l,n)) {
    if ((n2%d) != 0) continue;
    if ((d%2) != 0) continue;
    if ((n%d) == 0) continue;
    ll dh = d/2;
    ll sum = 0;
    ll mx = n;
    ll mn = n;
    vecll tmp(d+1, n);
    vecll tmp2(d+1, n);
    for (ll i:irange(0l,n)) {
      if (!bs.test(i)) {
        tmp[i%d] = min(tmp[i%d], i);
      } else {
        tmp2[i%d] = min(tmp2[i%d], i);
      }
    }
    for (ll i:irange(0l,dh)) {
      if (s[i] == '1') {
        sum += p2[dh-i-1];
        sum %= MOD;
        mx = min(mx, tmp[i]);
        mn = min(mn, tmp2[i+dh]);
      } else {
        mx = min(mx, tmp[i+dh]);
        mn = min(mn, tmp2[i]);
      }
    }
    if (mx >= mn) {
      ++sum;
      sum %= MOD;
    }
    ll sub = 0;
    for (ll e:divs) {
      if ((e%2) != 0) continue;
      ll eh = e/2;
      if ((dh%eh) != 0) continue;
      ll div = dh/eh;
      if ((div%2) != 0) {
        sub += dp[e];
        sub %= MOD;
      }
    }
    dp[d] = (MOD + sum - sub) % MOD;
    divs.push_back(d);
  }
  ll sum = 1;
  for (ll i:irange(0l,n)) {
    if (s[i] == '1') {
      sum += p2[n-i-1];
      sum %= MOD;
    }
  }
  ll sub = 0;
  for (ll e:divs) {
    if ((e%2) != 0) continue;
    ll eh = e/2;
    if (e >= n) continue;
    if ((n%eh) != 0) continue;
    ll div = n/eh;
    if ((div%2) != 0) {
      sub += dp[e];
      sub %= MOD;
    }
  }
  dp[n2] = (MOD + sum - sub) % MOD;
  ll ans = 0;
  for(auto& p : dp) {
    ans += p.second * p.first;
    ans %= MOD;
  }
  cout<<ans<<endl;
  return 0;
}

