            for (int c = 0; c <= 1; ++c) {
                if (f == 1 || c <= s[i] - '0') {
                    dp[i][f | (c < s[i] - '0')] += dp[i - 1][f];
                    if (dp[i][f | (c < s[i] - '0')] >= mod) {
                        dp[i][f | (c < s[i] - '0')] -= mod;
                    }
                }
            }
        }
    }
    for (int len = 1; len <= n; ++len) {
        if (n % len != 0 || (n / len) % 2 == 0) {
            res[len] = 0;
            continue;
        }
        res[len] = dp[len - 1][1];
        bool f = true;
        for (int i = len; i < n; i += len) {
            int t = i / len;
            if (t % 2 == 0) {
                if (z[n + 1 + i] >= len) {
                    continue;
                }
                else {
                    if (s[i + z[n + 1 + i]] < s[z[n + 1 + i]]) {
                        f = false;
                    }
                    break;
                }
            }
            else {
                if (zi[n + 1 + i] >= len) {
                    continue;
                }
                else {
                    if (s[i + zi[n + 1 + i]] == s[zi[n + 1 + i]] && s[zi[n + 1 + i]] == '0') {
                        f = false;
                    }
                    break;
                }
            }
        }
        //cerr << len << ' ' << f << '\n';
        res[len] += f;
        if (res[len] >= mod) {
            res[len] -= mod;
        }
    }
    ll ans = 0;
    for (int len = 1; len <= n; ++len) {
        if (n % len != 0 || (n / len) % 2 == 0) {
            continue;
        }
        for (int d = 2; d * d <= len; ++d) {
            if (len % d == 0) {
                if (d % 2 == 1) {
                    res[len] -= res[len / d];
                    if (res[len] < 0) {
                        res[len] += mod;
                    }
                }
                if ((len / d) % 2 == 1) {
                    res[len] -= res[d];
                    if (res[len] < 0) {
                        res[len] += mod;
                    }
                }
            }
        }
        if (len != 1 && len % 2 == 1) {
            res[len] -= res[1];
            if (res[len] < 0) {
                res[len] += mod;
            }
        }
        ans = (ans + res[len] * 2 * len) % mod;
    }
    cout << ans << '\n';
}

