const int mod = 998244353;

void add(li& x, li y) {
    x += y;
    if (x >= mod)
        x -= mod;
}

const int maxn = 4e5 + 555;

li c[maxn], a[maxn];
vector <li> b;
vector <int> g[maxn];
li ans[maxn], pw2[maxn];
int n;
li res;

void solve1(int x, int i) {
    if (i == n) {
        add(res, 1);
        return;
    }
    if (i >= x) {
        int need = c[i % x] ^ ((i / x) & 1);
        if (a[i] == need)
            solve1(x, i + 1);
        else if (a[i] > need)
            add(res, 1);
        return;
    }
    if (a[i] == 1) {
        int len = (x - i - 1);
        add(res, pw2[len]);
    }
    c[i] = a[i];
    solve1(x, i + 1);
}

li solve1(int x) {
    res = 0;
    solve1(x, 0);

    return res;
}

void solve(bool __attribute__((unused)) read) {
    cin >> n;
    pw2[0] = 1;
    for (int i = 1; i <= n; ++i) {
        pw2[i] = pw2[i - 1] * 2ll % mod;
    }
    string s;
    cin >> s;
    for (int i = 0; i < n; ++i) {
        a[i] = (s[i] - '0');
    }
    for (int x = 1; x <= n; ++x) {
        if (n % x == 0 && (n % (2 * x)) != 0) {
            b.push_back(x);
        }
    }
    for (int i = 0; i < (int)b.size(); ++i) {
        g[i].clear();
        for (int j = i + 1; j < (int)b.size(); ++j) {
            if (b[j] % b[i] == 0) {
                g[i].push_back(j);
            }
        }
    }
    memset(ans, 0, sizeof ans);
    li sumans = 0;
    for (int i = 0; i < (int)b.size(); ++i) {
        ans[i] += solve1(b[i]);
        ans[i] = (ans[i] % mod + mod) % mod;
        for (int j : g[i]) {
            ans[j] -= ans[i];
        }
        // cout << b[i] << " " << ans[i] << endl;
        sumans = (sumans + ans[i] * 2ll * b[i]) % mod;
    }
    cout << sumans << endl;

}

#include <bits/stdc++.h>
using namespace std;
const int BASE = 998244353;

int n;
string s;
map<int, int> m;

long long solve(int len)
{
  long long v = 0;
  for (int i = 0; i < len; i++)
    v = (v * 2 + s[i] - '0') % BASE;

  int isGood = 1;
  for (int i = len; i < n; i++)
  {
    int x = s[i % len] - '0';
    if (i / len % 2)
      x ^= 1;
    if (x == s[i] - '0')
      continue;
    if (x > s[i] - '0')
      isGood = 0;
    break;
  }

  v = (v + isGood) % BASE;
  long long res = 0;
  for (auto u : m)
    if (len % u.first == 0)
      v = (v - u.second + BASE) % BASE;

  m[len] = v;
  res = (res + 2LL * v * len) % BASE;
  return res;
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  cin >> n >> s;
  long long ans = 0;
  for (int i = 1; i <= n; i++)
    if (n % i == 0 && n / i % 2)
      ans = (ans + solve(i)) % BASE;
  cout << ans << endl;
}

