vector<ll> divisor(ll n) {
  vector<ll> res;
  for (ll i = 1; i*i <= n; ++i) {
    if (n%i != 0) continue;
    res.push_back(i);
    if (i*i != n) res.push_back(n/i);
  }
  sort(res.begin(), res.end());
  return res;
}


mint num(string s) {
  int n = sz(s);
  mint res = 0;
  mint pw = 1;
  drep(i, n) {
    if (s[i] == '1') res += pw;
    pw *= 2;
  }
  return res;
}

string rev(string s) {
  rep(i, sz(s)) s[i] = '0' + ((s[i] - '0')^1);
  return s;
}


