int main() {
    constexpr i64 mod = 998244353;
    int n;
    std::string s;
    std::cin >> n >> s;

    i64 c = 0, ret = 0;
    std::vector<std::pair<int, i64>> memo;
    for (int i = 0; i < n; i++) {
        c = (c * 2 + (s[i] == '1')) % mod;

        int d = i + 1;
        if (n % d || n / d % 2 == 0) continue;

        i64 overlap = 0;
        for (auto &e : memo) if (d % e.first == 0 && d / e.first % 2) overlap = (overlap + e.second) % mod;

        int flg = 1;
        for (int j = 0; j < n; j++) {
            int k = j / d % 2 ? '0' + '1' - s[j % d] : s[j % d];
            if (s[j] == k) continue;
            flg = k < s[j];
            break;
        }

        i64 count = (c + flg + mod - overlap) % mod;
        memo.emplace_back(d, count);
        ret = (ret + count * d % mod * 2 % mod) % mod;
    }

    std::cout << ret << std::endl;

    return 0;
}

