	cin >> n >> x;
	mint ans(0);
	mint sum(0);
	foreach(i, x){
		sum *= mint(2);
		if(i=='1'){
			sum += mint(1);
		}
	}
	sum += mint(1);
	//dp[i][j] j==1 上限 j==0 それ以外
	dp.resize(n, vector<mint>(2, mint(0)));
	if(x[0]=='1'){
		dp[0][1] = mint(1);
		dp[0][0] = mint(1);
	}else{
		dp[0][1] = mint(1);
	}
	rep(i, n-1){
		dp[i+1][0] += dp[i][0] * mint(2);
		if(x[i]=='1'){
			dp[i+1][1] += dp[i][1];
			dp[i+1][0] += dp[i][1];
		}else{
			dp[i+1][1] += dp[i][1];
		}
	}
	auto can = [&](int len){
		string str = x.substr(0, len);
		string str2;
		str2 = str;
		string res = "";
		foreach(i, str2){
			i = (i=='1')?'0':'1';
		}
		rep(i, n){
			if((i/len)&1){
				res += str2[i%len];
			}else{
				res += str[i%len];
			}
		}
		int ans = 0;
		ans += (res <= x)?1:0;
		ans += (res == x)?2:0;
		return ans;
	};

	auto getrev = [&](string in){
		string res="";
		foreach(i, in)res += (i=='1')?'0':'1';
		return res;
	};

	repa(i, n/2+1){
		if(n%i==0){
			if((n/i)%2==0)continue;
			for(int j=i*2;j<n;j+=i){
				dp[j-1][0] -= dp[i-1][0];
			}
			sum -= dp[i-1][0];
			ans += mint(i*2) * dp[i-1][0];
			string strs = x.substr(0, i);
			string add = x.substr(0, i);
			if(can(i)){
				for(int j=i*2;j<n;j+=i){
					add = getrev(add);
					strs += add;
					if(x.substr(0, j)==strs){
						dp[j-1][1] -= dp[i-1][1];
					}else{
						dp[j-1][0] -= dp[i-1][1];
					}
				}
				sum -= dp[i][1];
				ans += mint(i*2) * dp[i-1][1];
			}
		}
	}
	cout << ans << endl;
	cout << sum << endl;

	ans += sum * mint(n * 2);
