void dfs(int v, int c, int fst) {
	used[v] = mark;
	color[v] = c;
	which_cc[v] = fst;

	if(v < n)
		cc[fst].push_back(v);

	for(auto& u: g[v]) {
		if(used[u] != mark) {
			dfs(u, c ^ 1, fst);
		} else {
			if(color[v] == color[u])
				bi = 0;
		}
	}
}

int count[MAX_PERIOD];
int pow2[MAX_PERIOD];

void precalc() {
	pow2[0] = 1;

	for(int i = 1; i < MAX_PERIOD; ++i) {
		pow2[i] = add(pow2[i - 1], pow2[i - 1]);
	}
}

int deque[MAX_V];
int l, r;

void deque_push_front(int value) {
	int p = --l;

	if(p < 0)
		p += MAX_V;

	deque[p] = value;

	if(l < 0)
		l += MAX_V;
}

int deque_pop_back() {
	int p = --r;

	if(p < 0)
		p += MAX_V;

	int rez = deque[p];

	if(r < 0)
		r += MAX_V;

	return rez;
}

int deque_get(int i) {
	int pos = l + i;

	if(pos >= MAX_V)
		pos -= MAX_V;

	return deque[pos];
}

void solve() {
	cin >> n >> x;
	vector<int> divs;

	for(int i = 1; i <= 2 * n; ++i) {
		if((2 * n) % i == 0)
			divs.push_back(i);
	}

	int answ = 0;

	for(auto& cycle_size: divs) {
		last = n;

		for(int v = 0; v < 2 * n + 7; ++v) {
			g[v].clear();
			cc[v].clear();
			touched[v] = 0;
		}

		l = r = 0;

		for(int i = n - 1; i >= 0; --i) {
			deque_push_front(i + 1);
		}

		for(int i = 0; i < cycle_size; ++i) {
			int lst = deque_pop_back();
			deque_push_front(-lst);
		}

		for(int i = 0; i < n; ++i) {
			int j = deque_get(i);

			if(j > 0) {
				equal(i, j - 1);
			} else {
				nonequal(i, -j - 1);
			}
		}

		bi = 1;
		++mark;

		int fst = 0;

		for(int v = 0; v < last; ++v) {
			if(used[v] != mark) {
				dfs(v, 0, fst);
				++fst;
			}
		}

		if(bi == 0)
			continue;

		//DBG(cycle_size); DBG(fst);
		int cur = fst;
		int fl = 1;

		for(int i = 0; i < n; ++i) {
			int value = x[i] - '0';

			if(touched[which_cc[i]] == 0) {
				--cur;
				touched[which_cc[i]] = 1;

				if(value == 1)
					count[cycle_size] = add(count[cycle_size], pow2[cur]);

				if(color[i] != value) {
					for(auto& j: cc[which_cc[i]]) {
						color[j] ^= 1;
					}
				}
			} else {
				if(color[i] > value) {
					fl = 0;
					break;
				} else if(color[i] < value) {
					count[cycle_size] = add(count[cycle_size], pow2[cur]);
					fl = 0;
					break;
				}
			}
		}

		count[cycle_size] = add(count[cycle_size], fl);
		//DBG(count[cycle_size]);
	}

	//DBG("----");

	for(auto& i: divs) {
		for(auto& j: divs) {
			if(i % j != 0 || j == i)
				continue;

			count[i] = sub(count[i], count[j]);
		}
	}

	/*for(int cycle_size = 1; cycle_size <= 2 * n; ++cycle_size) {
		DBG(cycle_size); DBG(count[cycle_size]);
	}*/

	for(int i = 1; i <= 2 * n; ++i) {
		answ = add(answ, mult(count[i], i));
	}

	cout << answ << '\n';
}

int main() {
	init_IO();

	//stupid::print();
	precalc();
	solve();

	return 0;
}

