template<int MOD>
struct ModInt {
  int x;
  constexpr ModInt() : x(0) {}
  ModInt(ll s) { if ((x = s % MOD) < 0) x += MOD; }
  ModInt operator+=(ModInt rhs) { if ((x+=rhs.x) >= MOD) x -= MOD; return *this; }
  ModInt operator-=(ModInt rhs) { if ((x-=rhs.x) < 0) x += MOD; return *this; }
  ModInt operator*=(ModInt rhs) { x = (ll)x*rhs.x % MOD; return *this; }
  ModInt operator+(ModInt rhs) const { return ModInt(*this) += rhs; }
  ModInt operator-(ModInt rhs) const { return ModInt(*this) -= rhs; }
  ModInt operator*(ModInt rhs) const { return ModInt(*this) *= rhs; }
  ModInt operator/=(ModInt rhs) {
    static const ll inv2 = ModInt(2).inv().x; // 2で割るのは特別に保存してみる
    ll i = (rhs.x == 2 ? inv2 : rhs.inv().x);
    x = x*i%MOD; return *this;
  }
  ModInt operator/(ModInt rhs) const { return ModInt(*this) /= rhs; }
  ModInt inv() { return pow(MOD-2); }
  ModInt pow(ll n) const {
    ModInt r = 1, t = x;
    for (;n;n>>=1,t*=t) if (n&1) r *= t;
    return r;
  }
  static ModInt strnum(const string &n) {ModInt a = 0; for (char c:n) a = a*10+c-'0'; return a;}
  friend ostream& operator<<(ostream &os, const ModInt rhs){ return os << rhs.x; }
};
typedef ModInt<998244353> mint;

vector<ll> factors(ll n) {
  vector<ll> res;
  for (ll x=1; x*x<=n; ++x) {
    if (n%x==0) {
      res.push_back(x);
      if (n/x != x) res.push_back(n/x);
    }
  }
  // if(n>1) res.push_back(n);
  return res;
}

int main() {
  int n;
  string s;
  while(cin>>n>>s) {
    auto divs = factors(n);
    sort(ALL(divs), greater<ll>());
    // cout << divs << endl;
    map<int, mint> mp;
    mint ans = 0;
    FOR(it, divs) {
      int d = *it;
      if (d % 2 == 0) continue;
      int w = n/d;
      int ok = 0;
      int ng = 0;
      for (int i=1; i<d; i++) {
        REP(j,w) {
          int a = s[j]-'0';
          int b = s[w*i+j]-'0';

          if (i%2) {
            a = !a;
          }
          if (a<b) {
            ok = 1;
            break;
          } else if (a>b) {
            ng = 1;
          }
        }
        if (ok||ng) break;
      }
      mint c = 0;
      REP(i,w) {
        c *= 2;
        c += s[i]-'0';
      }
      c += 1;
      if (ng) c -= 1;
      mp[d] = c;
      int t = d;
      while (t<=n) {
        t += d;
        if (mp.count(t)) {
          c -= mp[t];
        }
      }
      mp[d] = c;
      // cout << d << " " << c << " " << w << endl;
      ans += c * w * 2;
      // cout << d << endl;
    }
    cout << ans << endl;
  }
}

