	cin.tie(NULL);
	cin>>N>>str;
	beki2[0]=1;
	for(int i=1;i<=N;i++){
		beki2[i]=2ll*beki2[i-1]%MOD;
	}
	//周期は奇数*2^ord2(N)*2のみがある。
	//N/奇数*2^ord2(N) が奇数　これを動かす。
	//周期がLで割り切れるものの個数をdp[L]に計算する。
	for(int k=1;k<=N;k+=2){
		if(N%k==0){
			ll L=N/k;//これの2倍が周期
			bool flag=1;
			for(int i=0;i<N;i++){
				if(str[i]=='1'&&(i<L||str[i-L]=='1')){
					if(i<L)dp[L]+=beki2[L-i-1];
					else dp[L]+=1;
					dp[L]%=MOD;
				}
				if(i>=L&&str[i]==str[i-L]){
					flag=0;
					break;
				}
			}
			if(flag)dp[L]=(dp[L]+1)%MOD;//
		}

	}
	ll ans=0;
	//包徐で整理。
	for(int i=1;i<=N;i++)if(N%i==0&&N/i%2==1&&dp[i]!=0){
		ans=(ans+(ll)2*dp[i]*i);//周期2iをその個数足す。
		ans%=MOD;
		for(int k=2;k<=N/i;k++){
			dp[k*i]=(dp[k*i]-dp[i]+MOD)%MOD;
		}
	}
	cout<<ans<<endl;
}

