const int mod = 998244353;
template<typename T>
T add(T x) {
  return x;
}
template<typename T, typename... Ts>
T add(T x, Ts... y) {
  T res = x + add(y...);
  if (res >= mod)
    res -= mod;
  return res;
}
template<typename T, typename... Ts>
T sub(T x, Ts... y) {
  return add(x, mod - add(y...));
}
template<typename T, typename... Ts>
void udd(T &x, Ts... y) {
  x = add(x, y...);
}
template<typename T>
T mul(T x) {
  return x;
}
template<typename T, typename... Ts>
T mul(T x, Ts... y) {
  return (x * 1ll * mul(y...)) % mod;
}
template<typename T, typename... Ts>
void uul(T &x, Ts... y) {
  x = mul(x, y...);
}
int bin(int a, ll deg) {
  int r = 1;
  while (deg) {
    if (deg & 1)
      uul(r, a);
    deg >>= 1;
    uul(a, a);
  }
  return r;
}
int inv(int x) {
  assert(x);
  return bin(x, mod - 2);
}

const int maxn = 200200;
vector<pair<int, int>> g[maxn];
int used[maxn];
int col[maxn];
int n;
string r;
bool fail;

void dfs(int u) {
  for (auto [v, c] : g[u]) {
    int nc = col[u] ^ c;
    if (used[v] != -1) {
      if (nc != col[v]) {
        fail = true;
      }
      continue;
    }
    col[v] = nc;
    used[v] = used[u];
    dfs(v);
  }
}

int calc(int d) {
  //cerr << "calc " << d << '\n';
  for (int i = 0; i < n; ++i) {
    g[i].clear();
    used[i] = -1;
  }
  fail = false;
  for (int i = 0; i < n; ++i) {
    g[i].emplace_back((i + d) % n, ((i + d) / n) % 2);
  }
  int deg = 0;
  for (int i = n - 1; i >= 0; --i) {
    if (used[i] == -1) {
      ++deg;
      col[i] = r[i] == '1';
      used[i] = i;
      dfs(i);
    }
    if (fail) {
      return 0;
    }
  }
  int res = 0;
  for (int i = n - 1; i >= 0; --i) {
    if (col[i] == 1 && r[i] == '0') {
      return res;
    }
    if (col[i] == 0 && r[i] == '1') {
      break;
    }
    if (used[i] == i) {
      --deg;
      if (col[i] == 1) {
        //cerr << "KEK " << deg << '\n';
        udd(res, bin(2, deg));
      }
    }
  }
  udd(res, bin(2, deg));
  return res;
}

