void adddiv(int i, int rem, int t)
{
	if (cntset[i][rem][0] > 0 && cntset[i][rem][1] > 0) cntbad[i] += t;
	else if (cntset[i][rem][0] == 0 && cntset[i][rem][1] == 0) cntfree[i] += t;
}

void sett(int pos, int v)
{
	//cout << "sett " << pos << ' ' << v << endl;
	for (int i = 0; i < (int)divsn.size(); i++)
	{
		int rem = pos % divsn[i];
		adddiv(i, rem, -1);
		if (isset[pos] != -1)
		{
			cntset[i][rem][isset[pos]]--;
		}
		cntset[i][rem][v]++;
		adddiv(i, rem, 1);
		//cout << divsn[i] << ' ' << rem << ' ' << cntfree[i] << ' ' << cntset[i][rem][isset[pos]] << endl;
	}
	isset[pos] = v;
}

void solve(int fixed)
{
