	for (int i = 0; i < (int)divsn.size(); i++) if (n % divsn[i] != 0)
	{
		ans[i] = 0;
		if (cntbad[i] == 0) ans[i] = p2[cntfree[i] / 2];
		//cout << divsn[i] << ' ' << ans[i] << endl;
		for (auto t : divs[divsn[i]])
