	{
		divsn.pb(i);
		int mu = -1;
		int cur = i;
		for (int j = 2; j * j <= cur; j++) if (cur % j == 0)
		{
			if (cur % (j * j) == 0) mu = 0;
			while (cur % j == 0) cur /= j;
			mu *= -1;
		}
		if (cur > 1) mu *= -1;
		for (int j = i * 2; j <= 2 * n; j += i) divs[j].pb({(int)divsn.size() - 1, mu});
	}
