			sett(fixed, 0);
			sett(n + fixed, 1);
			solve(fixed);
		}
	}
	sett(n - 1, s[n - 1] - '0');
	sett(n + n - 1, 1 - (s[n - 1] - '0'));
	solve(n);
	cout << answer << endl;
    return 0;
