string reverse(string i1){
	ll nn = i1.length();
	string i2;
	for(int i=0;i<nn;i++){
		if(i1[i] == '1'){
			i2 += '0';
		}else{
			i2 += '1';
		}
	}
	return i2;
}

ll cnt(ll i){
	string t = s.substr(0, i / 2);
	ll nn = t.length() * 2;
	ll tmp = 0;
	for(int i=0;i<nn / 2;i++){
		tmp *= 2;
		tmp += (t[i] - '0');
		tmp %= mod;
	}
	string u;
	for(int i=0;i<n/nn;i++){
		u += t;
		u += reverse(t);
	}
	if(u <= s){
		tmp += 1;
	}
	return tmp;
}

void solve(ll i){
	//pe("solved ");
	//p(i);
	ans_table[i] = true;
	ll base = cnt(i);
	x[i] = base % mod;
	return;
}

int main(){
    cin >> n >> s;
    for(int i=2;i*i<=2*n;i++){
    	ll a = i;
    	if((n % a) != 0 && ((2 * n) % a) == 0) {
    		solve(a);
    	}
    	if(i * i == 2 * n)break;
    	a = 2 * n / i;
    	if((n % a) != 0 && ((2 * n) % a) == 0) {
    		solve(a);
    	}
    }
    for(int i=1;i<=n;i++){
    	for(int j=2;j*i<=n;j++){
    		if(!ans_table[i*j])continue;
    		x[j*i] += mod - x[i];
    		x[j*i] %= mod;
    	}
    }
    for(int i=1;i<=n;i++){
    	//pe(i);p(x[i]);
    }
    ll ans = 0;
    ll num = 0;
    for(int i=0;i<n;i++){
    	num *= 2;
    	num += (s[i] - '0');
    	num %= mod;
    }
    num++;

    for(int i=1;i<=n;i++){
    	ans += (x[i] * i) % mod;
    	num += mod - x[i];
    	num %= mod;
    	ans %= mod;
    }
    p((ans + num * 2 * n) % mod);

    return 0;
}

