  for(const int & x : v){
    if(x%2==0)continue;
    int len = N/x;
    vector<PII> pf = prime_factor(len);
    int n_d = 0;
    for(const PII& p :pf) n_d += p.second;
    string t = s.substr(0,len);
    mint n = 0;
    mint n_2 = MINT 1;
    rep(i,len){
      if(t[len-i-1]=='1') n+=n_2;
