      if(t[i] == '0')t.push_back('1');
      else t.push_back('0');
    }
    while(t.length() < N) t+=t;
    t = t.substr(0,N);
    if(t<=s) n+=MINT 1;

    mp[len] = PMI(n,n_d&1);
    for(const pair<int,PMI>& p : mp){
