const int64_t MOD = 998244353;
void add(int64_t& a, int64_t b){
    a = (a+b) % MOD;
}
void mul(int64_t& a, int64_t b){
    a = a*b % MOD;
}

vector<int64_t> fact, seq_inv, fact_inv;

void create_fact_mod(int num){
    fact[0] = fact[1] = 1;
    for(int i=2; i<=num; i++) fact[i] = fact[i-1] * i % MOD;
}

void create_seq_inv_mod(int num){
    seq_inv[0] = seq_inv[1] = 1;
    for(int i=2; i<=num; i++) seq_inv[i] = (MOD - MOD/i) * seq_inv[MOD%i] % MOD;
}

void create_fact_inv_mod(int num){
    fact_inv[0] = fact_inv[1] = 1;
    for(int i=2; i<=num; i++) fact_inv[i] = fact_inv[i-1] * seq_inv[i] % MOD;
}

void create_mod_tables(int num){
    fact.resize(num+1);
    seq_inv.resize(num+1);
    fact_inv.resize(num+1);
    create_fact_mod(num);
    create_seq_inv_mod(num);
    create_fact_inv_mod(num);
}

int64_t comb_mod(int n, int k){
    return fact[n] * fact_inv[n-k] % MOD * fact_inv[k] % MOD;
}

int64_t perm_mod(int n, int k){
    return fact[n] * fact_inv[n-k] % MOD;
}

int64_t power_mod(int64_t num, int64_t power){
    int64_t prod = 1;
    num %= MOD;
    while(power > 0){
        if(power&1) prod = prod * num % MOD;
        num = num * num % MOD;
        power >>= 1;
    }
    return prod;
}

int64_t extgcd(int64_t a, int64_t b, int64_t& x, int64_t& y){
    int64_t d = a;
    if(b != 0){
        d = extgcd(b, a%b, y, x);
        y -= (a/b) * x;
    }else{
        x = 1; y = 0;
    }
    return d;
}

int64_t inv_mod(int64_t a){
    int64_t x, y;
    extgcd(a, MOD, x, y);
    return (MOD + x%MOD) % MOD;
}


int main(){
    int N;
    string X;
    cin >> N >> X;
    vector<int64_t> pow2(N+1);
    pow2[0] = 1;
    for(int i=1; i<=N; i++) pow2[i] = pow2[i-1] * 2 % MOD;

    vector<int> divs;
    for(int d=1; d*d<=N; d++) if(N%d == 0){
        int d2 = N/d;
        if(d2%2) divs.push_back(d);

        if(d != d2 && d%2) divs.push_back(d2);
    }
    // if(N%2){
    //     divs.push_back(1);
    //     if(N > 1) divs.push_back(N);
    // }
    sort(divs.begin(), divs.end());

    vector<bool> dead(N+1);
    vector<int64_t> num(N+1);
    for(int i=0; i<N; i++){
        if(X[i] == '1'){
            for(int d : divs){
                if(dead[d]) continue;
                if(i >= d && X[i-d] == '0') continue;
                int64_t C = pow2[max(0, d-i-1)];
                add(num[d], C);
            }
        }
        for(int d : divs){
            if(i >= d && X[i-d] == X[i]) dead[d] = true;
        }
    }
    for(int d : divs) if(!dead[d]){
        add(num[d], 1);
    }
    for(int d : divs){
        for(int k=2*d; k<=N; k+=d) add(num[k], MOD - num[d]);
    }
    //for(int d : divs) cerr << d << " " << num[d] << endl;
    int64_t ans = 0;
    for(int d : divs){
        int64_t res = num[d] * d;
        if(true) mul(res, 2);
        add(ans, res);
    }
    cout << ans << endl;

    return 0;
}

