int to_int(string t){
	int ret=0;
	for(auto c:t){
		ret=ret*2+c-'0';
		ret%=mod;
	}
	return ret;
}
bool ok(string &a,string &b){
	for(int i=0;i<a.size();i++){
		if(a[i]+b[i]!='0'+'1')return false;
	}
	return true;
}
