int calc(int len){
	if(n*2%len!=0)return 0;
	if((n*2/len)%2==0)return 0;
	valid[len]=1;
	int read_len=len/2;
	vector<string>vs;
	for(int j=0;j<x.size();j+=read_len){
		vs.push_back(getstr(x,j,j+read_len-1));
	}
	int pos=0;
	while(pos+2<vs.size()&&ok(vs[pos],vs[pos+1])){
		pos++;
	}
	if(pos&1)vs[pos]=inv(vs[pos]);
	else vs[pos+1]=inv(vs[pos+1]);
	if(pos&1){
		if(vs[pos]>vs[pos+1])return to_int(vs[pos]);
		return to_int(vs[pos])+1;
	}else{
		if(vs[pos+1]>vs[pos])return to_int(vs[pos]);
		else return to_int(vs[pos])+1;
	}
}

