			if(valid[j])ans[j]-=ans[i];
			if(ans[j]<0)ans[j]+=mod;
		}
	}
	int res=0;
	for(int i=1;i<=n+n;i++){
		res+=ans[i]*i;
		res%=mod;
	}
	cout<<res<<endl;
	return 0;
}

