ll modExp(ll b, ll ex){
    ll prod = 1;
    while(ex > 0){
        if(ex % 2 == 0){
            b = (b * b) % MOD;
            ex /= 2;
        } else{
            prod = (prod*b) % MOD;
            ex--;
        }
    }

    return prod;
}

vi facs[MN];
void sieve(){
    FOR(i, 1, MN-1){
        for(int j=i*2; j<MN; j+=i){
            facs[j].pb(i);
        }
    }
}
ll cnts[MN];

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    sieve();

    cin >> n >> s;

    ll ans = 0;

    RFOR(i, n, 1){ //i = # blocks
        if((i % 2 == 0) || (n % i != 0)) continue;
        ll cnt = 0;
        int sz = n/i;
        F0R(j, sz){
            if(s[j] == '1') cnt += modExp(2, sz-j-1);
            cnt %= MOD;
        }
        bool ok = true;
        bool gd = false;
        FOR(j, 1, i-1){
            FOR(k, sz*j, sz*(j+1)-1){
                //cout << "doing " << j << " " << k << " " << s[k] << "\n";
                if(j%2==0){
                    if(s[k] < s[k%sz]) ok = false;
                    if(s[k] > s[k%sz]) gd = true;
                } else{
                    if(s[k] < ('1'+'0'-s[k%sz])) ok = false;
                    if(s[k] > ('1'+'0'-s[k%sz])) gd = true;
                }
                if(!ok) break;
                if(gd) break;
            }
            if(!ok) break;
            if(gd) break;
        }
        if(ok) ++cnt;
        //else cout << "hmm\n";

        for(auto u : facs[sz]){
            cnt = cnt - cnts[u];
            cnt = (cnt+MOD)%MOD;
        }
        cnts[sz] = cnt;
        //cout << i << " " << cnt << "\n";
        ans += (sz*2*cnt)%MOD;
        ans %= MOD;
    }

    cout << ans << "\n";

    return 0;
}

