  for (int i = 1; i <= N; i += 2)
    if (N % i == 0) div.pb(i);
  string S;
  cin >> S;
  cerr << S;
  int sz = div.size();
  vi co(sz);
  rep(i, sz) {
    ll block = div[i];
    ll len = N / block;
    string head = S.substr(0, len);
    string head_rev = head;
    replace(all(head_rev), '0', '2');
    replace(all(head_rev), '1', '0');
    replace(all(head_rev), '2', '1');
    ll headnum = 0;
    rep(i, len) {
      headnum *= 2;
      headnum = headnum % mod;
      headnum += (S[i] - '0');
    }
    string sub;
    for (int i = 0; i < block; ++i) {
      sub = S.substr(len * i, len);
      if (i % 2 == 0) {
        if (head > sub) {
          break;
        } else if (head < sub) {
          ++headnum;
          break;
        }
      } else {
        if (head_rev > sub) {
          break;
        } else if (head_rev < sub) {
          ++headnum;
          break;
        }
      }
      if (i == block - 1) {
        ++headnum;
        break;
      }
    }
    co[i] = headnum;
  }

  for (int i = sz - 1; i >= 0; --i) {
    for (int j = 0; j < i; ++j) {
      if (div[i] % div[j] == 0) {
        co[j] -= co[i];
      }
    }
  }
  ll ans = 0;
  rep(i, sz) {
    ans += 2 * N / div[i] * co[i];
    ans = ans % mod;
  }
