using mint = ModInt<MODD>;
map<int, mint> dp;

vector<int> odd_divisor(int N) {
    vector<int> ret;
    for (int i = 1; i <= N; i += 2) {
        if (N % i == 0) {
            ret.emplace_back(i);
        }
    }
    return ret;
}

signed main() {

    int N;
    string X;
    cin >> N >> X;

    auto div = odd_divisor(N);
    for (auto& e: div) {
        int k = N / e;
        // Xの上位k桁
        mint top_k = 0;
        for (int i = 0; i < k; ++i) {
            top_k *= 2;
            top_k += X[i] - '0';
        }
        dp[e] = top_k;      // 真に等しい場合を除く
        {   // 真に等しい場合...
            bool ok = true;
            for (int i = k; i < N; ++i) {
                bool flip = (i / k) % 2 == 1;
                char bef = X[i % k];
                if (flip) bef ^= 1;
                char aft = X[i];
                if (bef > aft) {
                    ok = false;
                    break;
                }
                if (bef < aft) {
                    break;
                }
            }
            // debug(k, ok);
            if (ok) dp[e] += 1;
        }
    }

    // debug(dp);
    reverse(ALL(div));
    for (auto& a: div) {
        for (auto& b: div) {
            if (a < b and b % a == 0) {
                dp[a] -= dp[b];
            }
        }
    }

    mint res = 0;
    for (auto& [u, v]: dp) {
        // debug(2 * N / u, v);
        res += v * (2 * N / u);
    }
    print(res);

}

