#define int long long
const int N=1000005,M=998244353;
int ne[N],tot,b[N],a[N],fac[N],fi[N],zz[N],sl[N],miu[N],cnt,flag[N],fa[N],f[N],g[N],n;
char s[N];
int find(int x){
	if (x==fa[x])return x;
	return fa[x]=find(fa[x]);
}
int ksm(int x,int y){
	int ans=1;
	for (;y;y>>=1,x=x*x%M)
		if (y&1)(ans*=x)%=M;
	return ans;	
}
void jb(int x,int y,int z){
	ne[++tot]=fi[x];
	fi[x]=tot;
	zz[tot]=y;
	sl[tot]=z;
	fa[find(x)]=find(y);
}
void dfs(int x){
	flag[x]=1;
	for (int i=fi[x];i;i=ne[i])
		if (!flag[zz[i]]){
			flag[zz[i]]=1;
			a[zz[i]]=(a[x]+sl[i])%2;
			dfs(zz[i]);
		}
}
void init(){
	miu[1]=1;
	for (int i=2;i<N;i++){
		if (!flag[i]){
			b[++tot]=i;
			miu[i]=-1;
		}
		for (int j=1;j<=tot;j++){
			int k=b[j]*i;
			if (k>=N)break;
			flag[k]=1;
			if (i%b[j]==0){
				miu[k]=0;
				break;
			}
			miu[k]=-miu[i];
		}
	}
}
signed main(){
	init();fac[0]=1;
	scanf("%lld",&n);
	for (int i=1;i<=2*n;i++)fac[i]=fac[i-1]*2%M;
	scanf("%s",s);
	for (int i=n;i<2*n;i++)s[i]=s[i-n]^1;
	int kk=n,p=1;
	while (kk%2==0)p++,kk>>=1;
	for (int A=1;A<=2*n;A++)
		if (n%A!=0&&(2*n)%A==0){
			memset(fi,0,sizeof fi);
			memset(flag,0,sizeof flag);
			memset(a,0,sizeof a);
			tot=cnt=0;
			for (int i=0;i<2*n;i++)fa[i]=i;
			for (int i=0;i<2*n;i++)jb(i,(i+A)%(2*n),0),jb((i+A)%(2*n),i,0);
			for (int i=0;i<n;i++)jb(i,i+n,1),jb(i+n,i,1); 
			for (int i=0;i<2*n;i++)
				if (i==find(i))cnt++;
			for (int i=0;i<2*n;i++){
				if (i==n){
					f[A>>p]++;
					break;
				}
				if (flag[i]&&a[i]>s[i]-'0')break;
				else if (flag[i]&&a[i]<s[i]-'0'){
					(f[A>>p]+=fac[cnt])%=M;
					break;
				}
				else if (flag[i])continue;
				cnt--;
				if (s[i]=='0'){
					a[i]=0;
					dfs(i);
				}
				else {
					(f[A>>p]+=fac[cnt])%=M;
					a[i]=1;
					dfs(i);
				} 
			}
		}
	n<<=1;n>>=p;	
	for (int i=1;i<=n;i++)
		if (f[i])for (int j=1;j*i<=n;j+=2)
			if ((2*n)%(i*j)==0)(g[i*j]+=miu[j]*f[i])%=M;
	int ans=0;		
	for (int i=1;i<=n;i++)(ans+=g[i]*i)%=M;
	printf("%lld\n",ksm(2,p)*(ans+M)%M);			
	return 0;
}

