Int modadd(Int a, Int b) {
    Int ret = (a + b) % MOD;
    if (ret < 0) ret += MOD;
    return ret;
}

Int modsub(Int a, Int b) {
    Int ret = (a - b) % MOD;
    if (ret < 0) ret += MOD;
    return ret;
}

Int modmul(Int a, Int b) {
    Int ret = (a * b) % MOD;
    if (ret < 0) ret += MOD;
    return ret;
}

class Solve {
public:
    void solve() {
        Int N;
        string S;
        cin >> N >> S;

        vector<Int> divs;
        for (int i = 1; i <= N; ++i) {
            if (N % i == 0 && (N / i) % 2 == 1) {
                divs.push_back(i);
            }
        }
        vector<Int> kei(N + 1);
        for (int i = divs.size() - 1; i >= 0; --i) {
            kei[divs[i]] = 2 * divs[i];
            for (int j = divs[i] * 2; j <= kei.size(); j += divs[i]) {
                if (N % j == 0 && N / j % 2 == 1) {
                    kei[divs[i]] -= kei[j];
                }
            }
        }
        for (int i = 0; i < N + 1; ++i) {
            kei[i] = modadd(kei[i], 0);
        }

        Int ans = 0;
        for (auto e : divs) {
            Int cnt = 0;
            for (int i = 0; i < e; ++i) {
                cnt = 2 * cnt + S[i] - '0';
                cnt = modadd(cnt, 0);
            }

            string T = S;
            for (int i = e; i < N; ++i) {
                T[i] = static_cast<char>(T[i - e] ^ 1);
            }

            if (T <= S) {
                cnt++;
            }

            ans = modadd(ans, modmul(cnt, kei[e]));
        }

        cout << ans << endl;


    }
};


int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    cout << fixed << setprecision(10);

    Solve().solve();


    return 0;
}

