	while (n % p2 == 0) p2 *= 2;
	p2 /= 2;
	int odd = n / p2;

	LL ans = 0;
	for (int i = 1; i <= n; i++) {
		if (i % p2 != 0) continue;
		if (odd % (i / p2) != 0) continue;
		// if X has period p2*i, then use X[0..i-1], else X[0..i-1] - 1
		bool valid = true;
		for (int j = 0; valid && j + i < n; j++) {
			if (X[j] == X[j + i]) valid = false;
		}

