  for (int i = 1; i <= n; ++i) {
    if (n % i or (i & 1) == 0) {
      continue;
    }
    int k = n / i, res = 0;
    for (int j = 0; j < k; ++j) {
      res = add(res, res);
      if (s[j] == '1') {
        res = add(res, 1);
      }
    }
    for (int j = 0; j <= n; ++j) {
      if (j == n) {
        res = add(res, 1);
