template <std::uint_fast64_t Modulus>
class modint {
  using u64 = std::uint_fast64_t;

 public:
  u64 a;

  constexpr modint(const u64 x = 0) noexcept
      : a(x % Modulus) {
  }
  constexpr u64 &value() noexcept {
    return a;
  }
  constexpr const u64 &value() const noexcept {
    return a;
  }
  constexpr modint operator+(const modint rhs) const noexcept {
    return modint(*this) += rhs;
  }
  constexpr modint operator-(const modint rhs) const noexcept {
    return modint(*this) -= rhs;
  }
  constexpr modint operator*(const modint rhs) const noexcept {
    return modint(*this) *= rhs;
  }
  constexpr modint operator/(const modint rhs) const noexcept {
    return modint(*this) /= rhs;
  }
  constexpr modint &operator+=(const modint rhs) noexcept {
    a += rhs.a;
    if (a >= Modulus) {
      a -= Modulus;
    }
    return *this;
  }
  constexpr modint &operator-=(const modint rhs) noexcept {
    if (a < rhs.a) {
      a += Modulus;
    }
    a -= rhs.a;
    return *this;
  }
  constexpr modint &operator*=(const modint rhs) noexcept {
    a = a * rhs.a % Modulus;
    return *this;
  }
  constexpr modint &operator/=(const modint rhs) noexcept {
    return *this *= ~rhs;
  }
  constexpr modint power(u64 exp) const noexcept {
    modint v = 1, x = *this;
    while (exp) {
      if (exp & 1) {
        v *= x;
      }
      x *= x;
      exp >>= 1;
    }
    return v;
  }
  constexpr modint operator~() const noexcept {
    return power(Modulus - 2);
  }
};

vector<int> divisors(int N) {
  vector<int> res;
  for (int i = 1; i * i <= N; i++) {
    if (N % i == 0) {
      res.push_back(i);
      if (N / i != i) res.push_back(N / i);
    }
  }
  sort(res.begin(), res.end());
  return res;
}

using mint = modint<998244353>;

struct edge_t {
  int to;
  int w;
};

mint pw2[200000 + 10];

mint solve(int N, const vector<int>& X, int L) {
  if (N % L == 0) return 0;
  vec<edge_t, 2> G(N);
  for (int i = 0; i < N; i++) {
    int j = (i + L) % N;
    int w = ((i + L) / N) % 2;
    G[i].push_back({ j, w });
  }
  vector<int> id(N, -1), color(N, -1);
  vec<int, 2> group;
  for (int i = 0; i < N; i++) {
    if (id[i] != -1) continue;
    int v = i, c = 0, k = group.size();
    group.push_back({});
    while (id[v] == -1) {
      id[v] = k;
      color[v] = c;
      group[k].push_back(v);
      assert(G[v].size() == 1);
      int nv = G[v][0].to;
      int w = G[v][0].w;
      v = nv;
      c ^= w;
    }
    assert(v == i);
    if (c) return 0;
  }
  mint res = 0;
  int rem = group.size();
  vector<int> bit(N, -1);
  for (int i = N - 1; i >= 0; i--) {
    if (bit[i] != -1) {
      if (bit[i] > X[i]) {
        return res;
      }
      if (bit[i] < X[i]) {
        res += pw2[rem];
        return res;
      }
      continue;
    }
    int k = id[i];
    --rem;
    if (X[i] == 0) {
      for (int v : group[k]) bit[v] = (0 ^ color[i] ^ color[v]);
    } else {
      res += pw2[rem];
      for (int v : group[k]) bit[v] = (1 ^ color[i] ^ color[v]);
    }
  }
  res += 1;
  return res;
}

