struct Prime {
  int max_check;
  int max_prime;
  int prime_number;
  vector<int> primes;
  map<int, int> prime_id;
  Prime() {};
  Prime(int m) {
    initialize(m);
  };
  void initialize(int m) {
    sieve(m);
    prime_number = (int)primes.size();
    max_check = m;
  }

  void sieve(int m) {
    max_prime = 2;
    deque<bool> is_prime(m+1, true);
    is_prime[0] = is_prime[1] = false;
    int i;
    for (i = 2; i <= m; ++i) {
      if (!is_prime[i]) {
        continue;
      }
      if (i * i > m) {
        break;
      }
      for (int j = i*2; j <= m; j += i) {
        is_prime[j] = false;
      }
      prime_id[i] = (int)primes.size();
      primes.push_back(i);
      max_prime = i;
    }
    for (int j = i; j <= m; ++j) {
      if (!is_prime[j]) {
        continue;
      }
      prime_id[j] = (int)primes.size();
      primes.push_back(j);
      max_prime = j;
    }
  }

  map<int, int> prime_factor(ll x) {
    map<int, int> ret;
    if ((ll)max_check * (ll)max_check < x) {
      return ret;
    }
    for (int i = 0; i < prime_number; ++i) {
      if (x == 1) {
        break;
      }
      while (x % primes[i] == 0) {
        x /= primes[i];
        ret[primes[i]] += 1;
      }
    }
    if (x != 1) {
      ret[x] += 1;
    }
    return ret;
  }
};

vi odd_divisors_(int a) {
  while (a % 2 == 0) {
    a /= 2;
  }
  set<int> si_div;
  for (int i = 1; i * i <= a; i += 2) {
    if (a % i == 0) {
      si_div.insert(i);
      si_div.insert(a / i);
    }
  }
  si_div.erase(1);
  vi ret;
  for (int d: si_div) {
    ret.push_back(d);
  }
  return ret;
}

vi primes;

vi odd_divisors(int a) {
  vi ret;
  for (int d: primes) {
    if (d > a) {
      break;
    }
    if (a % d == 0) {
      ret.push_back(d);
    }
  }
  return ret;
}

int n;
using bs2e5 = bitset<200000>;
int maxn = 200000;
int mod = 998244353;
vll po2;

bool weak_bigger(bs2e5 a, bs2e5 b) {
  rep (i_, n) {
    int i = n-1 - i_;
    if (a[i] < b[i]) {
      return true;
    }
    if (a[i] > b[i]) {
      return false;
    }
  }
  return true;
}

ll count(int d, bs2e5 & bs) {
  assert (d >= 3);
  int section_size = n / d;
  ll ret = 0;
  auto cbs = bs2e5();
  rep (i, section_size) {
    if (bs[n-1 - i]) {
      ret = (ret + po2[section_size - 1 - i]) % mod;
      cbs[n-1 - i] = true;
    }
    //debug(ret);
  }
  cbs |= (cbs >> section_size);
  rep (i, section_size) {
    cbs.flip(n-1 - section_size - i);
  }
  int css = section_size * 2;
  while (true) {
    cbs |= (cbs >> css);
    css *= 2;
    if (css >= n) {
      break;
    }
  }
  //debug(cbs.to_string().substr(maxn - n, n));
  //debug(bs.to_string().substr(maxn - n, n));
  if (weak_bigger(cbs, bs)) {
    ret = (ret + 1) % mod;
  }
  return ret;
}

int main() {
  scan(n);
  string x;
  scan(x);
  primes = Prime(maxn).primes;
  primes.erase(begin(primes));

  po2.resize(200010);
  po2[0] = 1;
  rep (i, maxn) {
    po2[i + 1] = po2[i] * 2 % mod;
  }
  auto bs = bitset<200000>(x);
  //debug(bs);
  auto divs = odd_divisors(n);
  sort(all(divs));
  int sz = (1 << divs.size());
  vll inex(sz, 0);
  vi ds(sz, 0);
  ds[0] = 1;
  for (int i = sz - 1; i > 0; --i) {
    int d = 1;
    rep (j, (int)divs.size()) {
      if ((i >> j) & 1) {
        d *= divs[j];
      }
    }
    ds[i] = d;
    inex[i] = count(d, bs);
  }
  //debug(inex);

  inex[0] = 1;
  rep (i, n) {
    if (bs[i]) {
      inex[0] = (inex[0] + po2[i]) % mod;
    }
  }
  for (int i = sz - 1; i >= 0; --i) {
    FOR (j, i+1, sz) {
      int k = j - i;
      if ((i | k) == j) {
        inex[i] = (inex[i] + mod - inex[j]) % mod;
      }
    }
  }

  ll ans = 0;
  for (int i = sz - 1; i >= 0; --i) {
    int t = n / ds[i];
    ans = (ans + inex[i] * t * 2) % mod;
  }
  //debug(ds);
  //debug(inex);
  print(ans);

  return 0;
}

