int solve(int i){
	fill(fg0);
	fill(fg1);
	g.clear();
	g.resize(n);
	UF dsu(n);
	rep(j,n){
		if(i+j>=n){
			if(!dsu.join(j,(i+j)-n,1)) return 0;
		}
		else if(!dsu.join(j,i+j,0)) return 0;
	}
	int cmp = 0;
	rep(i,n){
		if(dsu.find(i)==i) cmp++;
	}
	ll ans = 0;
	rep(i,n){
		int j = dsu.find(i);
		int w = dsu.d[i];
		if(!fg0[j]&&!fg1[j]) cmp--;
		if(!w&&!fg0[j]&&x[i]=='1') ans+=pw[cmp],fg0[j]=1;
		if(w&&!fg1[j]&&x[i]=='1') ans+=pw[cmp],fg1[j]=1;
		if(!w&&!fg1[j]&&x[i]=='0') fg1[j]=1;
		if(w&&!fg0[j]&&x[i]=='0') fg0[j]=1;
		if(fg0[j]&&fg1[j]) return ans%mod;
	}
	return (ans+1)%mod;
}

