		return str <= x;
	};


	repa(i, n/2+1){
		if(n%i==0){
			if((n/i)%2==0)continue;
			mint start = sum;
			for(int j=i*2;j<n;j+=i){
				dp[j-1][0] -= dp[i-1][0];
			}
			sum -= dp[i-1][0];
			ans += mint(i*2) * dp[i-1][0];
			string strs = x.substr(0, i);
			string add = x.substr(0, i);
			if(can(i)){
				for(int j=i*2;j<n;j+=i){
					add = getrev(add);
					strs += add;
					if(x.substr(0, j)==strs){
						dp[j-1][1] -= dp[i-1][1];
					}else{
						dp[j-1][0] -= dp[i-1][1];
					}
				}
				sum -= dp[i-1][1];
				ans += mint(i*2) * dp[i-1][1];
			}
		}
	}

	ans += sum * mint(n * 2);
	cout << ans << endl;

	return 0;
}

