const int N = 2e5 + 5, md = 998244353;

inline int add(int x, int y) {
    x += y;
    if(x >= md) x -= md;
    return x;
}

inline int sub(int x, int y) {
    x -= y;
    if(x < 0) x += md;
    return x;
}

inline int mul(int x, int y) { return 1ll * x * y % md; }

inline int fpow(int x, int y) {
    int ans = 1;
    while(y) {
        if(y & 1) ans = mul(ans, x);
        y >>= 1; x = mul(x, x);
    }
    return ans;
}

char c[N];
int len[N], f[N];
int n, m, ans;

int check(int l) {
    for(register int i = l + 1; i <= n; i++) {
        int val = (c[(i - 1) % l + 1] - '0') ^ (((i - 1) / l) & 1);
        if(val < c[i] - '0') return 1;
        if(val > c[i] - '0') return 0;
    }
    return 1;
}

int solve(int l) {
    int ans = 0;
    for(register int i = 1; i <= l; i++) ans = add(add(ans, ans), c[i] - '0');
    return ans + check(l);
}

int main() {
    read(n); scanf("%s", c + 1);
    for(register int i = 1; i <= n; i++) {
        if(n % i == 0 && ((n / i) & 1)) {
            len[++m] = i;
            f[m] = solve(i);
        }
    }
    // for(register int i = 1; i <= m; i++) {
    //     fprintf(stderr, "%d, %d\n", len[i], f[i]);
    // }
    for(register int i = 1; i <= m; i++) {
        for(register int j = 1; j < i; j++) {
            if(len[i] % len[j] == 0) {
                f[i] = sub(f[i], f[j]);
            }
        }
        ans = add(ans, mul(f[i], 2 * len[i]));
    }
    print(ans, '\n');
    return 0;
}

