using namespace std;

long long prime = 998244353;

vector<int> divisors(int n) {
    vector<int> ds;
    for (int i = 1; i*i <= n; ++i) {
        if (n % i == 0) {
            ds.push_back(i);
            if (i != n/i) {
                ds.push_back(n/i);
            }
        }
    }
    sort(ds.begin(), ds.end());
    return ds;
}

template <typename F>
map<long long, long long> mult_fun(long long n, F& fun, long long P) {
    if (n == 1LL) {
        map<long long, long long> res;
        res[1] = 1;
        return res;
    }
    for (long long p = 2; p * p <= n; ++p) {
        if (n % p == 0) {
            long long pk = p;
            int k = 1;
            while ((n / pk) % p == 0) {
                pk *= p;
                ++k;
            }
            map<long long, long long> rec = mult_fun(n / pk, fun, P);
            vector<long long> p_rec = fun(pk, p);
            pk = 1;
            map<long long, long long> res;
            for (int i = 0; i <= k; ++i, pk *= p) {
                for (auto g : rec) {
                    res[g.first * pk] = (g.second * p_rec[i]) % P;
                }
            }
            return res;
        }
    }
    vector<long long> p_rec = fun(n, n);
    map<long long, long long> res;
    res[1] = p_rec[0];
    res[n] = p_rec[1];
    return res;
}

vector<long long> generator(long long pk, long long p) {
    vector<long long> fs;
    fs.push_back(1LL);
    while (pk > 1) {
        fs.push_back(((1LL - p) % prime + prime) % prime);
        pk /= p;
    }
    return fs;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n;
    string s;
    cin >> n >> s;
    vector<int> xs(n);
    for (int i = 0; i < n; ++i) {
        xs[i] = s[i] == '1';
    }
    int m = n&(-n);
    map<int, long long> f;
    auto fits_equal = [&](int k) {
        for (int i = k; i < n; ++i) {
            // xs[i] vs xs[i%k] if i/k is even and 1-xs[i%k] if i/k is odd.
            int y = (i/k) % 2 == 0 ? xs[i%k] : 1-xs[i%k];
            if (xs[i] > y) {
                return true;
            }
            if (xs[i] < y) {
                return false;
            }
        }
        return true;
    };
    auto ds = divisors(n / m);
    for (int d : ds) {
        long long num_less = 0;
        int k = d * m;
        for (int i = 0; i < k; ++i) {
            num_less = (2*num_less + xs[i]) % prime;
        }
        num_less = (num_less + fits_equal(k) + prime) % prime;
        f[d] = num_less;
    }
    // result is 1 * (id g) = 1 * (id (mu * f)) = (1 * (id mu)) * (id f)
    // let h = 1 * (id mu)
    // h(1) = 1
    // h(p) = p * mu(p) + 1 * mu(1) = 1 - p
    // h(p^k) = 1 - p, k >= 1
    map<long long, long long> h = mult_fun(n/m, generator, prime);
    long long result = 0;
    for (int d : ds) {
        result = (result + ( h[n/m/d] * d ) % prime * f[d]) % prime;
    }
    cout << (2*m*result)%prime << endl;
    return 0;
}

