ll cnt2(ll N,ll K){
  ll cnt=0;
  ll tmp=K;
  do{
    cnt++;
    if(tmp&1){tmp>>=1;}
    else{tmp>>=1; tmp^=(1LL<<(N-1));}
  }while(tmp!=K);
  return cnt;
}

