        tmp *= 2;
    }

    ans *= mint(2 * n);

    if (n % 2 == 1) {
        //X >= 1010101....01　かどうか
        bool over = false;
        rep(i, n) {
            if (! (i & 1)) { //1-indexedで奇数桁目のとき
                if (X[i] == '0') break;
            }
            else {
                if (X[i] == '1') {
                    over = true;
                    break;
                }
            }
            if (i == n - 1) over = true;
        }
        if (over) ans -= mint(2 * n - 2);

        //同様に010101...10について
        over = false;
        rep(i, n) {
            if (! (i & 1)) { //1-indexedで奇数桁目のとき
