typedef long long ll;
const ll MOD = 998244353;
const int n = 2e5 + 10;

int N;
string X;
vector<int> D;
bool dPos[100];
bool S[n];
ll pw[n], C[n];
ll tmp[n];

int main(){
  cin >> N;
  cin >> X;
  for(int i=0; i<N; i++){
    S[i] = X[i] == '1';
  }
  pw[0] = 1;
  for(int i=1; i<=N; i++){
    pw[i] = pw[i-1] * 2;
    pw[i] %= MOD;
  }
  ll res = 0;
  for(int i=N; i>0; i--){
    if(N%i == 0 && N/i%2 == 1){
      D.push_back(i);
      dPos[sz(D)-1] = true;
    }
  }
  for(int x : D){
    C[x] = 2*x - tmp[x];
    for(int y : D){
      if(x%y == 0 && x != y){
        tmp[y] += C[x];
      }
    }
  }
  /*
  for(int x : D){
    cout << x << ": " << C[x] << endl;
  }
  */
  for(int i=0; i<N; i++){
    if(S[i]){
      for(int j=0; j<sz(D); j++){
        if(!dPos[j] || (D[j] <= i && !S[i-D[j]]))
          continue;
        int rem = max(0, D[j]-i-1);
        //cout << "rem " << D[j] << ": " << rem << " -> " << pw[rem] << " " << C[D[j]] << endl;
        res += pw[rem] * C[D[j]];
        res %= MOD;
