				if (s[j%vec[i]] == '1'&&s[j] == '0') {
					bl = false;
					break;
				}
			}
		}
		if (bl)cnt[vec[i]]++;
		cnt[vec[i]] %= mod;
		for (int j = vec[i] * 2; j <= n; j += vec[i])cnt[j] = (cnt[j] - cnt[vec[i]] + mod) % mod;
		ans = (ans + cnt[vec[i]] * vec[i] * 2) % mod;
	}
	cnt[n] = (cnt[n] + mod) % mod;
	ans = (ans + cnt[n] * n * 2) % mod;
	cout << ans << endl;
}

