#define MOD   (998244353LL)

ll solve(const string &x, ll n, const ll pows[],
         bool dflags[], ll dcnts[], ll d)
{
    V<ll> divlist;
    get_divisors(divlist, d);
    set<ll> dset;
    for (auto dd : divlist) dset.insert(dd);

    ll decrcnt = 0LL;
    for (auto dd : dset) if (dflags[dd]) {
        decrcnt += dcnts[dd];
        decrcnt %= MOD;
    }

    string xx = x.substr(0LL, d);
    string xxrev  = xx;
    reverse(ALL(xxrev));

    ll cnt = 0LL;
    rep (i, d) {
        if (xxrev[i] == '0') continue;
        cnt += pows[i];
        cnt %= MOD;
    }

    string xx_not;
    for (auto c : xx) xx_not += (c + 1 - (c & 1) * 2);

    string xx_all;
    ll idx = 0;
    while (xx_all.size() < n) {
        if (idx & 1LL) xx_all += xx_not;
        else xx_all += xx;
        idx++;
    }

    bool done = false;
    bool incr = false;
    rep (i, n) {
        if (x[i] != xx_all[i]) {
            if (xx_all[i] < x[i]) incr = true;
            done = true;
            break;
        }
    }
    if (!done) incr = true;
    if (incr) cnt++;
    cnt %= MOD;

    cnt -= decrcnt;
    while (cnt < 0) cnt += MOD;

    dflags[d] = true;
    dcnts[d] = cnt;

    ll ret = cnt * d * 2LL;
    return ret % MOD;
}

