const int MOD = 998244353;

int sum(int a, int b)
{
    a += b;
    if (a >= MOD) a -= MOD;
    return a;
}
int sub(int a, int b)
{
    a -= b;
    if (a < 0) a += MOD;
    return a;
}
int mult(int a, int b)
{
    return (a * 1LL * b) % MOD;
}

const int N = 2e5 + 5;

int n;
char s[N];
int x[N];
int num[N];

int g[N];

void calc(int k)
{
    if (!((n / k) & 1))
        return;

    g[k] = sum(g[k], num[k]);
    for (int i = 0; i < n; ++i)
    {
        int cur = x[i % k] ^ ((i / k) & 1);
        if (cur < x[i])
            break;
        if (cur > x[i])
            return;
    }
    g[k] = sum(g[k], 1);
}

int main()
{
    //freopen("input.txt", "r", stdin);


    scanf("%d%s", &n, s);
    int m = strlen(s);

    for (int i = 0; i < n - m; ++i)
        x[i] = 0;
    for (int i = n - m; i < n; ++i)
        x[i] = s[i - (n - m)] - '0';

    num[0] = 0;
    for (int i = 0; i < n; ++i)
        num[i + 1] = sum(mult(2, num[i]), x[i]);

    for (int k = 1; k * k <= n; ++k)
    {
        if (n % k) continue;
        calc(k);
        if (k * k != n)
            calc(n / k);
    }

    for (int i = 1; i <= n; ++i)
        for (int j = i + i; j <= n; j += i)
        {
            if (n % j == 0 && ((n / j) & 1))
                g[j] = sub(g[j], g[i]);
        }

    int ans = 0;
    for (int i = 1; i <= 2 * n; ++i)
        ans = sum(ans, mult(2 * i, g[i]));
    printf("%d", ans);

}

