const int Mod = 998244353;

int add(int a, int b) {
  return (a += b) >= Mod ? a - Mod : a;
}

int sub(int a, int b) {
  return (a -= b) < 0 ? a + Mod : a;
}

int mul(int a, int b) {
  return 1ll * a * b % Mod;
}

int fast_pow(int a, int b) {
  int res = 1;
  for (; b; b >>= 1, a = mul(a, a)) {
    if (b & 1) res = mul(res, a);
  }
  return res;
}

const int N = 2e5 + 10;

int n, pri[N], vis[N], mu[N], tot = 0;
int f[N], g[N];
char x[N], y[N];

void get_prime(int n = N - 1) {
  mu[1] = 1;
  for (int i = 2; i <= n; i++) {
    if (!vis[i]) {
      pri[++tot] = i;
      mu[i] = -1;
    }
    for (int j = 1; j <= tot && i * pri[j] <= n; j++) {
      vis[i * pri[j]] = 1;
      if (i % pri[j] == 0) {
        mu[i * pri[j]] = 0;
        break;
      } else {
        mu[i * pri[j]] = -mu[i];
      }
    }
  }
  for (int i = 1; i <= n; i++) if (mu[i] < 0) mu[i] += Mod;
}

int check(int len) {
  int res = 0;
  for (int i = 1; i <= len; i++) y[i] = x[i];
  for (int i = len + 1; i <= n; i++) {
    if (y[i - len] == '0') y[i] = '1';
    else y[i] = '0';
  }
  bool flag = 1;
  for (int i = 1; i <= n; i++) {
    if (y[i] > x[i]) {flag = 0; break;}
    if (y[i] < x[i]) {flag = 1; break;}
  }
  if (flag) res++;
  int bas = 1;
  for (int i = len; i >= 1; i--) {
    if (x[i] == '1') {
      res = add(res, bas);
    }
    bas = mul(bas, 2);
  }
  return res;
} 

int main() {
  get_prime();
  n = read();
  scanf("%s", x + 1);
  for (int i = 1; i <= n; i++) {
    if ((n % i == 0) && ((n / i) & 1)) {
      g[i] = check(i);
    }
  }
  for (int i = 1; i <= n; i++) {
    for (int j = i; j <= n; j += i) {
      f[j] = add(f[j], mul(mu[j / i], g[i]));
    }
  }  
  int ans = 0;
  for (int i = 1; i <= n; i++) {
    if ((n % i == 0) && ((n / i) & 1)) {
      ans = add(ans, mul(f[i], mul(i, 2)));
    }
  }
  printf("%d\n", ans);
  return 0;
}

