void draw_edge(int v, int u) {
	g[v].push_back(u);
	g[u].push_back(v);
}

void equal(int v, int u) {
	draw_edge(v, last);
	draw_edge(u, last);

	++last;
}

void nonequal(int v, int u) {
	draw_edge(v, u);
}

int used[MAX_V], mark = 1337;
int color[MAX_V], touched[MAX_V];
int bi;

vector<int> cc[MAX_V];
int which_cc[MAX_V];

void dfs(int v, int c, int fst) {
	used[v] = mark;
	color[v] = c;
	which_cc[v] = fst;

	if(v < n)
		cc[fst].push_back(v);

	for(auto& u: g[v]) {
		if(used[u] != mark) {
			dfs(u, c ^ 1, fst);
		} else {
			if(color[v] == color[u])
				bi = 0;
		}
	}
}

int count[MAX_PERIOD];
int pow2[MAX_PERIOD];

void precalc() {
	pow2[0] = 1;

	for(int i = 1; i < MAX_PERIOD; ++i) {
		pow2[i] = add(pow2[i - 1], pow2[i - 1]);
	}
}

void solve() {
	cin >> n >> x;
	vector<int> divs;

	for(int i = 1; i <= 2 * n; ++i) {
		if((2 * n) % i == 0)
			divs.push_back(i);
	}

	int answ = 0;

	for(auto& cycle_size: divs) {
		last = n;

		for(int v = 0; v < 2 * n + 7; ++v) {
			g[v].clear();
			cc[v].clear();
			touched[v] = 0;
		}

		std::deque<int> ind;

		for(int i = 0; i < n; ++i) {
			ind.push_back(i + 1);
		}

		for(int i = 0; i < cycle_size; ++i) {
			int lst = ind.back();
			ind.pop_back();

			ind.push_front(-lst);
		}

		for(int i = 0; i < n; ++i) {
			int j = ind[i];

			if(j > 0) {
				equal(i, j - 1);
			} else {
				nonequal(i, -j - 1);
			}
		}

		bi = 1;
		++mark;

		int fst = 0;

		for(int v = 0; v < last; ++v) {
			if(used[v] != mark) {
				dfs(v, 0, fst);
				++fst;
			}
		}

		if(bi == 0)
			continue;

		DBG(cycle_size); DBG(fst);
		int cur = fst;
		int fl = 1;

		for(int i = 0; i < n; ++i) {
			int value = x[i] - '0';

			if(touched[which_cc[i]] == 0) {
				--cur;
				touched[which_cc[i]] = 1;

				if(value == 1)
					count[cycle_size] = add(count[cycle_size], pow2[cur]);

				int ini = color[i];

				for(auto& j: cc[which_cc[i]]) {
					if(ini != value)
						color[j] ^= 1;
				}
			} else {
				DBG(color[i]); DBG(value); DBG(i);

				if(color[i] > value) {
					fl = 0;
					break;
				} else if(color[i] < value) {
					count[cycle_size] = add(count[cycle_size], pow2[cur]);
					fl = 0;
					break;
				}
			}
		}

		count[cycle_size] = add(count[cycle_size], fl);
		DBG(count[cycle_size]);
	}

	DBG("----");

	for(auto& i: divs) {
		for(auto& j: divs) {
			if(i % j != 0 || j == i)
				continue;

			count[i] = sub(count[i], count[j]);
		}
	}

	for(int cycle_size = 1; cycle_size <= 2 * n; ++cycle_size) {
		DBG(cycle_size); DBG(count[cycle_size]);
	}

	for(int i = 1; i <= 2 * n; ++i) {
		answ = add(answ, mult(count[i], i));
	}

	cout << answ << '\n';
}

