void dfs(int v, int c, int fst) {
	used[v] = mark;
	color[v] = c;
	which_cc[v] = fst;

	if(v < n)
		cc[fst].push_back(v);

	for(auto& u: g[v]) {
		if(used[u] != mark) {
			dfs(u, c ^ 1, fst);
		} else {
			if(color[v] == color[u])
				bi = 0;
		}
	}
}

int count[MAX_PERIOD];
