ll dp[202020][2];

ll rec(ll k, bool tight, ll made){
    if(dp[k][tight] >= 0) return dp[k][tight];
    if(k==made) return 1;

    ll res = 0;

    ll ub = (tight ? S[k]-'0' : 1);
    for(int d=0;d<=ub;d++){
        res += rec(k+1, ((tight && d==ub) ? true : false), made);
        res %= mod;
    }

    dp[k][tight] = res;
    return res;
}

ll calc_pos(ll d){
    ll l = N/d;
    REP(i, 202020)REP(j, 2) dp[i][j] = -1;
    ll dig = rec(0, 1, l);
    dig--;
    string T = "";
    string A = S.substr(0, l);
    string B = "";
    REP(i, l) B += (S[i]=='1' ? '0' : '1');

    REP(i, d){
        if(i%2==0) T += A;
        else T += B;
    }
    if(T<=S) dig++;
    return dig;
}

