    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> N >> S;
    vector<ll> cum(N+1, 0);
    REP(i, N) cum[i+1] = cum[i] + (S[i]=='1');

    //bit DP
    REP(i, 202020)REP(j, 2) dp[i][j] = -1;
    ll total = rec(0, 1, N);
    //cout << rec(0, true) << endl;

    vector<ll> yaku;
    for(int i=2;i<=N;i++){
        if(N%i==0 && i%2==1) yaku.push_back(i);
    }

    ll M = yaku.size();
    vector<ll> num(M, 0);

    ll res = 0;

    for(int i=M-1;i>=0;i--){
        ll d = yaku[i];
        ll l = N/d;
        ll pos = calc_pos(d);
        num[i] += pos;
        num[i] %= mod;
        for(int j=i-1;j>=0;j--){
            if(yaku[i]%yaku[j]==0){
                num[j] -= num[i];
                num[j] += mod;
                num[j] %= mod;
            }
        }
        res += (2*l*num[i])%mod;
        res %= mod;
    }
    //cout << num << endl;

    ll sum = 0;
    REP(i, M){
        sum += num[i];
        sum %= mod;
    }

    ll tmp = (total - sum + mod)%mod;
    tmp *= (2*N);
    tmp %= mod;
    res += tmp;
    res %= mod;

    cout << res << endl;

    return 0;
}

