const long MOD = 998244353;

vector<long> p2;

long calc(int n, string &s, int k) {
    long res = 0;
    for (int i = 0; i < k; i++) {
        if (s[i] == '1') {
            res += p2[k - i - 1];
            res %= MOD;
        }
    }
    bool ok = true;
    for (int i = k; i < n; i++) {
        if (s[i] > (s[i - k] ^ 1)) {
            break;
        }
        if (s[i] < (s[i - k] ^ 1)) {
            ok = false;
            break;
        }
    }
    if (ok) {
        res = (res + 1) % MOD;
    }
    return res;
}

