const int64_t kRem = 998244353;

int64_t pow_rem(int64_t x, int64_t m, int64_t rem)
{
	if (m == 0) {
		return 1;
	}
	if (m == 1) {
		return x;
	}

	if (m & 1) {
		int64_t val = pow_rem(x, m / 2, rem);
		val = val * val;
		val %= rem;
		val *= x;
		val %= rem;
		return val;
	}
	else {
		int64_t val = pow_rem(x, m / 2, rem);
		val = val * val;
		val %= rem;
		return val;
	}
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	int n; cin >> n;
	string s; cin >> s;

	vector<int64_t> minus_rem(n);

	int64_t minus = 0;
	FOR_LT(i, 1, n) {
		if (n % i != 0) continue;
		if (!((n / i) & 1)) continue;

		int64_t m = 0;
		int v = 1;
		FOR_LT(j, 0, i) {
			if (s[i - 1 - j] == '1') {
				m += v;
				m %= kRem;
			}
			v *= 2;
			v %= kRem;
		}

		bool is_ng = false;
		FOR_LT(j, 0, n) {
			int p = (j / i);
			int pr = j % i;

			char pc = ' ';
			if (p & 1) {
				if (s[pr] == '1') {
					pc = '0';
				}
				else {
					pc = '1';
				}
			}
			else {
				if (s[pr] == '1') {
					pc = '1';
				}
				else {
					pc = '0';
				}
			}

			if (s[j] > pc) {
				break;
			}
			if (s[j] < pc) {
				is_ng = true;
				break;
			}
		}
		if (!is_ng) m++;

		m -= minus_rem[i];
		if (m < 0) m += kRem;

		for (int j = i * 2; j < n; j += i) {
			minus_rem[j] += m;
			minus_rem[j] %= kRem;
		}

		minus += (m * (2 * n - 2 * i));
		minus %= kRem;
	}

	int64_t m = 1;
	{
		int v = 1;
		FOR_LT(i, 0, n) {
			if (s[n - 1 - i] == '1') {
				m += v;
				m %= kRem;
			}
			v *= 2;
			v %= kRem;
		}
	}

	int64_t ans = m * (n * 2) % kRem;

	ans -= minus;
	if (ans < 0) ans += kRem;

	cout << ans << endl;

	return 0;
}

