    vector<ll> state;
    for(ll i = 1; i <= n; i++){
        if(n % i == 0 && (n / i) % 2 == 1){
            state.push_back(i);
        }
    }
    return state;
}

bool judgeJust(string x, ll pos){
    string t[2];
    t[0] = x.substr(0, pos);
    string t2;
    for(int i = 0; i < pos; i++){
        if(x[i] == '1'){
            t2 += '0';
        }
        else{
            t2 += '1';
        }
    }
    t[1] = t2;

    for(int i = 0; i < x.length() / pos; i++){
        for(int j = 0; j < t[0].length(); j++){
            if(x[i * pos + j] > t[i%2][j]){
                return true;
            }
            else if(x[i * pos + j] < t[i%2][j]){
                return false;
            }
        }
    }
    return true;
}


int main(){
