    ll num = 0;
    ll already[210000];  fill(already, already+210000, 0);
    ll res = 0;
    ll total = 0;

    for(ll i = 1; i <= N; i++){
        num = add(mul(num, 2), (x[i - 1] - '0'));
        if(N % i == 0 && (N / i) % 2 == 1) {
            ll count = num;
            if (judgeJust(x, i)) {
                count++;
            }
            count = sub(count, already[i]);
            total = add(total, count);
            res = add(res, mul(count, 2 * i));

            ll now = i;
            while (now <= N) {
                already[now] = add(already[now], count);
                now += i;
            }
        }
    }

    cout << res << endl;

    return 0;
}

