using namespace std;

int period(int K, int N) {

	long long int x = K;
	int cnt = 0;

	for (;;) {
		if (x % 2 == 1) { x = (x - 1) / 2; }
		else { x = x / 2 + ((long long int) 1 << (N - 1)); }
		cnt++;
		if (x == K) { break; }
	}
	return cnt;
}

