    t=0;
    for(j=1;j*j<=i;j++){
      if(j==i){continue;}
      if(i%j!=0){continue;}
      t+=dp[j];t%=mod;
    }
    t=mod-t;
    t%=mod;
    c=0;
    for(j=0;j<i;j++){
      c*=2;c%=mod;
      c+=(s[j]-'0');c%=mod;
      att[j]=s[j];
    }
    for(j=i;j<l;j++){
      att[j]=('0'+'1'-att[j-i]);
    }
    //printf("%lld %lld\n",i,lit(att,i));
    if(comp(s,att,l)!=1 || lit(att,i)==i){
      c++;
      c%=mod;
    }
    c+=t;c%=mod;
    dp[i]=c;
    c*=((n-i)*2);
    c%=mod;
    r+=mod;
    r-=c;
    r%=mod;
  }
  printf("%lld\n",r);
  return 0;
}

