long long comp(char s[],char t[],long long l){
  long long i;
  for(i=0;i<l;i++){
    if(s[i]>t[i]){return -1;}
    if(s[i]<t[i]){return 1;}
  }
  return 0;
}

long long lit(char s[],long long l){
  long long i,j,pos,w=l;
  for(pos=0;pos<l;pos++){
    for(i=1;i*i<=l;i++){
      if(l%i!=0){continue;}
      if(i!=1){while(w%i==0){w/=i;}}
      for(j=i;j<l;j++){
        if(s[(j+pos)%l]==s[(j+pos-i)%l]){break;}
        if(j==l-1){return i;}
      }
    }
    i=w;
    for(j=i;j<l;j++){
      if(s[(j+pos)%l]==s[(j+pos-i)%l]){break;}
      if(j==l-1){return i;}
    }
  }
  return l;
}

