long long getdiv(long long x,long long res[]){
  long long c=0,i;
  for(i=1;i*i<=x;i++){
    if(x%i!=0){continue;}
    res[c]=i;c++;
    if(i*i==x){continue;}
    res[c]=x/i;c++;
  }
  return c;
}

