public class Main implements Runnable{

	private void solve(FastIO io) {
		/*
		 * author: 31536000
		 * AGC039 C問題
		 * 考察メモ
		 * まず、基本的にどんな数も周期2N
		 * ただ、一部だけもっと小さい周期のものがある
		 * その周期をkとすると、まずkは偶数じゃないと矛盾だね
		 * で、gcd(N, k)=k/2の時だけが上手くいくっぽい
		 * kで割り切れるとどうしても矛盾が起きるので、k/2について奇数個欲しい
		 * そうするといい感じにk/2個、次にbit反転したk/2個……で構築できる
		 * これの自由度は2^(k/2)、先頭k/2個を決めると全てが定まる
		 * これは実際に調べれば良いので～
		 * あ、ただ重複があるから包除原理が必須だね
		 *
		 */
		int N = io.nextInt();
		char[] X = io.next().toCharArray();
		ModUtility mod = new ModUtility(998244353);
		ModInteger[] Xdigit = new ModInteger[N + 1];
		Xdigit[0] = mod.create(0); // 累積和であることに注意
		for (int i = 0;i < N;++ i) {
			Xdigit[i + 1] = Xdigit[i].multiply(2);
			if (X[i] == '1') Xdigit[i + 1].addEqual(1);
		}
		ModInteger ans = mod.create(1).addEqual(Xdigit[N]); // 0以上X以下、なのでX+1個ある
		ans.multiplyEqual(2 * N); // これが周期が存在しないと仮定したときの答え
		ModInteger[] calc = new ModInteger[N + 1];
		for (int i = 1;i < N;++ i) {
			calc[i] = mod.create(0);
			if (IntegerMath.gcd(N, 2 * i) == i) { // このパターンのみが構築可能
				calc[i] = Xdigit[i].add(1); // 0から第i桁目のXまで、これがそのまま作れるかもしれない(最後だけチェックがいる)
				for (int j = 2;j * j <= i;++ j) if (i % j == 0) calc[i].subtractEqual(calc[j]).subtractEqual(calc[i / j]); // 重複の削除、包除原理
				for (int j = i;j < N;++ j) { // 最初i桁が同値のものだけ、本当に作れるか検証が必要
					char num;
					if (j % (2 * i) < i) num = X[j % i];
					else num = X[i - j % i - 1] == '0' ? '1' : '0'; // bit反転
					if (num != X[j]) { // そこで結果が定まる
						calc[i].subtractEqual(num - '0'); // 本来0のところに1、つまり超過したときだけ-1しておく
						break;
					}
				}
				ans.subtractEqual(calc[i].multiply(N - i).multiply(2));
			}
		}
		io.println(ans);

	}

