                for (int j = 0; j < i; j++) {
                    if (x[j] == '1') {
                        qty[i] += pow[i - j - 1];
                        current[j] = '1';
                    } else {
                        current[j] = '0';
                    }
                }
                boolean good = true;
                for (int j = i; j < n; j++) {
                    int at = '1' + '0' - current[j - i];
                    if (at > x[j]) {
                        good = false;
                        break;
                    } else if (at < x[j]) {
