		 * @param a 整数
		 * @param b 整数
		 * @return aとbのうち小さい方の値
		 */
		public static int min(int a, int b) {
			return a < b ? a : b;
		}

		/**
		 * 配列の中で最小の値を返します。
		 * @param array 配列
		 * @return 配列の中で最小の値
		 */
		public static int min(int... array) {
			int ret = array[0];
			for (int i = 1;i < array.length;++ i) ret = min(ret, array[i]);
			return ret;
		}

		/**
		 * aとbのうち、大きい方を返します。
