	 */
	public static class IntegerMath {
		private IntegerMath() {
			throw new AssertionError();
		}


		/**
		 * aとbのうち、小さい方を返します。
		 * @param a 整数
		 * @param b 整数
		 * @return aとbのうち小さい方の値
		 */
		public static int min(int a, int b) {
			return a < b ? a : b;
		}

		/**
		 * 配列の中で最小の値を返します。
		 * @param array 配列
		 * @return 配列の中で最小の値
		 */
		public static int min(int... array) {
			int ret = array[0];
			for (int i = 1;i < array.length;++ i) ret = min(ret, array[i]);
			return ret;
		}

		/**
		 * aとbのうち、大きい方を返します。
		 * @param a 整数
		 * @param b 整数
		 * @return aとbのうち大きい方の値
		 */
		public static int max(int a, int b) {
			return a > b ? a : b;
		}

		/**
		 * 配列の中で最大の値を返します。
		 * @param array 配列
		 * @return 配列の中で最大の値
		 */
		public static int max(int... array) {
			int ret = array[0];
			for (int i = 1;i < array.length;++ i) ret = max(ret, array[i]);
			return ret;
		}

		/**
		 * aとbの最大公約数を返します。
		 * @param a 整数
		 * @param b 整数
		 * @return 最大公約数
		 */
		public static int gcd(int a, int b) {
			while (a != 0) if ((b %= a) != 0) a %= b; else return a;
			return b;
		}

		/**
		 * 配列全ての値の最大公約数を返します。
		 * @param array 配列
		 * @return 最大公約数
		 */
		public static int gcd(int... array) {
			int ret = array[0];
			for (int i = 1;i < array.length;++ i) ret = gcd(ret, array[i]);
			return ret;
		}

		/**
		 * 配列全ての値の最小公倍数を返します。
		 * @param a 整数
		 * @param b 整数
		 * @return 最小公倍数
		 */
		public static int lcm(int a, int b) {
			return a / gcd(a, b) * b;
		}

		/**
		 * 配列全ての値の最小公倍数を返します。
		 * @param array 配列
		 * @return 最小公倍数
		 */
		public static int lcm(int... array) {
			int ret = array[0];
			for (int i = 1;i < array.length;++ i) ret = lcm(ret, array[i]);
			return ret;
		}

		/**
		 * aのb乗を返します。
		 * @param a 整数
		 * @param b 整数
		 * @return aのb乗
		 */
		public static int pow(int a, int b) {
			int ans = 1;
			for (int mul = a;b > 0;b >>= 1, mul *= mul) if ((b & 1) != 0) ans *= mul;
			return ans;
		}

		/**
		 * aのb乗をmodを法として計算したものを返します。
		 * @param a 整数
		 * @param b 整数
		 * @param mod 法
		 * @return aのb乗をmodを法として計算したもの
		 */
		public static int pow(int a, int b, int mod) {
			if (b < 0) b = b % (mod - 1) + mod - 1;
			long ans = 1;
			for (long mul = a;b > 0;b >>= 1, mul = mul * mul % mod) if ((b & 1) != 0) ans = ans * mul % mod;
			return (int)ans;
		}

		/**
		 * aをbで割った値を、端数に関してはRoundingModeに従って計算します。
		 * @param a 整数
		 * @param b 整数
		 * @param mode 端数の処理方法
		 * @return a/b
		 * @throws ArithmeticException 不正引数
		 */
		public static int divide(int a, int b, RoundingMode mode) {
			int t;
			switch (mode) {
				case UP:
					t = (a >>> 31 << 1) - 1;
					return (a - t) / b + t;
				case DOWN:
					return a / b;
				case CEILING:
					t = ~a >>> 31;
					return (a - t) / b + t;
				case FLOOR:
					t = a >>> 31;
					return (a + t) / b - t;
				case HALF_UP:
					t = a % b;
					break;
				case HALF_EVEN:
					break;
				case HALF_DOWN:
					break;
				case UNNECESSARY:
					throw new ArithmeticException();
			}
			throw new AssertionError("undefined mode");
		}

		public static int sum(int... array) {
			int ret = 0;
			for (int i : array) ret += i;
			return ret;
		}

		public static int multiply(int... array) {
			int ret = 0;
			for (int i : array) ret *= i;
			return ret;
		}

		public static int nextMultiple(int a, int b) {
			return divide(a, b, RoundingMode.CEILING) * b;
		}

		public static int mod(int a, int mod) {
			return (a %= mod) < 0 ? a + mod : a;
		}

