internal partial class Solver {
    public void Run() {
        var n = ni();
        var X = ns();

        cout.WriteLine(Solve(n, X));
    }

    private long Solve(int n, string x) {
        int mod = 998244353;
        // A(BA)* のとき |A| * 2 が周期
        var pattern = new long[n + 1];
        long ans = 0;

        for (int i = 1; i <= n; i++) {
            var t = n / i; // must be odd
            if (i * t != n) continue;
            if (t % 2 == 0) continue;
            long p = 0;

            for (int j = 0; j < i; j++) {
                p = p * 2 + (x[j] - '0');
                p %= mod;
            }

            var s = new char[n];
            for (int j = 0; j < i; j++) {
                s[j] = x[j];
            }
            for (int j = i; j < n; j++) {
                s[j] = (s[j - i] == '0' ? '1' : '0');
            }

            if (string.CompareOrdinal(new string(s), x) <= 0) {
                p++;
            }

            for (int j = 1; j < i; j++) {
                if (i % j == 0) {
                    p = (p - pattern[j] + mod) % mod;
                }
            }
            pattern[i] = p % mod;
            ans += p * i * 2;
            ans %= mod;
        }

        return ans;
    }
}

