            for (int j = i + 1; j < N; j++)
            {
                max = Math.Max(max, Dist[i, j]);
            }
        }

        Console.WriteLine(max+1);
    }

    private bool Search(int pos, int d)
    {
        if (D[pos] != -1)
        {
            if (D[pos] % 2 == d % 2)
            {
                return true;
            }
            else
            {
                return false;
            }
        }
        else
        {
            D[pos] = d;
            foreach (int i in Edge[pos])
            {
                if (!Search(i, d + 1))
                {
                    return false;
                }
            }
        }

        return true;
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

