using System;
using System.Collections.Generic;
using System.Linq;
using CompLib.Mathematics;
using CompLib.Util;

public class Program
{
    private int N;
    private bool[] X;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        X = sc.Next().Select(c => c == '1').ToArray();

        /*
         * 奇数 1桁ずらす
         * 偶数 1桁ずらす、一番上1追加
         *
         * 一番下の桁を反転して一番上に
         * 2週すれば必ず元に戻る
         *
         * 例1
         * 0,1,3,4,6,7 6回
         * 2,5         2回
         * 6*6 + 2*2 = 40
         *
         * 
         * 
         * 2m回で戻る 長さmの部分列、反転が交互に
         * mはNの約数
         * 
         */

        List<int> div = new List<int>();
        {
            List<int> r = new List<int>();
            for (int i = 1; i * i <= N; i++)
            {
                if (N % i == 0)
                {
                    div.Add(i);
                    if (i != N / i) r.Add(N / i);
                }
            }

            for (int i = r.Count - 1; i >= 0; i--)
            {
                div.Add(r[i]);
            }
        }

        ModInt[] cnt = new ModInt[div.Count];
        for (int i = 0; i < div.Count; i++)
        {
            // i桁2進 反転... 交互
            // 最大
            // 上位div[i]桁そのままができるか?
            int d = div[i];
            if ((N / d) % 2 == 0) continue;
            bool f = true;
            for (int j = d; j < N; j++)
            {
                int dd = j / d;
                int mm = j % d;

                if ((X[mm] ^ (dd % 2 == 1)) && !X[j])
                {
                    f = false;
                    break;
                }

                if ((X[mm] ^ (dd % 2 == 0)) && X[j])
                {
                    break;
                }
            }

            ModInt p = 0;
            for (int j = 0; j < d; j++)
            {
                p *= 2;
                if (X[j]) p += 1;
            }

            if (!f)
            {
                // できない
                // 上位d桁-1
                p -= 1;
            }

            // 交互にp個できる
            cnt[i] += p + 1;
            for (int j = i + 1; j < div.Count; j++)
            {
                if (div[j] % d == 0 && (div[j] / d) % 2 == 1)
                {
                    cnt[j] -= cnt[i];
                }
            }
        }

        ModInt ans = 0;
        for (int i = 0; i < div.Count; i++)
        {
            ans += 2 * div[i] * cnt[i];
        }

        Console.WriteLine(ans);
    }

    public static void Main(string[] args) => new Program().Solve();
}

