func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	n := r.nextInt()
	a := make([]int, n)
	s := 0
	for i := 0; i < n; i++ {
		r.Scan(true)
		a[i] = r.nextInt()
		s += a[i]
	}

	ok := true

	if a[0] != 0 {
		ok = false
	} else {
		for i := 1; i < n; i++ {
			if a[i-1] < a[i] {
				if a[i]-a[i-1] > 1 {
					ok = false
					break
				}
			}
		}
	}

	ans := -1
	if ok {
		notErase := 0
		preNotEraseIdx := 0
		for i := 1; i <= n; i++ {
			if i == n || a[i-1] >= a[i] {

				n := a[i-1] - 1
				notErase += n * (n + 1) / 2
				notEraseIdx := i - 1
				n = preNotEraseIdx - (notEraseIdx - n) + 1
				if n > 0 {
					notErase -= n * (n + 1) / 2
				}
				preNotEraseIdx = notEraseIdx
			}
		}
		ans = s - notErase
	}

	fmt.Fprintln(stdout, ans)
}

