    A := 0
    for i := n - 1; 0 <= i; i-- {
      A = (A + B[n - i] * X[i]) % p
    }
    return A
  }
  LE := func(Y []int) bool {
    for i := 0; i < N; i++ {
      if X[i] != Y[i] { return Y[i] < X[i] }
    }
    return true
  }
  ans := 2 * N * (F(N) + 1) % p
  D := make([]int, 0)
  for k := 1; 3 * k <= N; k++ {
    if N % (2 * k) == k { D = append(D, k) }
  }
  C := make([]int, len(D))
