		long m = pa.length; // たとえば n = 6, d = 3, m = 2
		foreach(i, c; total){
			long j = i % m;
			long k = i / m;
			char c1;
			if(k % 2 == 0) c1 = pa[j];
			else c1 = (pa[j] == '0')? '1': '0';
			if(c1 == '0' && c == '1') return true;
			if(c1 == '1' && c == '0') return false;
		}
		return true;
	}

