use std::io::Read;

fn run() {
    let mut s = String::new();
    std::io::stdin().read_to_string(&mut s).unwrap();
    let mut it = s.trim().split_whitespace();
    let n: usize = it.next().unwrap().parse().unwrap();
    let s: Vec<usize> = it.next().unwrap().chars().map(|c| c.to_digit(10).unwrap() as usize).collect();
    let mut map = std::collections::BTreeMap::<usize, ModInt>::new();
    for d in (1..(n + 1)).rev() {
        if n % d != 0 || d % 2 == 0{
            continue;
        }
        let w = n / d;
        let mut dp = vec![ModInt::one(), ModInt::zero()];
        for &c in s[..w].iter() {
            let mut next = vec![ModInt::zero(); 2];
            next[1] += dp[1];
            next[1] += dp[1];
            if c == 1 {
                next[1] += dp[0];
            }
            next[0] += dp[0];
            dp = next;
        }
        for (&a, &b) in s.iter().zip(s[w..].iter()) {
            if (a ^ 1) > b {
                dp[0] = ModInt::zero();
            }
            if (a ^ 1) < b {
                break;
            }
        }
        let mut cnt = dp[0] + dp[1];
        for (k, v) in map.iter() {
            if w % k == 0 {
                cnt -= *v;
            }
        }
        map.insert(w, cnt);
    }
    let mut ans = ModInt::zero();
    for (k, v) in map.into_iter() {
        ans += ModInt((2 * k) as u32) * v;
    }
    println!("{}", ans);
}

fn main() {
    run();
}

