fn rotate(mut a: Vec<char>) -> Vec<char> {
    let n = a.len();
    let tmp = a[n-1];
    for i in (1..n).rev() {
        a[i] = a[i-1];
    }
    a[0] = ifv!(tmp == '0', '1', '0');
    a
}

fn check(mut a: Vec<char>) -> usize {
    let mut b = a.clone();
    let mut cnt = 0;
    while true {
        a = rotate(a);
        cnt += 1;
        if a == b {
            return cnt
        }
    }
    0
}

const MOD: i64 = 998244353;

fn count_less(x: &Vec<char>) -> i64 {
    let n = x.len();
    let mut ret = 0;
    for i in 0..n {
        ret = ret * 2 + ifv!(x[i] == '1', 1, 0);
        ret %= MOD;
    }
    (ret + 1) % MOD
}

fn count_ptn(x: &Vec<char>, gl: usize) -> i64 {
    let mut dp = dvec!(0; gl+1, 2);
    dp[0][0] = 1;
    for idx in 0..gl {
        for f in 0..2 {
            let mut base = dp[idx][f];
            for c in 0..2 {
                let mut tf = f;
                if c == 0 && x[idx] == '1' {
                    tf = 1;
                }
                if f == 0 && x[idx] == '0' && c == 1 {
                    continue;
                }
                dp[idx+1][tf] += base;
                dp[idx+1][tf] %= MOD;
            }
        }
    }

    let n = x.len();
    let mut big = false;
    for i in 0..n {
        let c = i / gl;
        let mut wo = x[i%gl];
        if c % 2 == 1 {
            wo = ifv!(wo == '1', '0', '1');
        }
        if wo == '1' && x[i] == '0' {
            big = true;
            break;
        } else if wo == '0' && x[i] == '1' {
            break;
        }
    }

    (dp[gl][1] + ifv!(big, 0, 1)) % MOD
}

