use self::mod_int::ModInt;

const MOD: usize = 998244353;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let x: Vec<usize> = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - '0' as usize)
        .collect();
    let mut sum = ModInt(0);
    let mut ans = vec![ModInt(0); n + 1];
    for k in 1..(n + 1) {
        if n % k == 0 && n % (2 * k) != 0 {
            ans[k] += solve(&x, k);
            sum += ans[k] * 2 * k;

            let mut cur = k * 2;
            let tmp = ans[k];
            while cur <= n {
                ans[cur] -= tmp;
                cur += k;
            }
        }
    }

    println!("{}", sum.0);
}

fn solve(x: &Vec<usize>, k: usize) -> ModInt<usize> {
    let n = x.len();
    assert_eq!(n % k, 0);
    assert_ne!(n % (2 * k), 0);

    let mut dp = vec![ModInt(1), ModInt(0)];
    for i in 0..k {
        let mut next = vec![ModInt(0); 2];
        for next_digit in 0..2 {
            for lower in 0..2 {
                if lower == 0 && x[i] < next_digit {
                    continue;
                }
                let next_lower = if lower == 1 || x[i] > next_digit {
                    1
                } else {
                    0
                };
                next[next_lower] += dp[lower];
            }
        }
        dp = next;
    }

    let mut lower = false;
    for i in 0..n {
        let y = if (i % (2 * k)) / k == 0 {
            x[i % k]
        } else {
            x[i % k] ^ 1
        };
        if y > x[i] {
            break;
        }
        if y < x[i] {
            lower = true;
            break;
        }
        if i == n - 1 {
            lower = true;
        }
    }

    if lower {
        dp[0] + dp[1]
    } else {
        dp[1]
    }
}

