const MOD: usize = 998244353;
use mod_int::ModInt;

// https://qiita.com/tanakh/items/0ba42c7ca36cd29d0ac8
macro_rules! input {
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, [ $t:tt ]) => {{
        let len = read_value!($next, usize);
        (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    }};

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

fn solve() {
    input! {
        n: usize,
        s: chars,
    }
    let x: Vec<usize> = s.into_iter().map(|c| if c=='0' {0} else {1}).collect();
    let mut sum = ModInt(0);
    let mut ans = ModInt(0);
    let mut book: HashMap<usize, usize> = HashMap::new();
    for i in 1..n+1{
        sum = sum * 2 + ModInt(x[i-1]);
        let block = i;
        if n%i!=0 {continue;}
        let num = n/i;
        if num%2==0 {continue;}
        let mut v = 1;
        for j in 0..n{
            let tmp = x[j];
            let mut val = x[j%block];
            if j/block%2==1 {
                val = 1 - val;
            }
            if tmp > val { break;}
            if tmp < val { v = 0; break;}
        }
        let mut cnt = sum + v;
        if let Some(&r) = book.get(&block){
            cnt -= r;
        }
        // println!("{} {} {}", sum.0, i, cnt.0);
        ans += cnt * block * 2;
        let mut y = block;
        while y <= n {
            y += block;
            if book.contains_key(&y) {book.insert(y, (cnt + *book.get(&y).unwrap()).0);}
            else {book.insert(y, cnt.0 );}
        }
    }
    println!("{}", ans.0);

}

pub mod mod_int {
