        ModInt {
            val: ModInt::val_from_addval(self.val - rhs.val + M)
        }
    }
}
impl std::ops::Sub<i64> for ModInt {
    type Output = ModInt;
    fn sub(self, rhs: i64) -> ModInt {
        self - ModInt::new(rhs)
    }
}
impl std::ops::SubAssign for ModInt {
    fn sub_assign(&mut self, other: ModInt) {
        self.val = ModInt::val_from_addval(self.val - other.val + M);
    }
}
impl std::ops::SubAssign<i64> for ModInt {
    fn sub_assign(&mut self, other: i64) {
        self.val = ModInt::val_from_i64(self.val - other);
    }
}

impl std::ops::Neg for ModInt {
    type Output = ModInt;
    fn neg(self) -> ModInt {
        ModInt {
            val: if self.val == 0 { 0 } else { M - self.val },
        }
    }
}

impl std::ops::Mul for ModInt {
    type Output = ModInt;
    fn mul(self, rhs: ModInt) -> ModInt {
        ModInt {
            val: self.val * rhs.val % M,
        }
    }
}
impl std::ops::Mul<i64> for ModInt {
    type Output = ModInt;
    fn mul(self, rhs: i64) -> ModInt {
        self * ModInt::new(rhs)
    }
}

impl std::ops::Div for ModInt {
    type Output = ModInt;
    fn div(self, rhs: ModInt) -> ModInt {
        self * rhs.inv()
    }
}
impl std::ops::Div<i64> for ModInt {
    type Output = ModInt;
    fn div(self, rhs: i64) -> ModInt {
        self / ModInt::new(rhs)
    }
}

impl std::fmt::Display for ModInt {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.val)
    }
}

//#[proconio::fastout]
fn main() {
    input! {
        n: usize,
        mut s:Bytes,
    }

    // 右ローテートして最上位を反転
    // N回繰り返すと元の値を全ビット反転したものになる
    // pattern !pattern pattern !pattern ... pattern の形 で 周期T=|pattern|*2
    // T = N÷奇数

    /*
        X = 100110...
        (prefix,T) -> パターン数を計算する

              prefix  0     1000     10010    ...
        T/2=1         0     -        -
        T/2=2         0x    -        -
        T/2=3         0xx   100      -
        T/2=4         0xxx  1000     -
        ...
        みたいな表を作る

    */
    let mut pow2 = Vec::with_capacity(n + 1);
    let mut x = M1;
    for _i in 0..=n {
        pow2.push(x);
        x = x + x;
    }
    let mut pat_lens = Vec::new();
    let mut counts = Vec::new();

    for pat_len in 1..=n {
        if n % pat_len == 0 && (n / pat_len) % 2 == 1 {
            let mut j = 0;
            let mut b = 0;
            let mut count = M0;
            for i in 0..n {
                // この時点で[0..i-1] がパターンに一致することは確認済みとする。
                if s[i] == b'1' {
                    s[i] = b'0';
                    // [0..i] がパターンに一致するなら、何パターンあるかを調べる
                    if i >= pat_len {
                        if s[i] == s[j] ^ b {
                            count += 1;
                        }
                    } else {
                        count += pow2[pat_len - (i + 1)];
                    }
                    s[i] = b'1';
                }

                // [0..i] が一致するかどうかを調べる
                if i >= pat_len {
                    if s[i] != s[j] ^ b {
                        break;
                    }
                }

                // ちょうどXの値で一致したら +1パターン
                if i == n - 1 {
                    count += 1;
                }

                // (b,j)++
                j += 1;
                if j == pat_len {
                    j = 0;
                    b = 1 - b;
                }
            }
            pat_lens.push(pat_len);
            counts.push(count);
        }
    }

    let l = pat_lens.len();
    //for i in 0..l {
    //    println!("pat_len={} count={} sum={}", pat_lens[i], counts[i], counts[i]*(pat_lens[i] as i64)*2);
    //}

    // 重複してカウントしたものを除く
    for i in 0..l {
        let pat_len = pat_lens[i];
        let count = counts[i];

        for j in i+1 .. l {
            if pat_lens[j] % pat_len == 0 && (pat_lens[j] / pat_len) % 2 == 1 {
                counts[j] -= count;
            }
        }
    }

    let mut ans = M0;
    for i in 0..l {
        ans += counts[i]*(pat_lens[i] as i64)*2;
    }
    println!("{}", ans);
}

use self::mod_int::ModInt;

const MOD: usize = 998244353;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let x: Vec<usize> = sc
        .read::<String>()
        .chars()
        .map(|c| c as usize - '0' as usize)
        .collect();
    let mut sum = ModInt(0);
    let mut ans = vec![ModInt(0); n + 1];
    for k in 1..(n + 1) {
        if n % k == 0 && n % (2 * k) != 0 {
            ans[k] += solve(&x, k);
            sum += ans[k] * 2 * k;

            let mut cur = k * 2;
            let tmp = ans[k];
            while cur <= n {
                ans[cur] -= tmp;
                cur += k;
            }
        }
    }

    println!("{}", sum.0);
}

fn solve(x: &Vec<usize>, k: usize) -> ModInt<usize> {
    let n = x.len();
    assert_eq!(n % k, 0);
    assert_ne!(n % (2 * k), 0);

    let mut dp = vec![ModInt(1), ModInt(0)];
    for i in 0..k {
        let mut next = vec![ModInt(0); 2];
        for next_digit in 0..2 {
            for lower in 0..2 {
                if lower == 0 && x[i] < next_digit {
                    continue;
                }
                let next_lower = if lower == 1 || x[i] > next_digit {
                    1
                } else {
                    0
                };
                next[next_lower] += dp[lower];
            }
        }
        dp = next;
    }

    let mut lower = false;
    for i in 0..n {
        let y = if (i % (2 * k)) / k == 0 {
            x[i % k]
        } else {
            x[i % k] ^ 1
        };
        if y > x[i] {
            break;
        }
        if y < x[i] {
            lower = true;
            break;
        }
        if i == n - 1 {
            lower = true;
        }
    }

    if lower {
        dp[0] + dp[1]
    } else {
        dp[1]
    }
}

pub mod mod_int {
    use super::MOD;
    use std::ops::{Add, AddAssign, Div, DivAssign, Mul, MulAssign, Sub, SubAssign};

    type Num = usize;

    #[derive(Clone, Copy)]
    pub struct ModInt<T: Copy + Clone>(pub T);

    impl Add<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn add(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self + rhs.0
        }
    }

    impl Add<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn add(self, mut rhs: Num) -> ModInt<Num> {
            if rhs >= MOD {
                rhs %= MOD;
            }
            let mut t = rhs + self.0;
            if t >= MOD {
                t = t - MOD;
            }
            ModInt(t)
        }
    }

    impl Sub<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn sub(self, rhs: Num) -> ModInt<Num> {
            let rhs = if rhs >= MOD { rhs % MOD } else { rhs };
            let value = if self.0 < rhs { self.0 + MOD } else { self.0 };
            ModInt(value - rhs)
        }
    }

    impl Sub<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn sub(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self - rhs.0
        }
    }

    impl AddAssign<Num> for ModInt<Num> {
        fn add_assign(&mut self, other: Num) {
            *self = *self + other;
        }
    }
    impl AddAssign<ModInt<Num>> for ModInt<Num> {
        fn add_assign(&mut self, other: ModInt<Num>) {
            *self = *self + other;
        }
    }

    impl SubAssign<Num> for ModInt<Num> {
        fn sub_assign(&mut self, other: Num) {
            *self = *self - other;
        }
    }

    impl SubAssign<ModInt<Num>> for ModInt<Num> {
        fn sub_assign(&mut self, other: ModInt<Num>) {
            *self = *self - other;
        }
    }

    impl Div<Num> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn div(self, mut rhs: Num) -> ModInt<Num> {
            if rhs >= MOD {
                rhs %= MOD;
            }
            self * ModInt(rhs).pow(MOD - 2)
        }
    }

    impl Div<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;
        fn div(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self / rhs.0
        }
    }

    impl DivAssign<Num> for ModInt<Num> {
        fn div_assign(&mut self, rhs: Num) {
            *self = *self / rhs
        }
    }
    impl DivAssign<ModInt<Num>> for ModInt<Num> {
        fn div_assign(&mut self, rhs: ModInt<Num>) {
            *self = *self / rhs
        }
    }

    impl Mul<ModInt<Num>> for ModInt<Num> {
        type Output = ModInt<Num>;

        fn mul(self, rhs: ModInt<Num>) -> ModInt<Num> {
            self * rhs.0
        }
    }
    impl Mul<Num> for ModInt<Num> {
        type Output = ModInt<Num>;

        fn mul(self, mut rhs: Num) -> ModInt<Num> {
            if rhs >= MOD {
                rhs %= MOD;
            }
            let t = (self.0 * rhs) % MOD;
            ModInt(t)
        }
    }

    impl MulAssign<Num> for ModInt<Num> {
        fn mul_assign(&mut self, rhs: Num) {
            *self = *self * rhs;
        }
    }

    impl MulAssign<ModInt<Num>> for ModInt<Num> {
        fn mul_assign(&mut self, rhs: ModInt<Num>) {
            *self = *self * rhs;
        }
    }

    impl ModInt<Num> {
        pub fn new(v: Num) -> Self {
            Self(v % MOD)
        }

        pub fn pow(self, e: Num) -> ModInt<Num> {
            let mut result = ModInt(1);
            let mut cur = self;
            let mut e = e;
            while e > 0 {
                if e & 1 == 1 {
                    result *= cur;
                }
                e >>= 1;
                cur *= cur;
            }
            result
        }
    }
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
